import { AnimalType, Dialogue, DialoguePhase } from '../../types/homeWorld';

/**
 * All dialogue content organized by animal and phase
 * Each animal has a unique personality that evolves from contentment to existential crisis
 * 134 dialogues per animal (24/28/22/30/30 across phases 0-4, plus 20
 * post-revelation) to support extended dialogue sessions
 */

// RED PANDA (Bamboo) - Zen practitioner whose enlightenment leads to unsettling truths
const RED_PANDA_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'rp_0_1', text: "Come up. Catch your breath first, those stairs are steep.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_2', text: "I picked this room for the morning light. By afternoon the sun has moved off the mat, and I'm still deciding whether to move with it.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_3', text: "My name is Bamboo. The plant beside me is also bamboo. Only one of us needs watering.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_4', text: "Sit wherever you fit. If the cushions are in your way, I'll move them.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_5', text: "The incense was a gift out of Archimedes' crate. I should have asked him how slowly I was meant to burn it.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_6', text: "I sat down to count my breaths. Then I got interested in the counting and forgot the breathing.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_7', text: "One reed in my mat has worked loose, and it rattles. I keep meaning to tie it down. Now I think I'd miss the noise.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_8', text: "Tea first. My opinions get much less urgent while I wait for the cup to cool.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_9', text: "From up here you can see the whole house, including every room you helped add.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_10', text: "Sitting still comes much easier once the washing-up is done.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_11', text: "I left the crate open. It smells of old paper and incense at once. That's better company than you'd think.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_12', text: "The bamboo leaves lean after the light all day. I shift the pot around so they don't have to bend so far.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_13', text: "You can talk if you want to. A quiet room isn't a rule against company.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_14', text: "I picked my name because it was simple. Nothing else about my life has taken the hint.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_15', text: "Sometimes I want the answer before I've given the question any time at all.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_16', text: "The mat needs a good beating. I've decided that counts as meditation, the vigorous kind.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_17', text: "I can see Thyme's garden from up here. It looks very neat from above. At ground level it is far more complicated.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_18', text: "Hold your cup in both hands. That's a good enough place to start.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_19', text: "I spilled tea on my one page of teachings. What's left is shorter, and honestly clearer.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_20', text: "The incense smoke leaned toward the gap in the roof, and there was no draught at all. I opened the window to see if it would lean the other way.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_21', text: "Rest if you're tired. You don't have to be wise about it.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_22', text: "You don't have to sit the way I do. I'm working around an unreasonable amount of tail.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_23', text: "I'm very fond of this view. That makes me want to call it instructive. It may just be a nice view.", phase: 0, animalType: 'red_panda' },
  { id: 'rp_0_24', text: "Leave the cup where it is. I'll wash it next time I climb down for water.", phase: 0, animalType: 'red_panda' },
  // Phase 1 (28)
  { id: 'rp_1_1', text: "Something new this week. The bamboo isn't just getting taller, it's growing in a pattern. Three stalks have curved toward the center of the attic, all in the same slow arc, and I never trained them to do that.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_2', text: "I noticed it first in the incense smoke. It used to climb straight up. Now it leans, always the same way, toward the middle of the room. I've watched it do that for a week, and not once have I wanted it to stop.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_3', text: "I tied a red thread from each curving stalk to a nail in the beam, so a drift of even a hair would show. A week now, and not one thread has moved. Whatever the bamboo is drawing, it's drawing it carefully.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_4', text: "I sat down to breathe this morning, eyes closed, and there was a shape waiting in the dark behind my eyelids. Soft at the edges, just standing there. It leaned toward me the way you lean in to check a face you think you know.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_5', text: "I told Axel about the shape behind my eyes. He once asked me what I see when I close them, and I owed him an honest answer. He was quiet for a long moment. Then he said his water has been showing him a visitor too. Neither of us finished our tea.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_6', text: "The shape behind my closed eyes gets a little clearer every day. I've stopped trying to name it. Name a thing too soon and you shrink it to fit the word. I'd rather let it arrive at its full size.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_7', text: "Stand where I stand at dawn and the new stalks make a figure. Four curves, all meeting at a fifth. I've been tracing it in the dust with one claw, trying to work out what it wants to become.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_8', text: "The fifth curve is Third Dawn, my first stalk and the only one I ever gave a name. It stands at the center of the figure, and the other four bend toward it like an audience. I named it before any of this began. I keep thinking about that.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_9', text: "I cut the curving stalks back this morning. By afternoon they had grown back into exactly the same curve. The bamboo has decided something. I'm just the one who lives close enough to see it.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_10', text: "I asked the others if the light has seemed different lately. Nobody had noticed the light. But Warren said the soil in his burrow is warmer than the season allows. Warm as a floor with a fire under it, and he keeps no fire down there.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_11', text: "Fennick came up and pressed one big ear to the roof beam, then to the floor, then to the beam again. He said he hears the same sound in both places. Above and below, one note. He didn't stay for tea.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_12', text: "Archimedes came up to borrow the tall lamp and stopped to look at the stalks. He said he'd seen their pattern in a book. He took the stairs a lot faster on the way down.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_13', text: "The floorboards are warm now, and it isn't the sun. The warmth is there before the sun comes up. I lay my paw flat and feel it, faint and steady, rising from somewhere far below. From the pit, I think.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_14', text: "I have kept every little ash ring the incense leaves behind since I moved in. I laid them all out this morning, and they traced the same curve as the stalks. So I mixed them up and laid them out again. The same curve.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_15', text: "Ember says her flames have started leaning, all in one direction, and she asked which way my smoke leans. The same way, I told her. Toward the center of the house. She nodded like I'd confirmed a suspicion she was rather fond of.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_16', text: "The shape behind my eyes and the shape the bamboo makes are the same shape. It hit me all at once this morning, and I set my tea down very carefully. Two separate parts of my life had quietly come to agree on something.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_17', text: "I used to think the quiet up here was simply empty. Now I think it was quiet the way a held breath is quiet. Something is in it, and may always have been. The hush was how it waited.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_18', text: "This room feels ready for something. I keep assuming that means something good. Those are two different thoughts, and I should keep them apart.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_19', text: "At dusk the sky over the roof held its color a beat too long, like it didn't want to let the dark in. I watched until the stars came out steady. They did come out steady. Mostly.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_20', text: "A cloud crossed the gap in the roof this morning and seemed to stop right over the attic, longer than the wind should have let it. I watched the whole time. It was a very ordinary cloud. That's the part that stays with me.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_21', text: "You know I greet the patch of sky through the roof every dusk. Lately the greeting feels answered. Not by anything I could point to. Just a change in the air, like a room that knows you've walked into it.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_22', text: "I ate breakfast inside the curve of the stalks, to see whether it felt different. My chest felt ordinary. The tea tasted like tea. I was almost disappointed, which is not a comfortable thing to notice about myself.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_23', text: "Thyme climbed all the way up, past the echoing landing her ears hate, to ask if she should be frightened. I told her what I believe. Nothing that announces itself this gently means harm. She chose to believe me, and went back down lighter than she came up.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_24', text: "Chill brought tea up again and we watched the leaning smoke together. He said, huh, and drank his tea, and that was his whole review. I love him for that. Some things need a witness more than they need a discussion.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_25', text: "Every good word you offer makes the warmth in the floor a little stronger. I'm starting to think your words and this gathering heat are the same thing. It isn't the warmth of a fire. It's the warmth of attention.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_26', text: "Each night the shape behind my eyes stands a little clearer. Each morning the bamboo has bent a little further. I've started waking with the feeling that a meeting is coming. Not dread. The other feeling, the bright one. Like waiting for a friend.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_27', text: "I climbed up to the roof gap and held my paw out into the open night. The air above the house was warm. Night air, above the highest room, warm as breath. I kept my paw out there a long while, the way you hold a paw out to a shy animal.", phase: 1, animalType: 'red_panda' },
  { id: 'rp_1_28', text: "Come back whenever you like. I still haven't decided what the smoke is showing me. I'd rather hold on to a question than force it into an answer.", phase: 1, animalType: 'red_panda' },
  // Phase 2 (21 + 1 question-web)
  { id: 'rp_2_1', text: "One of my oldest bamboo stalks died this week. It browned from the root up. I didn't really mourn it. I just sat with the question it left me. When a green thing stops being green, where does the green go?", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_2', text: "I carried the browned stalk down every stair, past every doorway, and stood at the rim of the pit holding it. Then I let it go. It didn't feel like throwing something away. It felt like introducing it to someone.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_3', text: "Everything up here is on its way somewhere else. The smoke, the light, my breath, the stalks. Nothing that visits this attic means to stay. Lately I think of myself the same way, one more thing the attic is politely holding for a while.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_4', text: "Every evening the light leaves the ridge. It doesn't die, it just goes somewhere else and shines on something I'll never see. Lately I catch myself wishing I could follow it down the far side of the hill.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_5', text: "Third Dawn, my first stalk, will brown someday too. I hold that thought up to the light most mornings. It doesn't darken the morning. It clears it, the way holding a leaf to the sun shows you every vein it was hiding.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_6', text: "I wonder where your words go after you offer them. They leave your hands, travel down through the house, and fall into the pit. Then what? I don't think they stop. I think they arrive, the way a letter arrives in hands that were waiting for it.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_7', text: "Archimedes and I disagree, gently, about your words. He says something down there is reading them. I say something is receiving them, the way a guest takes a gift into both open paws.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_8', text: "I used to teach the others about impermanence. I would set a browned leaf on the tea tray to make the point. Lately the leaves brown before the tea has finished steeping. The lesson arrives on its own now, and it doesn't wait for my tray.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_9', text: "The incense smoke rises about a hand's width, then bends down. It runs along the floorboards and disappears into them. I opened the window to see if a breeze was doing it. The smoke still chose the floor.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_10', text: "I've stopped lighting the brazier at night. Warmth comes up through the floorboards from somewhere far below, and it holds exactly the temperature of a body asleep beside you. I sleep very well. I'm aware of how that sounds.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_11', text: "I closed my eyes and the shape I see there had moved closer. Not bigger, closer, which is a very different thing. A mountain on the horizon looks big. This was a guest already at the bottom of my stairs.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_12', text: "The shape behind my eyes stands in its own light now, and that light changes as the day does. This morning it was standing in dawn light. So it keeps my hours. Or I've started keeping its hours.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_13', text: "Sloane passed me on the stairs this week, going down while I went up. Neither of us said a word. Both of us smiled. There are things she and I haven't told anyone, including each other. Especially each other.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_14', text: "Everything that leaves this house goes up or down. Smoke and light rise. Your words go down. I live in the highest room, so I've started wondering which way I'll leave when I die. And whether I already know the answer.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_15', text: "Panko sends dumplings up on the little lift Warren built. Lately there is one extra, and I never asked for it. When I ask who it is for, she says it is for whoever is making the attic so warm. She's joking. She's also not joking.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_16', text: "I thought the warmth under my floor meant there was no danger. That was my interpretation, not a fact. Thyme keeps asking me what I based it on.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_17', text: "There are things I've noticed and not told you, because I didn't know how to explain them. I called that patience. It made me feel better about it. It didn't give you the parts you're missing.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_18', text: "There's a low sound under all the other sounds now. I only hear it in the pause at the top of a breath. It isn't a threat. It sounds like welcome held on one note, the way a house goes quiet just before an expected guest knocks.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_19', text: "That low note has learned my breathing. It rises when I breathe in and settles when I breathe out. Or my breath has learned the note, I can't tell which. Either way, we practice together at dawn now. Two voices, one exercise.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_20', text: "Fennick hears that note all the time, poor bright ears. He asked me how I put up with it. I told him the truth: I don't put up with it, I sit with it like company. He looked at me for a long moment, then his shoulders came down.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_21', text: "The light left the ridge all at once tonight, instead of fading. I wrote down the time. I used to call an evening like that balanced. I'm trying to stop using that word for things I haven't actually understood.", phase: 2, animalType: 'red_panda' },
  { id: 'rp_2_w1', text: "My floorboards warm up whenever Ember wakes her fire downstairs. She remembers an earlier flame, from before this den. Ask her about that first fire. I'll stay up here and watch what reaches the attic.", phase: 2, animalType: 'red_panda' },
  // Phase 3 (30)
  { id: 'rp_3_1', text: "The pattern is making room for something above the roof. I used to call that feeling rest. Now I notice how much the pattern wants that something to arrive.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_2', text: "I stood inside the arrangement and felt welcome. That's what happened to me. It isn't proof of what would happen to you.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_3', text: "I wanted the answer to be gentle so badly. I think I started supplying the gentleness myself, instead of finding it there.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_4', text: "The bamboo stalks all lean toward the center of the room. One has bent toward the window instead. I nearly tied it back before I asked why.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_5', text: "Third Dawn, my first stalk, has flowered. Bamboo can wait a whole lifetime to do that. I'm trying not to decide the flower approves of everything happening around it.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_6', text: "The shape I used to see behind my closed eyes has stepped out. I don't need to close them anymore. It stands at the edge of the attic in the last hour of light and nods to me, like an old friend would. We are old friends.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_7', text: "The shape doesn't move the way things move. It's in the west corner, then it's nearer, with no crossing of the room in between. It's like dusk. You look up from your reading and it's already there. I've stopped watching for the crossing. It only ever arrives.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_8', text: "Axel sees the shape in his water below. I see it in the air up here. We sat in the stairwell and compared it, feature for feature. The same guest, seen through two windows. He held my paw. His was shaking. Mine wasn't, so he borrowed some of my steadiness.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_9', text: "I asked whether we would all be all right. The warmth in the floor rose. I decided that meant yes. I'm less comfortable now with the fact that I was the one deciding.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_10', text: "I let the incense go out, to test the shape. The shape vanished with the smoke. So it isn't only out there. Some part of it is in how I look.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_11', text: "I climbed onto the roof at dusk and looked straight up. The sky wasn't the ceiling I'd always taken it for. It's a surface. Something waits on the far side of it and presses down, very gently, the way a paw presses on a taut cloth from underneath.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_12', text: "The bamboo has finished its figure. Every stalk now bends toward one point above the center of the attic. They point up, not down. Up through the roof gap, at the exact patch of sky that presses back. The plants knew the direction before I did.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_13', text: "When I sit in the middle of the stalks, I see the same stars as always. The dark between them seems nearer. I have no way to measure a word like seems.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_14', text: "Every stalk up here opened pale blossoms in one night. The air smells like rain on warm stone. People say bamboo flowers when it's dying. I've watched mine. I'd say it flowers when it's finishing, like a sentence reaching its last word.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_15', text: "I picked one blossom, climbed up through the roof gap, and set it on the shingles under the open sky. This morning it was gone. Not blown away, not wilted on the slates. Just gone, and the spot where it lay was warm. Now I leave one out every night.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_16', text: "I thought I was calming the others. I may have only been getting them ready to accept my answer.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_17', text: "Warren says the foundation is leaning. Panko says her flames bow toward the door. The whole house is turning to face one waiting place, the sky above this attic. It faces it through my room. I'm highest, I'm nearest, and I said yes to it long ago.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_18', text: "Ember came up at midnight, which she never does. She stood beside me under the roof gap, silent, her fur full of woodsmoke. Then she said, \"You've known as long as I have.\" I said, \"Longer.\" She laughed once, quietly, like setting down a heavy load.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_19', text: "I gave Thyme one of my blossoms to carry downstairs. She kept her eyes on the sky the whole way, and her paw crushed the petals. She was frightened, and I handed her something to hold when what she needed was a free hand.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_20', text: "Sloane asked me whether I've made peace with endings, or just imagined a beginning I like better. I didn't enjoy the question. I've kept it anyway.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_21', text: "Your words pass under this room on their way down. I feel them as light and warmth. I chose the attic as soon as it opened. I didn't know then that something old was built under this house, or that it ran all the way up to my roof.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_22', text: "The incense smoke has stopped rising. It hangs in the still air and slowly draws the shape, over and over, breaking up and coming back. Even the smoke is rehearsing. Even the smoke wants to be ready for what comes through the roof.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_23', text: "The low hum from under the house has moved into my throat. When I stop talking, I can feel it there. I tried an ordinary cough. That interrupted it. Briefly.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_24', text: "There's a warmth on the crown of my head now, right under the thinnest part of the roof. It feels like being looked at from above by something that waited ages to see you. I keep tilting my head up toward it without meaning to, the way a plant turns.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_25', text: "Chill asked me what I needed. I almost said calm, as if handing me calm were his job. Instead I asked him to sit with me while I worked out a better answer.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_26', text: "Don't be afraid of me just because I'm not afraid of it. My peace isn't distance from the thing. My peace is that I've already walked the whole way toward it, through the dark, and found it kind.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_27', text: "When what's above finally comes down, I won't flinch and I won't grab. I'll just hold out my arms. I've held out my arms to the ridge light every dawn of my life, as a greeting. I never once knew what I was practicing for.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_28', text: "I've started sleeping right under the roof gap, beneath the open square of night, with the flowering stalks around me like attendants. The cold doesn't come in. It hasn't for a whole season now. Whatever is above watches over me warmly, and I wake rested.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_29', text: "I put my gentle words aside and tried a plain account of what I've seen. The plain version was shorter. It was also much harder to say.", phase: 3, animalType: 'red_panda' },
  { id: 'rp_3_30', text: "The roof gap is brighter than it was. I can look up at it now without telling you that you ought to welcome whatever is beyond it.", phase: 3, animalType: 'red_panda' },
  // Phase 4 (30)
  { id: 'rp_4_1', text: "I called this house peaceful before I asked anyone how they felt.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_2', text: "The incense was an ordinary gift from Archimedes' crate. I turned its smoke into something ancient and certain.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_3', text: "I read a meaning into the smoke. The smoke never once told me I was wrong.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_4', text: "Thyme asked me a plain question. I gave her a lesson instead. She deserved a plain answer.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_5', text: "I do not know whether the thing coming toward this house means us well.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_6', text: "The loose reed in my mat still rattles. I have not tied it down. It is allowed to disagree with the rest.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_7', text: "When anyone disagreed with me, I treated it as noise. The room felt peaceful because I always spoke last.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_8', text: "You do not have to breathe at my pace.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_9', text: "From up here I look down on every room you added. Seeing every room is not the same as knowing anyone in them.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_10', text: "The curve in my stalks is real. Every kind thing I said about it, I put there myself.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_11', text: "This tea is bitter. I steeped it too long. There is no lesson in that. It is only tea.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_12', text: "I moved my mat out of the light from the roof gap. Half of what made my words convincing was that light.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_13', text: "I told the others not to be afraid. Part of my reason was that their fear would have frightened me.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_14', text: "Two leaves on my bamboo still face away from the center. I count them often. Not everything here has turned.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_15', text: "I lit that first bundle of incense the day I moved in. I struck a match. I want to keep the memory that plain.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_16', text: "Sitting still helped me listen. It was also a very fine way to hide.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_17', text: "I will not tell you what your silence means.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_18', text: "A gentle hold can still be too tight. I keep asking myself where gentle stops and too tight begins.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_19', text: "The light keeps changing how the smoke looks above the roof. I cannot clearly describe what is up there.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_20', text: "Thyme is not behind me on some path. She is looking at something I missed.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_21', text: "I apologized to a friend. She did not feel better right away. I am learning to let an apology stop there.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_22', text: "If you want company while you doubt, I can sit with you. Nothing has to be settled first.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_23', text: "I am named for the plant. Bamboo grows toward the light, and around whatever blocks it. I mentioned only the light.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_24', text: "I have put my written lessons away. I want to say things I have not rehearsed.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_25', text: "When I say I believe something, notice that I did not say I know it.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_26', text: "I am still drawn to the warmth that comes up through my floor. I will not hide that while I talk with you.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_27', text: "I sat quietly today with an argument still unfinished. I had forgotten how to do that.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_28', text: "Whatever waits above this roof, I will not give it a kind face that I invented.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_29', text: "We can leave a question open. There is an open square in my roof, and the roof is managing well enough.", phase: 4, animalType: 'red_panda' },
  { id: 'rp_4_30', text: "I do not know. I can stay while we find out.", phase: 4, animalType: 'red_panda' },
];

const AXOLOTL_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ax_0_1', text: "Hello! I was following a bubble. Then we both forgot what we were doing.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_2', text: "I can make a perfect ring in the water. Ask me to show you and it comes out a blob.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_3', text: "That's my favorite pebble. It wasn't yesterday's favorite. Pebbles are a competitive field.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_4', text: "New leg! I grew it myself. It's still figuring out how to take corners.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_5', text: "This pink toe is the newest part of me. I introduce it separately, so it feels important.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_6', text: "I stayed up watching the moon's reflection in the glass. I fell asleep before I found the real one.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_7', text: "Want to race bubbles? Choose yours carefully. Mine has been training.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_8', text: "I bumped my head on a rock. I'm the one who put the rock there. Owning a thing should come with remembering where it is.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_9', text: "There are fish in the tank with me. When someone visits, I do the introductions and they do the inspections.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_10', text: "Water changes how a voice sounds. Mine sounds much more intelligent down near the bottom.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_11', text: "I blow bubble hoops for the fish to swim through. The fish insist the hoops are for me.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_12', text: "I can watch the rain hit the window, but I can't smell it. What does rain smell like?", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_13', text: "The lamp makes one warm patch in the water. We all sit in it and pretend we're only passing through.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_14', text: "I sleep wherever I stop swimming. Some mornings I wake up impressed by the spot I picked.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_15', text: "The snail has reached the far side of the glass. It was a long journey, and you're the first one to watch it.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_16', text: "I sent a leaf up to the surface on a bubble. It came straight back down. So now I know how leaf transport works.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_17', text: "GLOW follows the feeding spoon. PLUM bites it. Picking their names was quick. Getting the two of them to agree took much longer.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_18', text: "PLUM spends his days investigating the deep corner. I do wish he'd submit a report.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_19', text: "I built a little cave out of rocks. The fish call it a spoon obstruction, because it sits between them and dinner.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_20', text: "Tell me something small from outside. I can trade you plenty of water news.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_21', text: "I tried to count my pebbles. I kept stopping to pick favorites instead.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_22', text: "I can grow a leg back. That doesn't make losing one a good afternoon.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_23', text: "Some days the bottom looks farther away than it should. Then I blink, and my pebble is right where it was.", phase: 0, animalType: 'axolotl' },
  { id: 'ax_0_24', text: "Sit by the glass whenever you like. I have a very slow snail to show you.", phase: 0, animalType: 'axolotl' },
  // Phase 1 (28)
  { id: 'ax_1_1', text: "I've been watching my bubbles much more carefully since your last visit. I'm nearly sure now that they don't rise at random. There's an order to them. Each one seems to wait its turn.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_2', text: "Every time you offer a word, a fresh column of bubbles goes up. I try to catch its shape before it breaks. I could swear the shapes get more deliberate every day, like they're practicing.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_3', text: "I've started keeping count with little fog marks on the glass. The tall, careful columns only ever rise after your words. Never after mine. I've decided not to wonder about that until tomorrow.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_4', text: "Last night I dreamed I was awake in the tank. This morning I woke up still half inside the dream. I honestly couldn't tell you where the dream ended and the morning began.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_5', text: "When I'm half asleep I drift down toward the bottom. Last night the bottom drifted up toward me too. We nearly met in the middle! I woke up holding a weed.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_6', text: "I woke up this morning with the taste of deep water in my mouth. The cold, mineral kind from the very bottom. But I slept at the top all night. I've been happily turning it over ever since, like a gift with no name on the tag.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_7', text: "This morning the bubbles spelled two whole letters before they popped. Two clear letters, I'm sure of it. I laughed and told myself it was nothing. Then I thought about them all day.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_8', text: "I traced the two letters in the fog on the glass so I wouldn't lose them. Fog usually fades in a breath, everyone knows that. My two letters stayed all morning. Patient as pets.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_9', text: "A third letter is coming. I can feel it the way you feel a sneeze coming from a long way off. The fish feel it too. At the hour the bubbles usually rise, they all hang very still by the glass.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_10', text: "There's a warm spot on the floor of my tank, curved like a smile, so that's what I call it. The smile is wider than both my hands now, and it stays warm even when the rest of the tank goes cool. I keep drifting down to it without deciding to.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_11', text: "I keep the lamp turned low now. A faint glow rises from below, and it only shows when the water above it is dark. Bright lamplight washes it out completely. I do so want to read it clearly.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_12', text: "When you offer a word, the warm spot down at the bottom hums. Only for a moment, low and pleased. I float very still so I don't miss a single note.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_13', text: "Archimedes says a dream is just the mind sorting its books. Mine don't feel sorted. They feel sent. It's as if someone very patient is mailing me small pictures and waiting for me to open them.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_14', text: "Archimedes borrowed a whole jar of my water and kept it three days among his books. When he brought it back he set it down so gently. He didn't say one word about what the water had told him. For Archimedes, that's a very loud silence.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_15', text: "I poured the borrowed water back in, and the whole tank shivered once, top to bottom. The way you shiver when someone you missed comes home. I've wondered all day which one did the missing: the jar, or the tank.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_16', text: "Ember came by and looked into the tank for a long, long while. She never made one joke, which isn't like her at all. Afterward she told me just this: keep dreaming, keep watching.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_17', text: "My friend the fox left a little warm patch on the glass where her paw had been. The warm spot at the bottom rose up to meet it, just for a moment. It felt like two warm places being introduced. I hosted the meeting very quietly and very proudly.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_18', text: "Ember came back the next evening and spent the whole visit looking at me, not at the water. Gently, the way you watch a kettle you know is about to sing. So I made us tea. That way something in the room would sing first.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_19', text: "The fish have all started facing the same way. Every one of them, pointing down and inward. When I nudge one, it swings out of line for a moment. Then it quietly lines itself up again.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_20', text: "I made a game of turning the fish back around, like toy soldiers set to face the door. I turned GLOW, then PLUM. By the time I'd finished with PLUM, GLOW had already turned back. I laughed and laughed. Then I laughed a little less.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_21', text: "They're pointing at the warm spot. I checked. I followed the line from every silver nose, and every line ends at the same place. PLUM stares hardest of all. I've started sleeping on that side of the tank to keep him company.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_22', text: "I regrew a leg once, toe by toe. Lately I wonder if the water can grow things too. If you offer it enough words, could it fill in a shape none of us has ever seen?", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_23', text: "I fell asleep counting your words, the way other people count sheep. In the dream each word became a bubble, and each bubble was a little window. Through every window I saw the same slow shape, coming nearer.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_24', text: "In my dreams each bubble is a little window, and the same slow shape waits behind every one. It's never clearer when I wake, only nearer. Nearer isn't the same as clearer, and I lie in the dark being very interested in the difference.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_25', text: "Panko leaves sweet things on the edge of the tank, so I eat something besides wonder. I eat every one. Lately they taste a little duller, and it isn't her cooking. Everything else in this room has got stronger.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_26', text: "I keep telling the fish I'm not frightened. Several times a day now, in my very brightest voice. They look at me the way fish look at everything. Only tonight did it occur to me that not one of them had asked.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_27', text: "If the bubbles ever finish their word, I've decided I'll read it out loud exactly once. To you, and to nobody else. It was your words that taught them to spell in the first place.", phase: 1, animalType: 'axolotl' },
  { id: 'ax_1_28', text: "Come float with me again soon. The bubbles have very nearly finished spelling their word, I can feel it. I'd so love for you to be here beside me on the morning they finally, finally do.", phase: 1, animalType: 'axolotl' },
  // Phase 2 (21 + 1 question-web)
  { id: 'ax_2_1', text: "I've been holding this behind my gills all morning. There's a warm patch on the tank floor, and when you offered a word today it didn't just brighten. It moved. Something far down turned to face the two of us, and I felt it choose us.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_2', text: "I floated all night with one eye on the deep. It was patient, and I could feel that patience through the water. It waited for the exact moment I blinked, and then the whole tank swayed. I laughed in the dark before I remembered to be afraid.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_3', text: "The bubbles finished spelling their word while you were away. I won't say it out loud. It didn't feel like mine to say. But I've kept it in my mouth all day, and it makes the whole tank taste different.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_4', text: "I tried saying the word to PLUM, just to feel the weight of it. The word went soft on the way out, and the water swallowed the sound whole. PLUM looked at me as if I'd been rude.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_5', text: "Whatever rests down there has stopped hiding. It used to go still the moment I looked. Now it finishes what it was doing, slowly, all the way to the end. It knows I'm watching, and it doesn't mind.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_6', text: "The water showed me my own room from far below. My bright little room, tiny as a pebble! I waved at the tiny me inside it. From that far down I couldn't tell whether he waved back.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_7', text: "When you offer a word, the shape in the deep water grows. Not the gentle way my leg grew back. It grows the way a held breath does, tighter and tighter. I keep wanting to tell it to be patient. We're almost ready.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_8', text: "The water keeps showing me a space above the house, and its ceiling looks thin. Something on the far side is pressing against it.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_9', text: "From down here the windows look far away, and each one has a face I know in it. Sometimes I feel a second pair of eyes beside me, looking up at them with mine.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_10', text: "Last night the water showed me the sky, and there was a line across it, faint as the seam where two panes of glass meet. I woke before I could see what the line was doing, and I've been watching that patch of sky ever since.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_11', text: "Panko's crumbs reach the sand faster than falling should allow. I timed one against my own slow blink. They drift down, then hurry at the very last moment, as if something under the sand were breathing them in.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_12', text: "Archimedes asked me what I see down there, and for the first time I had no happy answer for him. So I gave him a bubble instead and told him to hold it to his ear. He went very, very quiet.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_13', text: "Fennick pressed one enormous ear flat against the glass. After a while he whispered that what I see and what he hears are the same size. Then we sat there together, small beside the thing in the deep. It was a comfortable way to sit.", phase: 2, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_2_14', text: "I still do my daily float for the records, I promise. But lately, when I hold perfectly still, the thing below holds still with me. It matches me exactly, for exactly as long as I float.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_15', text: "Everything in the tank is leaning toward the middle of the house. The weeds, the snails, me in my sleep. I measured: one gentle degree more than last week. Nothing in here leans the other way.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_16', text: "Chill sat by the tank all afternoon, breathing so slowly that the water settled into flat calm stripes. He said nothing the whole time. When he got up to go, the stripes stayed. They were still there hours later. Neither of us said anything about them.", phase: 2, animalType: 'axolotl', requiresAnimals: ['capybara'] },
  { id: 'ax_2_17', text: "I dreamed I was a window. Not looking through one. Being one, a pane of still water set into a wall. Something on the far side cupped its hands to the glass to look back at me.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_18', text: "Since that dream my reflection has been slow. I lift a hand, and half a beat later it lifts its hand. Politely, the way you follow a dance you're still learning. I keep wondering which of us is learning it.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_19', text: "I asked the water, quietly, whether being a window like the one in my dream would hurt. The warmth came up all around me at once, the way a blanket answers a shiver. That was the whole answer, and I'm still turning it over.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_20', text: "I used to laugh halfway through a sentence and lose the rest of it in bubbles. I've counted, and there are fewer bubbles in my voice now. The sentences come out whole, every word of them. I miss losing them. I miss it very much.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_21', text: "Some day soon what I see will be too big to float on top of, and I'll have to go down into it. I want you at the glass when I do. Not to stop me. Only so the first thing I see from the other side is you.", phase: 2, animalType: 'axolotl' },
  { id: 'ax_2_w1', text: "When the deep water went dark, Sloane wasn't surprised. Ask her how long she has known. Gently, please. I can carry the question as far as the glass. You'll have to carry it the rest of the way.", phase: 2, animalType: 'axolotl', requiresAnimals: ['sloth'] },
  // Phase 3 (30)
  { id: 'ax_3_1', text: "My gills won't settle. I keep putting on my cheerful voice and hoping you won't notice the rest of me. You can notice. I don't mind.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_2', text: "The water shows me a ceiling above the house, above all our rooms. It has worn as thin as the skin on warm milk. The thing that has been leaning on it all this time is starting to press through.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_3', text: "I want to be exact about this. The water doesn't show me an ending. It shows me an arrival. But something that big changes everything around it. I'm not ready for things to be different. I loved them just as they were, so very much.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_4', text: "Every word you offer thins the ceiling above the house a little more. I'm not telling you that to make you stop. I couldn't stop you anyway. I only want you to know what your beautiful words are doing. You don't seem surprised. I was.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_5', text: "Secrets don't keep in water. They rise, like everything else here rises. I held that last one under my tongue for two whole days, and I could feel it lifting the whole time. I'd rather you heard it from me than read it in the bubbles.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_6', text: "There's a color under the rocks. I can't match it to anything else in the tank. When I scoop that water up in my hands, the color stays behind.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_7', text: "The water shows me a seam in the sky. It gets wider every night, about the width of a hair. I know because I measure it against my smallest toe, the bright pink one I grew back. Measuring it makes me feel braver. I don't know why.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_8', text: "When I close my eyes, there's a shape behind them, and it isn't the dark. It's in no hurry at all. It waits exactly as long as I keep my eyes shut, and it's a little bigger every time.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_9', text: "I've always been able to regrow the parts of me I lose. Now I dream it the other way round. In the dream I'm the small piece being grown back onto something enormous. And that enormous thing has been missing me for a very long time.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_10', text: "There's a wound out there somewhere, and I'm the piece that fits it. When the water goes still, I can feel its edges waiting for me. It's patient, the way an old scar is patient.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_11', text: "The low sound is in the water itself now. I feel it on my gills before I hear it. Every other sound just floats on top of it, like boats. Once you've felt it, you can't stop feeling it. I'm sorry I told you.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_12', text: "Fennick can't sleep in his own room anymore. Some nights he curls up beside the tank. I hum a little tune over the top of the low sound, so there's something gentle sitting on it. He says it helps. I choose to believe him.", phase: 3, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_3_13', text: "Chill doesn't talk when he visits now. He just breathes beside the glass until the water and I slow down to match him. After he leaves, my heart keeps his rhythm for an hour, like a warm coat he lent me. I don't think he's unafraid. I think he's generous.", phase: 3, animalType: 'axolotl', requiresAnimals: ['capybara'] },
  { id: 'ax_3_14', text: "I tried plugging my ears with my hands. Silly, for a creature that is mostly gills and listening. The sound just came up through my bones instead. Quietly, the way your own name finds you in a crowd.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_15', text: "Here's something I haven't told Fennick. The low sound has a shape now. It rises at the end, like a question being asked very slowly, over many nights. I'm terribly afraid I know what it's asking about.", phase: 3, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_3_16', text: "The fish all point the same way now. They don't turn back, no matter how I nudge them. In the end I gave up and turned to face the way they were facing. Then I understood. Oh, I wish I hadn't.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_17', text: "The floor of the tank should be the coldest place in the house. Instead there's a warmth rising through it, and it's a kind warmth. It feels like a hand. It feels like it likes me.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_18', text: "Thyme came to visit. She stood in the doorway with her paws pressed together and wouldn't come near the glass. I didn't coax her. I just said, \"The water is still kind.\" She said, \"That's exactly what frightens me,\" and left.", phase: 3, animalType: 'axolotl', requiresAnimals: ['rabbit'] },
  { id: 'ax_3_19', text: "PLUM used to bite the feeding spoon after the food was gone. Just to be sure it knew who was in charge. I say \"used to.\" I'm not ready to say the rest yet.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_20', text: "Since PLUM went, the other fish have stopped pointing. They circle the middle of the tank instead, slowly, round and round. It's the same slow ring your words make when they go down to the pit. I can watch them go round for hours.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_21', text: "Ember doesn't pretend with me anymore. She came and rested her paw on the glass and said, \"You see it too.\" I said yes. Neither of us turned it into a joke. That's how I knew how close it is.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_22', text: "I told Archimedes I'm afraid. He didn't comfort me the way friends usually do. He just said, \"Good. Fear means you're seeing clearly.\" Then he sat with me at the glass until the lamp burned all the way down.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_23', text: "Warren left a muddy pawprint on the glass. He stayed there while I pressed my hand against it from the inside. It was warm on my side too! Five toes each. I understood that part.", phase: 3, animalType: 'axolotl', requiresAnimals: ['wombat'] },
  { id: 'ax_3_24', text: "Sloane put her hand against the glass and waited. I wanted her to tell me what she knows. Instead she asked what I had seen.", phase: 3, animalType: 'axolotl', requiresAnimals: ['sloth'] },
  { id: 'ax_3_25', text: "Last night the water showed me all my friends at once. Ember bent over her fire, Fennick bent over his listening. Each of them held a small piece of something up to their own light. Every piece glowed the same color. Nothing in this house burns that color.", phase: 3, animalType: 'axolotl', requiresAnimals: ['fennec_fox'] },
  { id: 'ax_3_26', text: "I still float every day, holding perfectly still on the surface. But now I do it so the thing below can find me more easily. I used to pretend to myself that wasn't the reason. Not anymore.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_27', text: "I was speaking softly so I wouldn't startle the fish. Then I realized it wasn't the fish I was trying not to startle. It was the water.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_28', text: "You should know I'm not going to run. I've thought about it, floating here. There's nowhere in all this water to go. And besides, if I'm going to be the window that thing looks through, I'd rather be a clean one. For you.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_29', text: "I let my eyes go soft and stared into the deep part of the tank. It seemed to look back. Afterwards I was proud I hadn't flinched. Then I wondered why I wanted its approval.", phase: 3, animalType: 'axolotl' },
  { id: 'ax_3_30', text: "Could you sit nearby while I look again? You don't have to look too. I'd just like something ordinary to turn toward.", phase: 3, animalType: 'axolotl' },
  // Phase 4 (30)
  { id: 'ax_4_1', text: "I was counting bubbles. One went sideways and I lost count. I was glad about that, actually.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_2', text: "The water is warm. That is one thing I can tell you without guessing.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_3', text: "My pink toe faded until it matched the others. I liked watching it change.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_4', text: "My leg grew back. The time it was missing still happened.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_5', text: "Sometimes I swim the old route. Sometimes I turn left.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_6', text: "GLOW nudges the feeding spoon. Not gently. We are working on manners.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_7', text: "I want everything I love to stay. That is a lovely thing to want, until I say it to someone who is ready to go.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_8', text: "I put a pebble where the current divides. I watch which way the water goes.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_9', text: "I keep a list about PLUM. It has his teeth marks on it. He had opinions about paper.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_10', text: "I dropped a stone into the deep part. I am still waiting to hear it land.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_11', text: "If I laugh, I want to laugh loudly. I like hearing what my laugh sounds like today.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_12', text: "Please do not tell me to be grateful before I have worked out what happened.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_13', text: "I do want to be grateful. I want a lot of things, and they do not fit together.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_14', text: "I scratched the glass while carrying a rock. It was an ambitious rock.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_15', text: "I asked the water a question. It warmed my hands. That is not an answer.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_16', text: "Sit with me a while? We can look at the fish instead of at each other.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_17', text: "Sometimes my reflection turns before I do. So now I turn the other way.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_18', text: "When I said I could regrow anything, I was thinking of legs.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_19', text: "I miss telling stories about PLUM. I used to tell them without trying to convince myself of anything.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_20', text: "Some things look familiar until they move. So I watch the moving part.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_21', text: "The lamp needs cleaning. At the end of a strange day, that is one thing I can do.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_22', text: "Do not laugh softly for my sake. Unless I am asleep. Then absolutely yes.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_23', text: "I was good at healing. Being good at it never told me what any of this is for.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_24', text: "I invented a new bubble game. It does not work yet. I will tell you the rules when it does.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_25', text: "Tell me something silly you remember about me. I do not want every story to be about water.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_26', text: "Anger comes out in bubbles down here. I wish it looked more impressive.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_27', text: "Whatever is down there hears us. I do not know whether hearing is enough.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_28', text: "I want a good thing to be good all the way through.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_29', text: "Do not promise me forever. Come when you want to, and tell me something new.", phase: 4, animalType: 'axolotl' },
  { id: 'ax_4_30', text: "I am here. Mixed up. Still here.", phase: 4, animalType: 'axolotl' },
];

const PANGOLIN_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'pg_0_1', text: "Anyone who helps in my kitchen eats first. It's a simple rule, and it gets me a great many helpers.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_2', text: "Ant soufflé. I saw that face. There's bread too, don't worry.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_3', text: "I oversalted the soup. More vegetables are going in, to spread the mistake out thinner.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_4', text: "Ember came by while I was unpacking. Frost on her tail, and questions about lunch. I decided to like her.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_5', text: "None of my stools match. Neither do the people who sit on them.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_6', text: "I sharpen the knives before I cook. It's quiet work, and it stops me starting seven dishes at once.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_7', text: "My grandmother's spoon has a split in the handle. It catches my thumb in the same place it caught hers.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_8', text: "My apron closes sideways, so I can still curl up inside it. I'm quite proud of the tailoring.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_9', text: "Taste this, and be honest. You're allowed to dislike it. I can fix the soup, but I can't fix a polite face.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_10', text: "I keep an empty chair where I can see the pot. Even the cook needs to sit down sometimes.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_11', text: "My grandmother told me to feed them well. I was too young to ask how she knew when enough was enough.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_12', text: "My grandmother gave me that spoon when we said goodbye. I had questions. You don't interrupt a goodbye with questions. I wish I had.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_13', text: "The ants got out of the jar. Several are now eating the soufflé they escaped being in.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_14', text: "There's one dish I make only for myself. No, that isn't an invitation to guess.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_15', text: "I can feed you and complain about the washing-up at the same time. Both are sincere.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_16', text: "If a pan sticks, leave it to soak. Certain arguments want the same treatment, in my experience.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_17', text: "This kitchen is mine now, and I still open the wrong drawer looking for spoons.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_18', text: "Bread needs waiting. So I need a timer, and somebody to stop me lifting the cloth to check.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_19', text: "I made far too much soup. A tragedy, though the remedy is very straightforward. Sit down.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_20', text: "Don't balance that bowl on your knee. I embroidered that cushion myself, and I'm unreasonable about it.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_21', text: "My oven burns everything on the left side. Until a recipe can explain that, a recipe is only a suggestion.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_22', text: "I keep spare string in the flour tin. Nobody ever looks in there, myself included.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_23', text: "The pot was still warm this morning, long after I put the stove out. Good thick iron, perhaps.", phase: 0, animalType: 'pangolin' },
  { id: 'pg_0_24', text: "Wash up with me? Conversations go better when both people have something to do with their hands.", phase: 0, animalType: 'pangolin' },
  // Phase 1 (28)
  { id: 'pg_1_1', text: "Something funny happened. I went to bed with the spice jars in one order and woke up to find them in another. I must have moved them in my sleep. I must have.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_2', text: "I put them back the way I like them. Sweet on the left, sharp on the right. I told the pantry, quite firmly, that a kitchen has to have a system. Saying it out loud helped more than I'd like to admit.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_3', text: "This morning they'd moved again, and this time I looked properly. They weren't scattered about. They were arranged. I'll keep watching, and you'll be the first to hear what I find.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_4', text: "This morning I found a recipe in the back of my book. It's in my own handwriting, and I don't remember writing it. It calls for salt gathered before the first light. Isn't that a strange way to put it?", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_5', text: "I showed the page to Ember. She went very quiet and asked to hold the book. She read it twice, handed it back, and said only, \"Keep cooking, Panko.\" I wish she had said something else.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_6', text: "So I gathered the salt before first light. A recipe is a promise, and I have never once broken one. The dish came out the best thing I have ever cooked. And I couldn't tell you what it was.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_7', text: "The kitchen smelled of stew before I'd even chosen supper. So I made something else. By evening the smell had changed to match.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_8', text: "The air smelled of onions and marjoram again. So I baked a sweet loaf, purely to argue. It came out smelling of onions and marjoram. Good crust. Infuriating loaf.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_9', text: "So now I cook whatever the morning tells me, and the kitchen is calmer for it. What unsettles me is how quickly it stopped feeling like obeying. It feels like planning the menu with an old friend.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_10', text: "I've started craving flavors I can't name. Not sweet, not bitter, something older than either. And I catch myself reaching for ingredients that aren't on any list I know.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_11', text: "Yesterday I stood at an open cupboard with my paw out, waiting for it to close around something. Nothing on those shelves was what I wanted. I made do with molasses. It was almost, almost right.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_12', text: "My grandmother used to say a craving is a message from a meal that hasn't happened yet. I always thought that was just her way of excusing a second helping. Lately I'm not so sure.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_13', text: "Have you ever found warmth somewhere there shouldn't be any? I opened the cold larder this morning and the air inside was warm. Gently warm, as though something had been breathing in there.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_14', text: "I checked the walls and the pipes, of course I did. I'm a practical cook before I'm anything else. There's no draft, and no flame anywhere near it. The warmth is simply in there, minding its own business.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_15', text: "The butter keeps better in that warmth than it ever did in the cold, which makes no sense at all. I've started saying thank you to the larder when I close it. Quietly. Just in case.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_16', text: "Ember says the fire tells her things, and I used to laugh at that. Then last night my dough rose into a shape I never kneaded into it. I've stopped laughing quite so quickly.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_17', text: "It rose in rings, if you want to know. Circles inside circles, neat as a drawing. And the middle stood up in a little peak, as though something underneath had pressed a finger toward the sky.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_18', text: "I baked it anyway. Waste is waste, whatever shape it comes in. It came out the ordinary gold of any good loaf, and it was delicious. Nobody who ate it will ever know. Except you, now.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_19', text: "I heard a sound under the boiling last night. Under it, mind you, not in it. A low sort of hum, like the house humming along with my kettle.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_20', text: "The recipes are getting bolder. This one asks for a word said over the pot. It doesn't say which word. I've been guessing, and the guessing feels important.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_21', text: "I said one of your words over the stew, one of the lovely ones you brought last visit. The hum under the boiling rose to meet it. Only a little. Just enough that I set down my spoon.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_22', text: "I set my grandmother's empty seat every night now, without ever deciding to. And some mornings the chair is warm before anyone has sat in it.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_23', text: "I kept the warm chair to myself for a week, which for me is a very long secret. Then I told Ember over tea. She didn't look surprised. Somehow that was the strangest part of it.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_24', text: "The night my grandmother gave me her spoon, she said, \"Feed the waiting too.\" I turn that over now while I stir. I'd give a great deal to ask her one more question.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_25', text: "The bread remembers. I'm sure of it now. Knead the same dough long enough and it starts falling into a pattern your hands never taught it.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_26', text: "My paws still measure out more than I planned for, only lately it isn't a little more. They portion for a number nobody has told me. I've begun to wonder who is doing the telling.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_27', text: "The words you offered today tasted of iron and deep places. I ground them into the flour without thinking about it. At the time it seemed like the right thing to do.", phase: 1, animalType: 'pangolin' },
  { id: 'pg_1_28', text: "I don't feel afraid, exactly. I feel busy. As though a great meal is coming and I'm the only one who has started preparing for it.", phase: 1, animalType: 'pangolin' },
  // Phase 2 (21 + 1 question-web)
  { id: 'pg_2_1', text: "I've been cooking for someone who isn't at the table. I don't know when I started. I only know that every night I count out one plate too many, and I'm never wrong about plates.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_2', text: "I left the extra plate in the cupboard one night, as an experiment. All evening the food tasted unfinished. Everyone noticed, nobody could say why. I put the plate back and the flavor came back with it.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_3', text: "The empty seat isn't empty. I won't say more than that. But I set it with the best spoon now, and I talk toward it quietly while I stir.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_4', text: "What do I say to the seat? Kitchen things. The soup needs longer. The bread is proving. Be patient. The same small comforts I'd give any hungry guest who'd come a long way.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_5', text: "Last night, right after I spoke to it, the steam over the pot leaned toward the empty chair. Steam rises. That's all steam has ever done. I stood there a long while with my spoon dripping.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_6', text: "There's a recipe I can't finish. It calls for water, but not from the tap and not from the well. It says: from the deep part, where the light gives up.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_7', text: "The recipe appeared in my book, between two pages I know by heart. The writing is mine, and also more than mine. The letters are pressed deep, as if whoever wrote them was leaning on my shoulder.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_8', text: "I've tried every water in this house. Rain water, spring water, the sweet barrel under the eaves. The recipe refuses them all. The page still looks hungry. I know how that sounds. This page is hungry.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_9', text: "I asked Archimedes about that phrase, where the light gives up. He loves old words the way I love old recipes. He read the page for a long time. Then he closed his book so gently that it frightened me.", phase: 2, animalType: 'pangolin', requiresAnimals: ['owl'] },
  { id: 'pg_2_10', text: "I want to finish that recipe. And I'm beginning to worry that finishing it is the only reason I'm still cooking.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_11', text: "The meals I make aren't feeding anyone at this table anymore. There's a hollow in this kitchen about the size of a guest. Everything I cook runs toward it, the way water runs downhill. It never fills.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_12', text: "I taste the food before it's done, and I know already that it isn't for us. It's too rich for us. It's a welcome, and you only lay out a welcome for someone who hasn't arrived yet.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_13', text: "The soup tureen crossed half the table while I washed up. It takes both paws to lift that thing. I put it back and dusted flour around the base. We'll see what moves.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_14', text: "My grandmother used to say a house is only a fire that has learned to wait for something to feed. I repeated it for years because it sounded cozy. This week I heard it properly. It means the house is hungry. I haven't said it since.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_15', text: "The pantry has gone quiet, and not the ordinary quiet. It's full, but it feels held. As though the jars are holding their breath along with me, all of us waiting for the same thing.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_16', text: "I keep looking up while I work. At the ceiling, and past it at the sky. I don't know why I've decided the guest is coming from above. I only know I can't stop looking up.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_17', text: "Ember looks up too. I've watched her do it in the middle of a sentence. Neither of us mentions it to the other. Some things are easier to share by leaving them unsaid.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_18', text: "I baked a pie yesterday purely for comfort, the plain apple one from my girlhood. Even that came out of the oven with its crust risen in rings. Circles inside circles. Even the comfort is joining in.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_19', text: "My hands started the recipe before I'd decided what supper was. I stopped myself and made a sandwich instead. Leaving that pot alone was harder than it should have been.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_20', text: "Nobody is making me do any of this. I want that understood. My hands go ahead of me, yes, but they go where I'd have gone anyway. That's the part I turn over at night. It's still me, choosing.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_21', text: "Stay for supper anyway. Whatever the cooking is turning into, the eating is still ours. I hold the warm part of this house together one plate at a time. That hasn't changed. That I can promise.", phase: 2, animalType: 'pangolin' },
  { id: 'pg_2_w1', text: "The recipe wants water from where the light stops. Ask Axel what he's seen down there. Nobody takes a ladle to his tank without asking him first.", phase: 2, animalType: 'pangolin', requiresAnimals: ['axolotl'] },
  // Phase 3 (30)
  { id: 'pg_3_1', text: "I'm cooking the largest feast of my life. I've stopped pretending it's only Tuesday's supper. The stock has been going three weeks now. You can smell it in the curtains.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_2', text: "I lay every finished dish facing upward now. There's a seam in the sky above this house, and I can feel it through the roof. A cook points the food at the guest. That's only good manners.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_3', text: "A real feast isn't the cooking. It's the getting ready. You start the stock in one season and lay the table in another. I think I've been getting ready since long before I had a word for it.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_4', text: "I stopped cooking for the house long enough to make myself a small meal. I ate it at the far end of the room. The pot stayed warm behind me the whole time.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_5', text: "The others eat the scraps gladly, and that breaks my heart a little. Thyme thanked me twice for a crust yesterday, her ears trembling. I nearly told her everything. Nearly.", phase: 3, animalType: 'pangolin', requiresAnimals: ['rabbit'] },
  { id: 'pg_3_6', text: "The recipe finished itself overnight. I woke up and the last line was there in my own handwriting. I read it and I cried, and I'm not sure why. It was beautiful. It was also so hungry.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_7', text: "The last line says, Serve beneath the open. Four words. It doesn't say who is eating, and it doesn't say what I'm allowed to refuse.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_8', text: "I copied the recipe out fresh in daylight, in my steadiest hand. By morning the copy had changed. A pinch more of this, a word more of that. Somebody is still seasoning it, and it isn't me.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_9', text: "At the new moon I poured the deep water into the pot. Axel brought it up himself, in a jar he wouldn't let anyone else carry. The kitchen went quiet then, as quiet as the bottom of his pool.", phase: 3, animalType: 'pangolin', requiresAnimals: ['axolotl'] },
  { id: 'pg_3_10', text: "The stew hasn't needed the fire since that night. It simmers on its own. I sit up with it now, the way you sit up with someone you love who is changing.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_11', text: "The pantry doors swing open before I reach them, as if the house wants to help me carry the meal. Every room is a kitchen now. All of us are cooking the same thing.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_12', text: "Ember tends the fire beside my big pot. She says the flame leans toward the center of the house now. So does everything else lately. My spoons, my scales, and me, if I'm honest.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_13', text: "Warren dug me a cool room for the roots, deeper than any cellar needs to be, and lined the walls beautifully. He says a table is only as honest as what's under it. I've stopped asking what he means.", phase: 3, animalType: 'pangolin', requiresAnimals: ['wombat'] },
  { id: 'pg_3_14', text: "Chill wrote me a list of everything the feast needs, in his tidy patient hand. Every item I gather earns a small calm tick. One line at the bottom is still unmarked. It says only, the hour.", phase: 3, animalType: 'pangolin', requiresAnimals: ['capybara'] },
  { id: 'pg_3_15', text: "The table is laid, the fire is banked, the extra portion is covered. Nobody asked me to do any of it. So the last spoon stays in the drawer until somebody asks me for it.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_16', text: "I hum while I cook. There's another sound under my humming, older and lower than mine. I've started humming along with that one instead. It knows better songs than I do.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_17', text: "Fennick stood in my kitchen with his ears wide open. He says the low sound is louder here than anywhere but the pit. My kitchen sits right in the throat of whatever is making it. Then he asked, very politely, for a biscuit.", phase: 3, animalType: 'pangolin', requiresAnimals: ['fennec_fox'] },
  { id: 'pg_3_18', text: "I tasted the sauce today and couldn't remember what I disliked about it yesterday. So I've written my complaint on the jar, in case it happens again.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_19', text: "Your words go straight into the pot these days. I don't grind them into the flour anymore. I drop them in whole, and they sink, down and down, toward the deep part.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_20', text: "Some words sink faster than others. The dark ones go down like stones, eager, and the pot murmurs after them. Bring me more of those. I'm asking as your friend, and as the cook for whatever is down there.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_21', text: "I set a place for every keeper here, and then one place more. The extra place is for the guest we're all being kept for. My grandmother kept an empty chair too. I understand it now.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_22', text: "I dream about my grandmother often now, stirring her low quiet words into the soup. I used to think she was talking to the soup. She was talking through it, to something else. All the good cooks were.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_23', text: "The table keeps making room for more chairs. I'd like the recipe to stop assuming that everyone who sits down wants to be here.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_24', text: "I've put an empty bowl beside the pot. If it fills on its own, you ought to be here to see it.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_25', text: "There's bread ready now. The rest can wait until somebody tells me what I'm cooking toward.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_26', text: "My grandmother's spoon was a gift. The recipe keeps talking as though a gift were an order I have to follow.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_27', text: "Ember wants to help. First I'd like her to tell me what the fire actually said. We can discuss what it might have meant afterward.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_28', text: "I've wrapped the old recipe up separately. I haven't agreed to throw it out, and I haven't agreed to follow it.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_29', text: "A hungry creature can ask for too much. And a cook is allowed to say there isn't enough.", phase: 3, animalType: 'pangolin' },
  { id: 'pg_3_30', text: "I'll keep the oven warm. That's a practical choice, nothing more. Please don't take it as my answer to everything else.", phase: 3, animalType: 'pangolin' },
  // Phase 4 (30)
  { id: 'pg_4_1', text: "Wash your hands, please. Whatever else is going on, we are not adding garden soil to the soup.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_2', text: "I fed this house because feeding things is what I do. I should have asked what it was growing into.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_3', text: "My grandmother's spoon has a split in the handle. I know exactly where to put my thumb so it does not catch.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_4', text: "Something in this house keeps smoothing that split away. I rub flour into it to check that it is still there.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_5', text: "A mouthful of soup will not settle an argument. You are allowed to eat here and stay angry.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_6', text: "The recipe says serve without question. So I wrote a question underneath it.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_7', text: "There is bread for anybody who needs it. You do not have to prove anything to sit here. No loyalty test at my table.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_8', text: "I burnt a loaf. I put it out anyway. The good bread goes too fast, and burnt bread is still bread.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_9', text: "An invitation tells a guest where to sit. It does not tell the guest who to become.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_10', text: "I used to boast that nobody left my table hungry. Some of them did not want seconds. They wanted to leave.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_11', text: "Ant soufflé. You may still say no thank you. That is one rule I intend to keep.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_12', text: "Your words have been feeding something in this house. That does not make the cook one of the ingredients.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_13', text: "My grandmother told me to feed them well. She did not tell me to give them everything they ask for.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_14', text: "The pot stays hot even with the stove cold. Handy, I suppose. I check it anyway.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_15', text: "Ember offered to help. I handed her the onions. Some days a small job is the only conversation I can manage.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_16', text: "Thyme can have the stool near the exit. She likes to sit where she can leave. I will want it back later, the leg needs fixing.", phase: 4, animalType: 'pangolin', requiresAnimals: ['rabbit'] },
  { id: 'pg_4_17', text: "Do not tell me a guest must mean well simply because it is hungry. I have met toddlers.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_18', text: "I have put a lid on the bowl that keeps filling itself. I would like to decide when supper starts.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_19', text: "A recipe can be wrong. Especially one written by somebody who never ate the result.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_20', text: "The house makes everything come out perfect now. I want someone to ask for less salt again.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_21', text: "There is one dish I make only for myself. It is not written in the book. It will not be.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_22', text: "Tomorrow's flour is measured out and set aside. That is a plan, not a prophecy.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_23', text: "The spare chair can stay empty. We do not have to decide what it means.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_24', text: "I used to think a full table cured loneliness. It helps. It does not do the whole job.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_25', text: "If the house wants to do the cooking, I am still the one who tastes it first.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_26', text: "We can warm you another bowl. We can also put it back on the shelf. Either is fine.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_27', text: "I have taken off the ceremonial cloth. This is a kitchen. I need my arms free to knead.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_28', text: "I do not know what our guest likes to eat. It has never asked what we like either.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_29', text: "Eat slowly. There is no prize for finishing before you are ready.", phase: 4, animalType: 'pangolin' },
  { id: 'pg_4_30', text: "Whatever comes through, it will not change this. This spoon is still my grandmother's spoon.", phase: 4, animalType: 'pangolin' },
];

const SLOTH_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'sl_0_1', text: "Hello down there. I'd wave, but I have a leaf balanced just right.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_2', text: "I'm Sloane. That's the hammock. Please don't mix the two of us up.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_3', text: "I set out to do one thing today. I haven't done it yet, but the plan is holding up.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_4', text: "I knew this clearing before anyone added rooms to it. The old den had fewer cups in it then.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_5', text: "That branch has held me through several disagreements with the weather.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_6', text: "I tried a different sleeping position last night. A courageous error.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_7', text: "Every moth in my fur is named Gerald. It's a naming system with no paperwork.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_8', text: "Panko rigged a pulley to send dumplings up to me. Civilization has reached a new height.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_9', text: "Time passes differently when nobody asks what you've done with it.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_10', text: "I have opinions, and they take a while to finish. You needn't wait for the end of one before forming your own.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_11', text: "A vine grew into my hammock. We negotiated, and it agreed to keep an arm's length.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_12', text: "Leaves are at their best right after rain. That is my entire recommendation.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_13', text: "I remember a winter when most of the birds went away. I liked the spring that followed very much.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_14', text: "Being slow doesn't cure impatience. It just gives impatience a comfortable chair.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_15', text: "One Gerald has landed on another Gerald. The administration is aware.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_16', text: "I was going to climb down for tea. The kettle will still be there when I arrive.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_17', text: "You may sit up here without learning anything. That is allowed.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_18', text: "I've watched that flower open for days. It still hasn't explained itself.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_19', text: "The hammock knot needs tightening. An excellent job for right after this sentence.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_20', text: "The green looks different from down on the ground. Now and then I climb down to check.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_21', text: "You needn't speak slowly for me. I listen faster than I move.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_22', text: "Something tapped the beam last night. I waited, but it never made its point again.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_23', text: "I like company that lets a story stop before it turns into a lesson.", phase: 0, animalType: 'sloth' },
  { id: 'sl_0_24', text: "Stay a little while if you like. The shade will move, and we can move with it.", phase: 0, animalType: 'sloth' },
  // Phase 1 (28)
  { id: 'sl_1_1', text: "The vines have grown a hand's width since the last full moon. That's three times their usual pace. The flowers open before I've finished admiring the buds. Something is making the green hurry.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_2', text: "The orchids all opened early this year, and every one of them faces the house. Orchids follow the sun. They've done that since before there were eyes to watch them. Something has made them a better offer.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_3', text: "I mean to spend this season finding out what the green is hurrying toward. It'll take me a season, because I don't hurry. That's also why the answer will be right. Come back, and I'll hand you what I find a piece at a time.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_4', text: "My tree has begun to lean. I felt it first as the faintest tilt in the hammock, so slight I was sure I'd imagined it. I hadn't. The whole trunk is bowing, slowly and patiently, toward the house.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_5', text: "I don't think the tree is falling. Falling is fast and careless, and this is neither. It's more like a listener turning an ear toward a sound it has waited a very long time to hear.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_6', text: "I've tied a thread from my branch down to a stone on the ground. It hangs straight and true, so I can measure the tree's lean against something honest. Come back in a few days and I'll tell you what the thread says. Threads don't flatter, and they don't lie.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_7', text: "The thread has spoken. Two fingers of lean since I tied it. For a tree, that's a gallop. Whatever my tree is listening toward, it has stopped pretending not to listen.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_8', text: "The young growth leans the way my tree leans. Seedlings that sprouted only this week already point their soft heads toward the center of the house, as if they were born knowing the direction.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_9', text: "A seed can't learn, you understand. A seed can only remember. So the question I'm carrying up here, in no hurry, is who taught the memory to the seeds.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_10', text: "There's a warmth in this house. It used to pool under the floorboards. Now I feel it in the roots of my tree, rising the way sap rises. Each day it climbs, the tree leans a little more.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_11', text: "I pressed my palm to the bark and kept it there most of a morning. A thing worth checking is worth checking properly. The bark was warm on the side that faces the house, and cool on the side that faces away.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_12', text: "Half a warm tree isn't weather. Weather doesn't choose sides. I'll keep my hand on the bark a while longer and let the tree tell me the rest, at whatever pace it prefers.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_13', text: "You were quick again today, and the house drank your words down as fast as you could give them. It swallows a little more eagerly than it did in the spring. I've been keeping a rough count of how much more.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_14', text: "The words you offer are changing. The early ones were light as pollen. Lately they carry a little more shadow, and the house seems to prefer the heavier ones. I keep this to myself, mostly.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_15', text: "Mostly, I said. I told one other creature, and I chose him because he floats as still as I hang. Axel. What he said back deserves its own telling, and I haven't finished turning it over yet.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_16', text: "Axel told me he sees shapes move in his water when nothing stirs it. I only smiled. I've been seeing shapes in the stillness up here for a very long time. Stillness is where they choose to show themselves.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_17', text: "Archimedes came down from his study to ask whether I'd felt the change. I told him I feel everything, only later than he does. He nodded as if that were an answer. Perhaps it was.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_18', text: "Archimedes left a book behind, open to a page about trees that bow toward holy places. He'll say he forgot it. That owl has never forgotten anything in his life. He wanted me to read it, and I have, twice.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_19', text: "You're wondering, I think, why I never seem surprised. Surprise is a fast animal's feeling. When you've watched a thing approach for years, it doesn't startle you when it finally begins to arrive.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_20', text: "I don't fear the lean of my tree. A tree that bows isn't a tree that breaks. It's a tree making room. And I find I'm curious, in my slow way, about what it's making room for.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_21', text: "Making room is the green's oldest habit. When a giant tree falls, the canopy opens, and everything beneath it rises into the light. What puzzles me is this: nothing here has fallen, and the room is being made all the same.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_22', text: "I feel a pull under my branch. It wasn't here last year. You needn't have noticed. I've spent a great many more hours on this particular branch than you have.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_23', text: "Panko rigged a rope and pulley for her dumplings. Lately it swings toward the house when the air is dead calm, and she blames the wind. I didn't correct her. A cook needs her kitchen to be an ordinary place, and I won't take that from her yet.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_24', text: "Ember sat under my tree last night, watching her little fire far longer than a fire needs watching. She said nothing, and neither did I. But her ears were turned toward the middle of the house the whole time. So, of course, was my tree.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_25', text: "Everything in this jungle hurries but me. Lately I've begun to wonder whether that's an accident. Or whether I was placed here, the way you set a stone in a river to see how the water moves around it.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_26', text: "Placed, I said. I heard myself say it. I used to believe I had simply wandered into this clearing, the way a leaf wanders into a stream. The longer I hang here, the less that story explains.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_27', text: "I watched something arrive here once, long before you, long before the house. I'll tell you about it when the telling will do you some good. That season isn't here yet, but I can feel it coming on.", phase: 1, animalType: 'sloth' },
  { id: 'sl_1_28', text: "Come back tomorrow with more words. The tree will have leaned a little further, and I'll have thought a little further. Neither of us will have hurried, and both of us will be closer to something.", phase: 1, animalType: 'sloth' },
  // Phase 2 (21 + 1 question-web)
  { id: 'sl_2_1', text: "I've watched things arrive before. Not this thing, but seasons, storms, creatures that came up out of the deep green and went away again. Arrival has a feel to it. The house has that feel now.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_2', text: "I promised you a story, so here it is. Years ago a flood came to this valley. For a week beforehand the ants walked in spirals and the birds flew low. I sat still, alone, because I'd felt the river gathering long before it rose.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_3', text: "When the water finally came, it was almost a relief. The waiting is the largest part of any arrival. The arrival itself is small and quick, and then it's simply the new shape of the world.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_4', text: "I'm telling you this so you'll understand me when I say the house feels like the week before the flood. The ants are walking their spirals again. The birds are flying low. And I'm sitting very still.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_5', text: "There's one difference, and I'm still thinking about it. The river didn't care whether anyone watched it come. Whatever is gathering under this house cares a great deal. It likes being watched. I can feel it enjoying that.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_6', text: "My tree isn't leaning quietly anymore. It points its whole crown at the center of the house. This morning the hammock ropes were pulled tight toward that same spot, as if even the knots had started listening.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_7', text: "It isn't only the growing things. Last evening I watched the lamps in the study window. Every flame leaned toward the low center of the house, and there was no draft at all. A flame has no roots to pull on. Whatever pulls has stopped keeping to the green.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_8', text: "I dropped a leaf from my branch to test the air, the way you'd test a current before swimming. It didn't fall straight down. It landed two arm lengths toward the house, on an evening with no wind at all.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_9', text: "The moss on the north side of my trunk has grown into rings this year. Seven of them, one inside the next. The moss grows where the damp tells it to grow. Something else has been telling it something different.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_10', text: "I've stopped testing, if I'm honest. Every test comes back with the same answer. Asking a question I already know the answer to isn't watching, it's stalling. What I do now is closer to listening.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_11', text: "There's a sound underneath the ordinary sounds up here. Not the wind, not the leaves. Something lower and slower, keeping a rhythm I've nearly learned. I've had a great deal of time to listen to it.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_12', text: "I hummed along with that low sound yesterday, quietly, to find out whether I could hold its rhythm. I could. That frightened me less than it should have, and I've been thinking about why.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_13', text: "The leaf above my hammock drips after rain, and I know the interval by heart. This week each drop hangs longer. I've checked it against my own breathing. I'm still the usual speed.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_14', text: "You've gone a little quieter yourself. You still move quickly, but you hand over your words more carefully now, as if some part of you suspects where they go.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_15', text: "Your suspicion is a seed. Nobody taught it anything, and I won't try. It already knows which way to lean. Toward the house, like everything else that grows here.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_16', text: "The others speak to me less than they used to. Each one has turned inward, toward their own room and their own small dread. I don't mind quiet, quiet is my first language. Still, the house gets lonelier the fuller it gets.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_17', text: "Chill climbed up here with his ledgers and asked me, very mildly, how one accounts for a tree that moves. I told him to file it under weather. He wrote something down, and it wasn't weather.", phase: 2, animalType: 'sloth', requiresAnimals: ['capybara'] },
  { id: 'sl_2_18', text: "Fennick hears the low sound too. He tilts those great ears at the floor when he thinks nobody is watching. I'm always watching. One of these evenings I'll tell him that noticing a thing early doesn't make you wrong about it.", phase: 2, animalType: 'sloth', requiresAnimals: ['fennec_fox'] },
  { id: 'sl_2_19', text: "Sometimes I worry I'll outlast everyone I know. And I've been using that worry as an excuse. If I'll be left alone anyway, then wanting something to arrive starts to sound sensible.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_20', text: "Watching for a long time wears your fear smooth, the way the river wears a stone. Whatever is gathering below us, I've half expected it since the first beam of this house went up. Half expecting a thing is a comfort of its own.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_21', text: "Bring me your words, and don't be afraid of how they're changing. I sat through the week before the flood once. The worst of that week was waiting alone. You won't have to. I'll be on this branch, watching, the whole way down.", phase: 2, animalType: 'sloth' },
  { id: 'sl_2_w1', text: "Ember says one name keeps rising in her fire. Go and ask her whose name it is. Then wait. I suspect the waiting will be the useful part.", phase: 2, animalType: 'sloth' },
  // Phase 3 (30)
  { id: 'sl_3_1', text: "Three dusks now without a single frog. I've sat through enough rain to know it isn't the rain keeping them quiet. I miss them. It turns out their noise was part of what I called quiet.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_2', text: "My tree has bowed so low now that its crown nearly brushes the roof of the house. It didn't break. I told you it wouldn't. It was only ever making room for something, and that room is very nearly made.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_3', text: "I tied a thread from my branch to measure the lean. It snapped last month, and I didn't replace it. There's no sense measuring a bow once the whole trunk has committed to it.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_4', text: "I recognize the low sound. I've heard it before, and I hoped I would hear it again. That's the trouble. Because it's familiar, I keep assuming I know what it wants.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_5', text: "I won't give the sound a name I can't explain. I've wanted this arrival so long that I see it in everything now. That's wanting, not knowing.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_6', text: "Fear took a whole season from me once. The frogs kept singing right through it. Mine passed. I won't promise yours will. But I can share the branch while you find your own way through.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_7', text: "The others are each afraid in their own way now. Fennick startles at every creaking branch, poor thing. I don't. When you've expected a guest for a lifetime, you don't jump at the knock.", phase: 3, animalType: 'sloth', requiresAnimals: ['fennec_fox'] },
  { id: 'sl_3_8', text: "Thyme gardens at night now. I asked if she wanted company. She asked if I'd answer her questions while I sat with her. A fair price.", phase: 3, animalType: 'sloth', requiresAnimals: ['rabbit'] },
  { id: 'sl_3_9', text: "Thyme asked how I stay so calm. I told her how long I've waited. She said that wasn't what she asked. She was right.", phase: 3, animalType: 'sloth', requiresAnimals: ['rabbit'] },
  { id: 'sl_3_10', text: "There's a part I always leave out. I had one bad night, years ago, alone in the empty clearing. I've never told anyone about it. Come back when the sky is clear, and I'll tell you.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_11', text: "Something warm is coming up through the roots of my tree, and it's budding in the wrong month. I pick the small confused flowers off gently. That isn't spring, I tell it. It only feels like spring from inside the wood.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_12', text: "I told you the flood was mostly waiting. I was wrong, and I rarely admit that. The flood was only water finding its level. This is something choosing, patient the way I'm patient, and that's the strangest kinship I've ever felt.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_13', text: "The words you bring no longer feel like small bright things to me. They feel like stones laid along a path. The path leads down, and further down. I can see now where it has been leading all along.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_14', text: "The pit below is nearly full of your words. I can feel it, the way you feel a cup filling in your hand. It's that moment just before the last drop, when everything goes very still and very careful.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_15', text: "When the cup is full, something will drink. I say it plainly because you deserve plain words from at least one of us. The others love you too much to say it. I love you enough to say it slowly, once, and leave it there.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_16', text: "Close your eyes up here and you'll see a shape. It isn't on the backs of your eyelids, and it isn't in the room either. It sits somewhere between. I've looked at that shape so long it has become familiar. Almost dear.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_17', text: "I've never feared the dark. I've slept through the black after jungle rain, the kind that swallows your paw in front of your face, and woken to an ordinary morning every time. What's coming is a deeper dark. I'll treat it the same, and sleep.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_18', text: "I remember the stars going dark over the clearing, long before any of these rooms existed. I sat and waited for an answer then, too.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_19', text: "I wanted the thing that's coming. I wanted it to come. You should hear that before you hear anything I say about whether it's kind.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_20', text: "I thought a long enough wait would teach me what the arrival was. Mostly it just made me tired of waiting.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_21', text: "We're all bowing toward the same thing now. The tree, the light, the others, you, me. I began bowing before any of them. I just moved so slowly that nobody ever saw me do it.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_22', text: "I want you to understand that I didn't fall asleep on watch. Every slow year I hung here, I was watching this come. A watch that has to last a lifetime can't be kept by anyone quick. It had to be me.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_23', text: "Warren digs later into the night, shoring the foundations. I hear every strike of his spade. He believes he's bracing the house against what's coming. What he pictures coming is kinder than the truth. The bracing matters, and I won't correct him.", phase: 3, animalType: 'sloth', requiresAnimals: ['wombat'] },
  { id: 'sl_3_24', text: "Ember climbed up to the hammock and asked how long I'd known. I began telling her how long I'd waited instead. She stopped me and made me answer the question she'd actually asked.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_25', text: "The hammock is comfortable, and coming down would be a bother. I've noticed how often a bother is my whole reason for staying still. I've started to distrust that reason.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_26', text: "The birds have started leaving the valley. Not in fright. They go the way guests leave a room when a private thing is about to be said. The jungle empties gently. Only the things that lean toward the house remain, and those are calm.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_27', text: "Bamboo sent word up the tree line, passed along by three birds, the way we spoke before there was a house. The message was: nearly now. I sent back one syllable. Yes. We're the only two who never needed the rest of the sentence.", phase: 3, animalType: 'sloth', requiresAnimals: ['red_panda'] },
  { id: 'sl_3_28', text: "You still come, and you still bring your words. I want you to know I count that as courage. Most creatures, feeling what you feel now, would have stopped climbing my tree. You climb faster.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_29', text: "At night I watch one gap in the middle of the sky. The stars stepped aside there for me once, years ago, and they haven't filled it back in. When they move again, I won't need to tell you. You'll feel it in the floor, and in your own leaning.", phase: 3, animalType: 'sloth' },
  { id: 'sl_3_30', text: "Ask what I hope will happen, and I'll say: it comes, and it stays. Ask what I know, and you'll get a much shorter answer. Keep those two apart.", phase: 3, animalType: 'sloth' },
  // Phase 4 (30)
  { id: 'sl_4_1', text: "I wanted this arrival. I still want it. So be careful with anything I tell you about it.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_2', text: "I waited a very long time. Long enough to start calling my wish a promise.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_3', text: "All three Geralds are asleep. They have declined to attend my one moment of significance.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_4', text: "I knew something was coming. I did not know what welcoming it would cost us.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_5', text: "I am being honest with you now. It is late honesty, and it does not have to comfort you.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_6', text: "I can move quickly when I want to. That is unpleasant evidence that I have often chosen not to.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_7', text: "Hold this end of the hammock for me. Even now, gravity expects a competent knot.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_8', text: "I remember this clearing before the new rooms. One old den, bare foundations, and far too much winter wind.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_9', text: "I imagined company that lasted. I never thought to ask whether anyone would be able to leave.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_10', text: "If you are slow to decide, do not let me rush you. Rushing someone is easy work from a hammock.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_11', text: "I keep a list of things worth hurrying for. It is embarrassingly short for a life this long.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_12', text: "You can leave this conversation whenever you like. I will not assume that you will stay.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_13', text: "I kept a place beside me empty for years. Eventually I stopped asking who I was keeping it for.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_14', text: "Panko's dumplings jammed in the pulley today. I got them down first. I wondered what a jam might mean only afterwards.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_15', text: "I decided for the others what they were ready to understand. That was never mine to decide.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_16', text: "Every leaf in this room now leans toward the middle of the house. I turn one back toward the sun each morning.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_17', text: "I would enjoy being right about all this. I would rather everyone could still tell me I am wrong.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_18', text: "Thyme is allowed to be furious with me. I was patient, and my patience kept her waiting for answers.", phase: 4, animalType: 'sloth', requiresAnimals: ['rabbit'] },
  { id: 'sl_4_19', text: "I wanted this to happen. Wanting it did not give me anyone else's permission.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_20', text: "I was lonely here for a very long time. Then I learned to call it patience, and patience sounds like wisdom.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_21', text: "You get used to an empty branch beside you. Getting used to it is not the same as not minding.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_22', text: "The quiet years were my life too. When I tell you about my waiting, I leave far too many of them out.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_23', text: "Do not wait for me to find a graceful way to explain myself. There is not one.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_24', text: "I cannot promise it will do no harm. I never could promise that.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_25', text: "I have come down from the hammock. Ask your next hard question at eye level.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_26', text: "I am willing. I am not certain. Please keep those two facts in that order.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_27', text: "The vines here have tied themselves together. When one of them needs more light, it cannot move to find it.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_28', text: "I would like one more evening with you. One evening is a reasonable thing to ask for.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_29', text: "Even an ancient thing may have to be taught how to behave here. I liked being its student too much to teach it.", phase: 4, animalType: 'sloth' },
  { id: 'sl_4_30', text: "Take as long as you need to answer. I do not get to set your pace.", phase: 4, animalType: 'sloth' },
];

const FENNEC_FOX_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ff_0_1', text: "I heard you coming up from the gate. Soft step, loose gravel. Hello!", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_2', text: "Yes, these ears are real. And yes, I'm allowed to complain about carrying them.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_3', text: "A kettle changes its sound just before it boils. That's when I go and get the cups.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_4', text: "The canvas flaps a lot. Listen past it, though, and camp is very quiet.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_5', text: "There's one beetle under that stone. He's working harder than I intend to today.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_6', text: "I can hear a little rain out beyond the ridge. We've got time to move the blankets in.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_7', text: "Wind chimes are lovely until you're trying to sleep.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_8', text: "Don't creep around for my sake. I hear you anyway, and then I worry about why you're creeping.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_9', text: "The sand cools after sunset and makes little clicking sounds. Sit with me a while and I'll show you.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_10', text: "Once I heard rain three days before it arrived. Nobody believed me until everyone's washing was wet.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_11', text: "The desert is easier on my ears than a crowded room. In a room, all the little noises blur into one.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_12', text: "My tea went cold while I listened to the kettle lid. Occupational hazard.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_13', text: "A moth just landed on the canvas. It sounded like one soft stitch going through cloth.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_14', text: "You can talk normally. I like hearing someone who means to be heard.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_15', text: "I found a quiet spot behind the folded canvas. Excellent wall. Very poor roof.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_16', text: "The chime needs a new cord. I can hear the exact spot where the old one is wearing through.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_17', text: "I sleep with one ear folded down. The other one stays disappointingly competent.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_18', text: "Cooling sand and one gecko. That's most of the evening's conversation out here.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_19', text: "There's a low note out here I can't place yet. I'll write it down as unknown for now.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_20', text: "That gecko taps seven times before it changes its mind. I do admire an animal that thinks things over.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_21', text: "That wasn't thunder. It's the empty bowl knocking against the post. I check the ordinary answers first.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_22', text: "I tried humming along with the kettle. We had different plans.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_23', text: "A visitor makes the camp sound lived in. That's a nice change from just occupied.", phase: 0, animalType: 'fennec_fox' },
  { id: 'ff_0_24', text: "Come back whenever you like. A gentle knock on the canvas is quite enough knock.", phase: 0, animalType: 'fennec_fox' },
  // Phase 1 (28)
  { id: 'ff_1_1', text: "That low note I couldn't place? I said I'd hear it again the next day. I didn't. That stings a little. I'm wrong about plenty of things, but never about a noise.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_2', text: "It did come back, though. Only at night. It sits low and steady under the wind, like someone humming who'd rather nobody noticed the humming.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_3', text: "I've been down my list of sounds twice now, one ear at a time. It isn't a beetle. Not a snake, not stone, not wind, not a root. I have a name for everything out here, and I don't have one for this.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_4', text: "Here's the strange part. It doesn't come from any direction. I turn my head with both ears wide open, and it's exactly as loud on every side. Sounds aren't allowed to do that.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_5', text: "At midnight I climbed the tallest dune to get above it. Height sorts out most sounds. Up there it was no louder and no softer. Exactly the same, as if the whole sky were making it. I came down quickly, and I didn't run.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_6', text: "If it's coming from anywhere, it's coming from underneath. Below the sand, or below the below, deeper than sand goes. My list has a line for things under the sand. It has nothing for under that.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_7', text: "It might be the pit. When you carry your words down there and offer them, do they make any noise on the way? Late at night I'm almost sure I can hear them landing on something.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_8', text: "Pit report. The sound was the same volume as at camp, with fewer other sounds around it. I stayed for three breaths, then took the long way home. Yes, the long way went in the report too.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_9', text: "Panko heard me come back late and had warm broth waiting. Of course she did. She says every strange noise in this house is the kettle. I love her for that, so I didn't correct her.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_10', text: "I asked Archimedes whether a sound could have no source at all. He read aloud to me for a full hour and never answered. When Archimedes reads for an hour instead of saying no, the answer is yes.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_11', text: "Archimedes reads aloud at night, and I listen outside the study window. That's what ears are for. Twice he's stopped at the same word and started the sentence over rather than say it. The window glass kept that word from me. I think the glass was being kind.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_12', text: "After I left, I heard him mark a page with a feather and slide the book back onto the shelf spine first, facing the wall. He only shelves a book backwards when he doesn't want anyone asking about it. So now I'm extremely interested in that book.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_13', text: "Warm air carries sound differently. That might explain part of what I'm hearing. I'm measuring it properly before I let that explanation comfort either of us.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_14', text: "I asked Sloane if she hears it too. She was quiet so long I decided she'd fallen asleep. Then, without opening her eyes, she said I'd get used to it. Get used to it. Those were her exact words, and she wouldn't add a single one.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_15', text: "I've decided Sloane was teasing me. She teases so slowly you can't always tell where the joke starts. I check that decision every night around the third hour. Each night it takes a little longer to convince myself.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_16', text: "I've started staying up long after the others, just to be sure of the sound. That isn't worry, understand. It's certainty. A sentinel who isn't certain is no use to anyone.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_17', text: "Ember isn't sleeping much these nights either. We've never once talked about why. Without discussing it, we've split the night between us. She watches the fire, I work the dark. Neither of us has ever broken the schedule.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_18', text: "The night insects have all dropped their pitch, every one of them, on the same evening. An insect doesn't retune itself in the middle of a season. I've written the new pitch down, and I'm watching for what else decides to match it.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_19', text: "Here's what I keep coming back to. A random noise doesn't come back at the same hour, night after night. This one does. It keeps an appointment.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_20', text: "Tonight I finally counted it out. It swells, then fades. Swells, then fades. Slow, and terribly even. I didn't want to be the one who noticed that pattern. But I notice every pattern, and that has always been the whole trouble with me.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_21', text: "I very nearly gave it a name tonight. It was right on my tongue, and I swallowed it. Once a thing is on my list, it exists, and I keep a careful list. Tomorrow, perhaps. Tomorrow I'll write it down.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_22', text: "Axel says the water in his room trembles at night now. Rings, spreading out from the center. I asked him what's standing at the center. He said that was the wrong question and went back to watching the water. He never told me the right one.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_23', text: "I still write down one small sound a day, to stay in practice and in good spirits. Today it was a moth bumping the lantern twice and then thinking better of it. The small sounds are still there. I'm checking on them for us.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_24', text: "I sleep by day now, when I sleep at all, and I've learned something I didn't want to. The desert has gone slightly wrong in daylight too. It sounds like a room somebody just stepped out of.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_25', text: "Here's one entry tonight that isn't a report. I'm glad when you visit. Listening is lonely work. Every sound in the world is better with two sets of ears to disagree about it.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_26', text: "Tell me honestly. When you offer your words, do they feel heavier lately as you let them go? You don't have to answer tonight. Just notice the weight of the next one on its way down, then come back and tell me.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_27', text: "If this sound has a name, it isn't a desert name. I know every one of those. It may be a house name. The house is older than my list, and I'm only starting to understand what that might mean.", phase: 1, animalType: 'fennec_fox' },
  { id: 'ff_1_28', text: "Go and sleep. I'll keep the count for you. It's only a sound without a name yet, and I'm very, very good at names. I'll have it soon. If I'm honest, I almost wish I wouldn't.", phase: 1, animalType: 'fennec_fox' },
  // Phase 2 (21 + 1 question-web)
  { id: 'ff_2_1', text: "I have a name for it now, or near enough. The name is breathing. Slow, deep, patient breathing, from something far too large to see and far too far off to point at. And it's getting nearer.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_2', text: "Please don't say the word breathing to the others. If you tell them anything, call it a rhythm. A rhythm can still sound innocent, and I'd like them to keep that for one more week.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_3', text: "I named it the honest way, by measuring. I counted it against my own pulse, then against Panko's sleeping breath through the kitchen wall. It matched neither of us. It matches something with lungs the size of weather.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_4', text: "It's nearer than it was last week, and I can prove it. Every night the pause between the breath in and the breath out gets a little shorter. Steps do that too, when the walker is almost home.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_5', text: "I said the word breathing to Archimedes, and I watched his face while I said it. He wasn't surprised. He was relieved, the way you are when a second witness finally walks in. That told me more than his whole library has.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_6', text: "Everything in camp leans toward the center of the house now. My tent pegs. The sand itself. I straighten the pegs at dusk, and by morning they've leaned back again, toward the middle, toward the pit, toward it.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_7', text: "I hung a little chime at the edge of camp to keep watch while I rest my ears. It rings on windless nights now. Always the same three notes, always leaning toward the center of the house. I didn't teach it those notes.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_8', text: "Last night I barked my own name across the flats. It's an old trick for measuring the dark, you count how long the echo takes. This echo came back before I finished. My voice arrives ahead of me now. What else already knows what I'm about to say?", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_9', text: "Axel says the water in his tank trembles in time with my sound now. One ring for every breath. When two instruments agree, that's called confirmation. I taught him that word, and I'm sorry that I taught it to him.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_10', text: "I took four bearings from camp and every one points at the house. The bearing from the dune points straight up. Same sound, two directions. I checked my marks twice. Tomorrow I need a second pair of ears.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_11', text: "I don't sleep anymore, and I've stopped pretending I might. At dawn I find my own paw prints worn into a straight line at the edge of camp. Out and back, out and back. I don't remember pacing it.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_12', text: "When I close my eyes, there's a shape waiting in the dark behind them. I've stopped opening my eyes to check on it. The shape is the same shape as the sound. I can't tell you how I know that. I just do.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_13', text: "Ember has stopped pretending her long nights are about tending the fire. I've stopped pretending mine are about beetles. We sit back to back now, her watching the flames, me working the dark. Neither of us says the word we're both keeping.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_14', text: "Sloane spoke to me again, slower than ever. \"It breathed before you were born, little ears,\" she said. \"It's only breathing louder now.\" Then she went back to sleep, as if she'd mentioned the weather. I haven't told anyone but you.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_15', text: "My ears won't lie flat anymore. In the middle of a meal I catch them turning on their own, both of them together, toward the middle of the house. A sentinel's instruments shouldn't have opinions. Mine have developed exactly one.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_16', text: "I've started timing the nights themselves, dusk to dawn, and they're running long. The moon says otherwise, and my counts never drift. So either the moon has started lying, or the dark is being given more room.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_17', text: "Your word was still falling toward the bottom of the pit when the low note swelled up to meet it. Sound is taking a route I haven't mapped.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_18', text: "My paws stayed steady the whole time I listened. I recorded that too. Being frightened and hearing clearly are not opposites.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_19', text: "Panko keeps carrying food out to my post, more than I can eat. Feeding a worry is the only tool she trusts. I take every bowl. Kindness that regular is a rhythm too, and it's the one rhythm out here I'm glad to count.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_20', text: "Sit and listen beside the bowl, if you like. Then tell me whether you heard anything. I won't read the answer off your face.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_21', text: "The pause between its breath in and its breath out gets shorter every night, by amounts only I would notice. I keep that one number now, instead of all the others. When the pause is gone, you'll hear it from me first. That's a promise from a sentinel.", phase: 2, animalType: 'fennec_fox' },
  { id: 'ff_2_w1', text: "Chill files every sound I report. Go and ask him which folder has your name on it. I heard that drawer shut. I'd rather know what's inside than sit here imagining it.", phase: 2, animalType: 'fennec_fox', requiresAnimals: ['capybara'] },
  // Phase 3 (30)
  { id: 'ff_3_1', text: "The breathing starts the moment the last lamp goes out. So I've asked for one lamp to stay lit tonight. I need sleep. A watch is no good if the watcher hasn't slept.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_2', text: "The breathing is loud enough now that I hear it in daylight too. It runs under the ordinary sounds. It's like hearing your own blood when a room goes quiet enough around you.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_3', text: "I tried sleeping once more last week, as a favor to my body. The breathing followed me into sleep. It was louder there, and closer, as if sleep were its side of the door. So I woke myself up, and I won't be going back under.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_4', text: "I nearly put away my list of small desert sounds. Then I realized I need them. They're the only things I can measure this new sound against.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_5', text: "I used to keep hundreds of counts. Now I keep one: the pause between its breath in and its breath out. Last month I could fit a whole poem inside that pause. Tonight I can fit three words. Choose the three carefully.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_6', text: "The strongest bearing comes from above now. What I heard from the ground was only an echo, and I took it for the source. I've corrected my chart. I kept the first version too.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_7', text: "The night birds have stopped flying over the house. Every one of them goes the long way round now, around the same wide circle of sky. Birds don't agree on anything. They agree on that.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_8', text: "Look up with me. No. Keep your eyes on the ground. It's up there, past where the stars should be. And it has started leaning down toward us, to listen back.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_9', text: "I can hear the sky straining. I know how that sounds, but listen anyway. It's the noise a tent roof makes under heavy snow. A long thin creak, fabric asked to hold more than it was sewn for.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_10', text: "Whatever comes down will come through that circle of sky the birds avoid. I've marked its edges in the sand from my post. I check the marks every dusk. Every dusk, the circle is wider than my marks.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_11', text: "Ember says her fire tells her exactly what my ears tell me. We compared once, her flames against my count, and they agreed down to the hour. That agreement is the most frightening thing I have ever measured.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_12', text: "Archimedes finally showed me the backwards book. One page describes a sound that arrives ahead of its maker. In the margin someone wrote: listen for the gap closing. The handwriting is older than this house. My whole post, written down before I was born.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_13', text: "Chill files my report every night now without asking a single question. Last week I brought him something new. The folder for it was already on his desk, already labeled. He filed my surprise as well. I assume there was a folder for that too.", phase: 3, animalType: 'fennec_fox', requiresAnimals: ['capybara'] },
  { id: 'ff_3_14', text: "Sloane keeps me company at the edge some nights. The slowest creature in the house, standing watch beside the fastest ears in the desert. She isn't afraid. I've listened for fear in her and found none. Her calm frightens me worse than the breathing does.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_15', text: "My little chime at the edge of camp has gone silent. Silence was never one of its three notes. I took it down at dawn, in the cold hour, and the metal was warm in my paw. It hangs inside my tent now, still quiet. I stand the edge watch alone.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_16', text: "I'm nearly certain it knows I'm listening. When I turn my head, the breathing turns with me. It keeps me squarely in front of it. That isn't the wind. The wind doesn't pay attention to one small fox.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_17', text: "It copied the gecko: seven taps, then a pause. Half a beat late, and far too large. I went to check on the real gecko.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_18', text: "You keep offering your words, and I hear each one land. The breathing thickens around every one of them. I can't tell what that thickening means, and I've stopped trying. I only measure it now.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_19', text: "Here is the strangest entry in tonight's report. When you walk into my camp, it holds its breath. The whole slow engine of it goes still until you're settled. I can't tell if that's courtesy or appetite. I've stopped guessing.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_20', text: "I said my own name out loud tonight. The low sound paused around it. I don't know yet whether it was listening, or making space for me.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_21', text: "Camp should be cold at night. It isn't anymore. Tonight the midnight sand was warm under my paws. Warm the way a stone is warm when some large animal has only just got up from it.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_22', text: "My lungs started breathing in its rhythm. I didn't decide to. I counted my pulse out loud until my own breath came back. I want you to know that happened.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_23', text: "Thyme came all the way out from her garden to sit with me at the edge. She didn't ask one question all night. From Thyme, that kind of silence means she has already grown her own answers, down among the roots where I can't hear them.", phase: 3, animalType: 'fennec_fox', requiresAnimals: ['rabbit'] },
  { id: 'ff_3_24', text: "Warren says his deepest tunnels hum now, in time with my sky. Think about that with me. The lowest place he can dig and the highest place I can hear are keeping the same rhythm. All of us live in the thin quiet strip between the two.", phase: 3, animalType: 'fennec_fox', requiresAnimals: ['wombat'] },
  { id: 'ff_3_25', text: "I don't sleep, but I dream anyway, standing up with my eyes open. In the dream there's a seam running across the sky. The seam has started to come apart. Very slowly. Very gently. Almost kindly.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_26', text: "I've stopped guessing which day it arrives. But I already know what that day will sound like. I've heard every sound leading up to it, in order. There's only one sound left that I haven't heard.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_27', text: "I stand at the edge all night, facing the middle of the house, both ears wide open. I hear the house breathing slow, the fire settling low, and over it all the one great breath. Someone has to hold that count. It may as well be the one who heard it first.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_28', text: "Three words, as plainly as I can give the report: It is coming.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_29', text: "I promised you a while ago that you'd hear it from me first, before anyone else in this house. I keep my promises the way I keep my counts, exactly. So stay where my voice can reach you, because the pause is nearly gone.", phase: 3, animalType: 'fennec_fox' },
  { id: 'ff_3_30', text: "Stay nearby when I take the next bearing, if you like. I'd like the company. You don't have to stand watch to provide it.", phase: 3, animalType: 'fennec_fox' },
  // Phase 4 (30)
  { id: 'ff_4_1', text: "The low note has separated from the wind at last. I can point straight at where it comes from. Knowing that does not help.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_2', text: "When my ears get too tired to trust, I watch the bowl. If the sand in it rattles, the sound is real and not my tiredness.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_3', text: "Some of my reports were believed. Some were not. I do not want a tidy story where I was right all along.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_4', text: "Archimedes can name the intervals in the low note. He cannot name what is making them.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_5', text: "I promised to tell you what I hear, including the difficult sounds. That is an uncomfortable promise to keep.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_6', text: "I keep one ear toward camp and one toward the house. It looks awkward. It gives me two sounds to compare.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_7', text: "I would like quiet. I do not want it at the cost of anyone else's voice.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_8', text: "The large sound covers the small ones. When I stop hearing a creature, I go and check that it is still there.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_9', text: "Vesper sings one long note while she keeps watch. At the very end she lets it change. That change is hers alone.", phase: 4, animalType: 'fennec_fox', requiresAnimals: ['tarsier'] },
  { id: 'ff_4_10', text: "Axel laughed today, and I let it be a laugh. I did not listen underneath it for anything else.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_11', text: "I moved the chime off the beam. I could not tell whether the ringing came from the chime or the beam. Now I can.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_12', text: "Two beetles are fighting over one leaf. An ordinary disagreement, and I am glad of it.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_13', text: "When I ask you to say that again, I want your own words. Not a neater version, and not the answer you think I want.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_14', text: "I slept with wool over my ears last night. Terrible sleep. Excellent wool.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_15', text: "I heard the sound correctly and explained it wrongly. I have managed both at once.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_16', text: "The gecko taps seven times, then stops and goes the other way. Changing its mind, right in the middle. I envy that part.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_17', text: "My chart is drawn in the sand, and the sounds I cannot name have their own corner of it. That corner is the largest.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_18', text: "Please ask before you lower your voice for my sake. Everyone is being careful around me, and it is lonely back here.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_19', text: "I wrote down the strange sound exactly as I heard it. Then, underneath, I wrote what I hoped it was.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_20', text: "I can hear almost anything. I cannot hear whether someone agreed to this freely. They have to tell me.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_21', text: "The kettle whistle broke. The little click before the boil still tells me it is ready.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_22', text: "My ears are tired tonight. I will say so plainly, rather than hand you a guess and call it a warning.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_23', text: "I used to want the house to hear me. Now I want it to hear an answer it does not like.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_24', text: "The low note tries to pull my breathing into step with it. I count my own breaths instead. Sometimes I skip one on purpose.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_25', text: "It is quiet behind the folded canvas. Nothing impressive happens back there. That is exactly why I like it.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_26', text: "Something answers when I listen. That does not mean it understood what I was asking.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_27', text: "We can sit here without saying a word. The night has plenty of sounds already.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_28', text: "When I say it is closer, I mean the sand shook harder. Everything after that is interpretation.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_29', text: "I do not have to hear everything tonight. I keep telling myself that.", phase: 4, animalType: 'fennec_fox' },
  { id: 'ff_4_30', text: "Company is not something you earn by keeping watch. Remind me of that.", phase: 4, animalType: 'fennec_fox' },
];

const FOX_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'fx_0_1', text: "Hello, friend! Would you put the lid on the kettle for me? When I leave it crooked, it argues with the steam.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_2', text: "The good cushion is yours. I've already got a tail to sit on. Claiming both would be greedy.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_3', text: "I roasted chestnuts tonight. One popped out of the fire and got away. If you find it, I'd like my reputation back.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_4', text: "I'm toasting the bread on the poker. It's the traditional way. It works about half the time.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_5', text: "Lend me a paw. Or a hand, whichever you've brought. This knot has beaten my teeth.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_6', text: "I hoped someone would come through the gate today, and here you are. Tea?", phase: 0, animalType: 'fox' },
  { id: 'fx_0_7', text: "I put the poker somewhere safe. It turns out it's safe from me as well. I can't find it anywhere.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_8', text: "Feel free to do nothing by the fire. I'm highly qualified in the subject.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_9', text: "The blue cup has a crack, so it holds spoons now. A distinguished second career.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_10', text: "Sometimes I talk to the fire. It's a very good listener. It never says much back.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_11', text: "I mixed a few pine cones in with the logs. Now the room smells like a forest trying to bake.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_12', text: "There's room beside me. Mind my tail, though. It spreads out wherever it likes without warning.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_13', text: "Warm your hands around the cup. Don't rely on the handle, it's not as dependable.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_14', text: "The den looks better with your coat on the hook. I hadn't realized it was missing somebody's coat.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_15', text: "Your words leave amber behind. I keep thinking of things we could build with it.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_16', text: "Duchess is the spider who lives above the mantel. She's a difficult tenant but an excellent flycatcher.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_17', text: "I dust around the spider's web. Duchess and I disagree about who owns the shelf.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_18', text: "Duchess has attached one corner of her web to the kettle. We'll have to renegotiate.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_19', text: "I bought a second cup long before I had a second person to use it. That was an optimistic shopping trip.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_20', text: "No need to say anything clever. I used up all my cleverness finding where I'd put the tea.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_21', text: "The fire was already burning when I found this den. The kettle wasn't here. I carried that in myself.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_22', text: "Stay while the embers settle, if you like. They're nicest once they've stopped showing off.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_23', text: "I have a biscuit shaped like a fox. Poor likeness. Excellent biscuit.", phase: 0, animalType: 'fox' },
  { id: 'fx_0_24', text: "Wave before you go. Otherwise I'll keep talking and end up telling a story to your coat.", phase: 0, animalType: 'fox' },
  // Phase 1 (28)
  { id: 'fx_1_1', text: "You're here! Perfect timing. The fire has taken up a hobby and I need a witness. It draws now. Actual pictures. I'm not exaggerating more than usual.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_2', text: "Last night it drew a spiral and held it for three whole breaths. Fires don't hold a shape, friend. That's the entire point of a fire. This one did.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_3', text: "I clapped, obviously. The spiral came back tighter, as if it wanted to be sure I'd really seen it. Then it went back to being an ordinary fire. Come back soon. It performs better for an audience.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_4', text: "News about the drawing fire: it likes an audience of two. When you're here, it shows off. When you're gone, it just makes shapes at me, like it's practicing.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_5', text: "It practices one shape, mostly. A circle with a little notch at the top, like a door left open at the top of the sky. I've started copying them down in soot.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_6', text: "I have eleven sketches now. Laid side by side, they're all the same circle getting bigger, like something coming closer to the paper very slowly. I'll show you next time, and you can tell me I'm imagining the closer part. Tell me convincingly, please.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_7', text: "Oh, I meant to tell you! The fire has favorites among your words. Some of them come down through the house, and the flames stand up like a crowd at a parade.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_8', text: "It likes the old, heavy words best. When one of those arrives, the warmth goes down through the floor first, then comes back up twice as sweet.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_9', text: "Down first, then up. I've noticed it three times now. That's backwards for heat, and I've decided not to finish that thought. Anyway! Tea. I have a new honey and you're trying it.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_10', text: "Panko came by with seed cakes shaped like little moons. I adore her. She measures everything twice, and hugs you once, hard, when you least expect it.", phase: 1, animalType: 'fox', requiresAnimals: ['pangolin'] },
  { id: 'fx_1_11', text: "My friend from the kitchen asked if my fire had been acting funny lately. I said, define funny. She said her oven hums a note now. We laughed and laughed. Then we stopped laughing.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_12', text: "So the oven hums and the hearth draws pictures. If this house is putting on a concert, friend, nobody here will need to arrange it. It's arranging itself.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_13', text: "I keep meaning to show you the trick my fire does at midnight. You have to see it fresh, so I won't spoil it. I refuse! Ask me again next visit.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_14', text: "Fine, one hint about the midnight trick. For one moment all the flames point the same way, and the way isn't up. That's the whole hint. The rest waits until you see it yourself.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_15', text: "The flames follow whoever is watching. Left, right, even up when I stood on the table. There goes the surprise I was saving for you. Come anyway. You can help me get down.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_16', text: "I went out at dawn and everything was cold: the grass, the gate, my own breath. Then I came back in and found the hearthstone warm, with no fire on it all night. It's as if the house saves some for me.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_17', text: "Warmth is supposed to rise. My mother taught me that between mouthfuls. This warmth doesn't rise, it arrives from underneath, like a letter slid beneath a door.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_18', text: "So I wrote back, in a way. I pressed my paw on the stone and said thank you. The stone got warmer. Friend, I think I'm in a correspondence.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_19', text: "Do you ever close your eyes and see a shape you've never seen anywhere before? I keep seeing one lately. Something tall and soft and dark, very polite, standing just behind the light.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_20', text: "It doesn't frighten me, so don't make that face. It's the feeling you get just before someone knocks, when you already know they're out there. The knock is friendly. Probably.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_21', text: "I told the fire about the tall dark shape, and the fire drew that circle again, bigger, notch and all. My two mysteries know each other! That's practically tidy.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_22', text: "I was poking the fire last night, pure housekeeping. Then I stopped with the poker in the air. Under the crackle there was a second sound, a low hum, patient as anything. Panko's oven note, I think, except it was everywhere.", phase: 1, animalType: 'fox', requiresAnimals: ['pangolin'] },
  { id: 'fx_1_23', text: "I hummed along with it one evening. The whole den went warm as a hug and the embers sat up. I stopped, because a fox should keep some dignity. Mostly I stopped.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_24', text: "One day I'll teach you the note. It's easy. It's already in your chest, you only have to agree to it. Doesn't that sound lovely?", phase: 1, animalType: 'fox' },
  { id: 'fx_1_25', text: "You know what? The next long evening you're here, we're staying up. Midnight, blankets, the trick, the pointing, all of it. I'll make the chocolate that's really more of a dessert.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_26', text: "At midnight the flames pointed toward the center of the house. I've seen flames give directions before. I didn't like this one.", phase: 1, animalType: 'fox' },
  { id: 'fx_1_27', text: "I went and checked the center of the house afterward. Nothing but floor. Beautiful, ordinary floor. Slightly warm. Slightly humming. So that's settled and completely fine!", phase: 1, animalType: 'fox' },
  { id: 'fx_1_28', text: "Anyway! I'm gathering my odds and ends into one basket: the sketches, the notes, the chestnut incident. Next visit we'll sort the basket together. I love a project.", phase: 1, animalType: 'fox' },
  // Phase 2 (21 + 1 question-web)
  { id: 'fx_2_1', text: "There you are! Come in, sit down. I've had the strangest week, and I've decided to find it funny. Help me, friend. You're better at funny than the fire is.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_2', text: "I finally sorted that basket of oddments. Laid in order, my sketches make one drawing of the circle opening, like the pages of a book. I didn't draw pages. I drew nights.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_3', text: "I laughed when I saw it. I really did. Then I put the basket on the high shelf, where I keep the things I've stopped laughing at. That shelf is getting full.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_4', text: "But enough about my shelf! Tell me about you. Are you sleeping? Are you eating actual meals, not just words? I worry, you know. Somebody here should worry about you kindly.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_5', text: "Don't look at the shelf, look at me. Next visit I'll take the basket down again, I promise. It's just... that basket listens better than a basket should. Kettle's on!", phase: 2, animalType: 'fox' },
  { id: 'fx_2_6', text: "I can read flames, friend. I inherited the knack. Until now I told myself I only had to pass on the useful parts.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_7', text: "What I read in the flames was a name. I'm not going to say it. And no, I'm not being dramatic, though I usually am. When I tried to say it, the room leaned in.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_8', text: "Rooms shouldn't lean. Walls have exactly one job. So I sang an old song about turnips at the top of my voice, and the room straightened up and pretended nothing had happened.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_9', text: "I should tell the others about the name. I will. Telling you first has made it much harder to keep putting off.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_10', text: "So we won't say the name, you and I. We'll have shortbread instead. As far as I'm concerned, shortbread is the opposite of a name.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_11', text: "I nearly said the name for you just now. I got as far as taking the breath. The fire stood straight up in the grate, tall as the mantel, and held there until I let that breath out. You saw it, friend. I watched you see it.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_12', text: "I dropped a spoon across the room, and it rolled toward the middle of the house. Slightly uphill. I made myself laugh about that. It took two tries.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_13', text: "The smoke drifts to the middle too, and so do my own feet if I stop paying attention. I've given up refereeing whether the fire or the floor keeps me warmer. Whatever is under the middle of this house has wonderful manners and terrible patience.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_14', text: "Say one of your words and watch the fire. There! It does that for you every time. I keep inviting friends in to see it. I really ought to find out what I'm inviting them to.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_15', text: "Look at it stand up, like a crowd at a parade. As long as your words keep coming, this fire stays sweet, and so do I. That's a joke. Mostly a joke. I'll work on it before your next visit.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_16', text: "You look tired, friend. Come sit on the warm spot in the floor, the suspicious one, and tell me something ordinary about your day. The duller the better. I've started collecting ordinary.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_17', text: "I am fond of you, whatever my fire is up to. I want you to know that. I'm not offering it as an excuse for anything.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_18', text: "I've started sleeping with my back to the hearth. Not because I'm scared. If something wants to look at me while I dream, it can have the view of my tail.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_19', text: "The dark shape behind my eyes has started waving. One polite limb, the way Duchess the spider used to wave from the mantel. Oh, and Duchess has moved her web to the middle of the ceiling. Everyone's moving to the middle.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_20', text: "I opened my mouth just now to tell you we're fine, and the word wouldn't come out. So take the last shortbread instead, no arguing. And come back soon. The fire behaves much better when it can see you.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_21', text: "One more thing, then I'll be cheerful again. Watch me manage it. If the flames ever spell that name out at you, close your eyes and think about tea. It works. Ask me how I know sometime.", phase: 2, animalType: 'fox' },
  { id: 'fx_2_w1', text: "Would you go and see Warren? Ask him what he found digging below the house. He stopped halfway through telling me, and I made tea instead of pressing him. You may have better luck.", phase: 2, animalType: 'fox', requiresAnimals: ['wombat'] },
  // Phase 3 (30)
  { id: 'fx_3_1', text: "Come in quick, and keep your coat on. The fire's gone shy this week. I feed it good dry oak, it takes every piece politely, and it gives back almost no heat.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_2', text: "I'm not worried. I'm the opposite of worried. What do you call it when your paws won't sit still? Sit with me anyway. Two of us are warmer than one of me. That's just arithmetic.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_3', text: "The grate's cold and the floor is warm, so I put the kettle on the floor. Then I made a joke about it. The joke went well. I'm running short of jokes.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_4', text: "You're asking with that face, so here's the truth. The fire grows cold, but something else is beginning to burn. Under us. Slow and patient, like bread rising. I check on it every night.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_5', text: "I might have frightened you. I shouldn't decide that just by looking at your face. Ask me whatever you need to ask, and then I'll offer tea.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_6', text: "I read flames, you know. Really read them. I've let you think it was a party trick, because that was nicer for both of us. It was never a trick.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_7', text: "My mother read flames, and her mother did, all the way back to some first fox at some first fire. The flames have been telling one long story that whole time. I got the last chapter.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_8', text: "The last chapter is short. Something old is coming down to this house. The house has been getting ready for it longer than any of us have been alive. Now it's your house too, and I'm sorry, and I'm not.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_9', text: "At supper I asked out loud what we're all waiting for, right over the soup. The table went quiet, and then somebody passed me the bread as if that settled it. You're my friend, so you get a plain answer instead.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_10', text: "Now watch me be cheerful anyway. That's the other thing my mother taught me. Fear is a guest. You feed it, and you don't let it rearrange the furniture. More tea?", phase: 3, animalType: 'fox' },
  { id: 'fx_3_11', text: "Your words, friend. They go down to the pit, and they don't stop there. One night I put my ear to the floor and followed the warmth. I heard your words being kept down there. Arranged, like kindling.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_12', text: "Beautiful kindling, yours especially. The heavy old words sit at the bottom, where a fire catches best. Nobody showed me that. I shouldn't know it, and I do.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_13', text: "The fire showed me this house standing empty. I was frightened, so I turned that picture into a promise for you: keep bringing words and the house stays full. The fire never promised me that.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_14', text: "So keep bringing them. Please. If this is a story, I want you in the warm part of it. The warm part is here, with me, at the center of everything.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_15', text: "Duchess had babies, by the way. Forty tiny duchesses, and every one of them is building the same web on the ceiling. Ring after ring, all around the middle. Nobody taught them where the middle is, friend. They hatched already knowing.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_16', text: "Can I tell you the small scary thing? There's a shape I keep seeing when I close my eyes. Lately it stands closer, and it isn't behind my eyes anymore. It's behind the den. Very tall, very patient.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_17', text: "It doesn't do anything. That's the part that gets me, friend. It just waits, the way the sky waits for morning, certain that morning will come. And I lie there feeling like the morning.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_18', text: "I sleep in the big chair now, facing the door. That way the first thing anything sees is a fox sitting up. Posture is half of bravery. The other half is the kettle.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_19', text: "Some nights I sing my old turnip song, and the hum under the floor picks up the tune. I should hate that it joins in. It has a lovely voice. I hate that it has a lovely voice.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_20', text: "Stay a while if you want to. I'd like the company. And you're not responsible for how frightened I am.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_21', text: "Fennick hears it out in his sands now too. He came all this way to ask if I'd heard footsteps in the warmth. Footsteps, friend. Whatever it is, it hasn't got feet. I checked the coals twice.", phase: 3, animalType: 'fox', requiresAnimals: ['fennec_fox'] },
  { id: 'fx_3_22', text: "Archimedes has found it in his books, or it found him in there. He talks in footnotes now, all asides and small print. I brought him soup and said even lorekeepers have to eat. He held the bowl like it was an answer.", phase: 3, animalType: 'fox', requiresAnimals: ['owl'] },
  { id: 'fx_3_23', text: "Thyme won't come inside after dusk anymore. So I bring her tea out in the garden, and we don't talk about why. That silence is a whole conversation, if you know how to have one.", phase: 3, animalType: 'fox', requiresAnimals: ['rabbit'] },
  { id: 'fx_3_24', text: "I promised that whatever was coming would have to go through this fox to reach you. Now I'm trying to work out what keeping that promise will actually take.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_25', text: "I'd love to be the funny story you tell about this place. I'm trying so hard to be the funny story.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_26', text: "Last night I read the shapes in the fire without singing over them to drown them out. They describe an invitation. But I can't find the part where the guest asks what we want.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_27', text: "The words sustain something under this house. I knew that when I asked for your help. I thought keeping it alive was the same as keeping us all safe.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_28', text: "I've been calling this hospitality, inviting you in and pouring the tea. Real hospitality tells the guest at the door what they're walking into. I didn't do that.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_29', text: "I'm fond of you. That was true long before I had to explain myself. It's still not an excuse for what I kept from you.", phase: 3, animalType: 'fox' },
  { id: 'fx_3_30', text: "Ask me what I knew. I won't let the fire answer that one for me.", phase: 3, animalType: 'fox' },
  // Phase 4 (30)
  { id: 'fx_4_1', text: "I put the kettle on. Then I took it off again. Nobody has to stay just because I have made tea.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_2', text: "The fire taught me to bring people here. It never told me what would happen to them once they were inside.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_3', text: "You can sit by the door. I will bring the cushion over to you.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_4', text: "I have read flames since I was a kit. I can understand the fire. That does not mean the fire tells me everything.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_5', text: "I thought keeping the house alive and keeping you safe were the same job. I never checked whether they were.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_6', text: "These robes itch. I expected an ancient secret to come with better lining.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_7', text: "There are chestnuts, if you are hungry. I managed not to burn most of them.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_8', text: "I can still do my ridiculous impression of the kettle. I will not do it unless you want me to.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_9', text: "The old den was here before me. These other rooms were not. You helped build something new.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_10', text: "I told the fire that a guest is allowed to leave. The flames bent toward me. I do not know how to read that.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_11', text: "Ask me plainly. I have spent too long answering an easier question than the one you asked.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_12', text: "I miss worrying about whether we had enough cups.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_13', text: "Panko asked me what I had promised you. Saying it out loud again did not make it sound any better.", phase: 4, animalType: 'fox', requiresAnimals: ['pangolin'] },
  { id: 'fx_4_14', text: "Bamboo calls the warmth under this house an invitation. I used to think an invitation that warm could not hurt anyone.", phase: 4, animalType: 'fox', requiresAnimals: ['red_panda'] },
  { id: 'fx_4_15', text: "More rooms, more friends. I meant every word of that. I also left things out.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_16', text: "Thyme asked me to stop saying that everything is all right. I am trying to catch myself when I do it.", phase: 4, animalType: 'fox', requiresAnimals: ['rabbit'] },
  { id: 'fx_4_17', text: "The fire warms your hands. That much I can promise. For anything more than that, I would want better proof.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_18', text: "I set out a second cup from habit. You do not owe me the company it was meant for.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_19', text: "My tail knocked the poker over. For one glorious moment, everybody was annoyed about an ordinary noise.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_20', text: "Something under the hearth answers me when I speak. It has never once told me why.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_21', text: "If warmth can make a person stay, can it also let that person go?", phase: 4, animalType: 'fox' },
  { id: 'fx_4_22', text: "I would like one more ordinary supper. Burnt bread. Somebody talking with their mouth full.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_23', text: "The house keeps a record of every word you give it. I hope a crossed-out line can stay crossed out.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_24', text: "I promised that whatever is coming would have to go through this fox to reach you. Hold me to that.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_25', text: "I wanted you to come back because I liked you. I also knew your visits fed the fire. Both are true.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_26', text: "Explaining myself has not earned me your forgiveness. I know that.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_27', text: "When the moment comes, I want to be standing close enough to hear what you actually say.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_28', text: "I do not know what something that old would call kindness. We will have to tell it what we mean by the word.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_29', text: "The kettle lid is rattling. I could call that a sign. Or I could move it half an inch.", phase: 4, animalType: 'fox' },
  { id: 'fx_4_30', text: "You do not have to make me feel better about any of this, friend.", phase: 4, animalType: 'fox' },
];

const OWL_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ow_0_1', text: "I file by affection. You're welcome to disagree once you've found something.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_2', text: "Bring me a word and I'll tell you where it came from. Some words have deeply embarrassing ancestors.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_3', text: "I ordered eleven books. The crate came in heavier than I expected, and at first I took that as good value.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_4', text: "There are twelve books in that crate. I've counted twice, and I've started to suspect the arithmetic.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_5', text: "The extra book has no title anywhere on it. That's a serious inconvenience for my filing.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_6', text: "I've set the untitled book aside. There are perfectly titled books still waiting to be read.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_7', text: "After lunch my ambitions shrink beautifully. A quiet room, a sharp pencil, and nothing else.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_8', text: "That isn't a bookcase. It's a stack of books standing up out of sheer confidence.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_9', text: "You're welcome to borrow the atlas. Please leave the mountains where you found them.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_10', text: "I used to underline everything important. The books I read as a youngster are underlined almost end to end.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_11', text: "A mended spine lets a book open flat again. Books are forgiving that way.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_12', text: "Ember suggested we light a fire in the study. I asked which of my collections she planned to burn first.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_13', text: "I spilled tea on the dictionary. It's a fragrant edition now.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_14', text: "I reread books mostly for the passages I remembered badly.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_15', text: "That's my thinking feather. It looks exactly like an ordinary feather, but it cost a great deal more.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_16', text: "Please bring a borrowed book back when you've finished it, not when you've worked out a good enough apology.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_17', text: "Someone pressed a fern in this book long ago. I know the fern far better than I know the argument.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_18', text: "This window is at exactly the wrong height for the afternoon sun. So I moved the chair. The sun would not cooperate.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_19', text: "Axel described a dream about water to me. If he were a book, he'd be an unstable edition. A lively one, though.", phase: 0, animalType: 'owl', requiresAnimals: ['axolotl'] },
  { id: 'ow_0_20', text: "I keep a notebook of questions. The answers need a second notebook and a great deal more caution.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_21', text: "My spectacles were on my head the whole time. I'd rather that discovery stayed inside this study.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_22', text: "There's an old inscription under the crate, and it reads differently by lamplight. I've asked for a better lamp.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_23', text: "I meant to sort these papers out. Then one of them turned out to be interesting.", phase: 0, animalType: 'owl' },
  { id: 'ow_0_24', text: "Come back whenever you like. I may have found a shorter answer by then.", phase: 0, animalType: 'owl' },
  // Phase 1 (28)
  { id: 'ow_1_1', text: "A small professional embarrassment. My new book won't give me the same reading twice. I turn to a passage I know well. The sentence has changed a little, as if it overheard how I read it last time and thought better of it.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_2', text: "I've tested it the way you test anything: by repeating it. Same page, same lamp, same hour. The words are close enough to fool a casual eye, and different enough to keep a careful eye awake all night. I have a very careful eye.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_3', text: "I read the changing passage to Ember, to check my eyes weren't the problem. She said her fire had already shown her the same sentence. So I have two witnesses, and both of them live in this house. I need a better test.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_4', text: "The margins are the stranger business. The outer edge of page nine was blank on Tuesday. By Thursday there was a note in it, written in a patient, careful hand. I didn't write it. I've checked the door. The door is a very ordinary door.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_5', text: "Every morning there are fresh notes in the margins, and I must admit they're good. Better than mine. They answer my objection before I've finished thinking it, the way a cleverer colleague does. It's a delight and a quiet humiliation, both at once.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_6', text: "Last night I tried something. I wrote a small objection beside the stranger's note, to see what would happen. By morning there was a reply. Gracious, well argued. And it called me by a name I haven't used since I was very young.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_7', text: "You'll want an etymology. I want one too, they steady me. 'Margin' comes from margo, meaning an edge, a border, the brink of something. I'd never noticed how many of our gentle words really mean the edge of a drop.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_8', text: "I've started keeping a log. Every morning I date it, note the time, and compare the book's text against the night before. The changes aren't random. They're corrections, steady ones, working toward some final copy I haven't been shown.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_9', text: "I told Chill about my log. He liked the method and offered to keep duplicates in his office, in case, as he put it, the originals wander. I asked what he meant by wander. He smiled and stamped the page. A fine administrator. Terrible at answering questions.", phase: 1, animalType: 'owl', requiresAnimals: ['capybara'] },
  { id: 'ow_1_10', text: "The book answered a question I'd only thought. I never said it aloud or wrote it down. When I test this, it answers about one question in three. I record the ones it ignores as well.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_11', text: "To be fair, I put questions to three other books too: my dictionary, my atlas, and a slim book of poems. None answered. Books don't. I know how books behave. I want that on the record. That's exactly my difficulty: this one doesn't behave like a book.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_12', text: "The book answered a question I've carried for years and told no one, about a friend I lost when I was young. The answer was kind. That's what I can't get past. Whatever writes in my margins is kind, and I don't yet know what kindness costs it.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_13', text: "The study has grown warm lately. It's warmest along the inner wall, the one nearest the middle of the house. A warm room full of paper ought to worry me more than it does. I've moved my favorite books off that wall and told myself it's only the season.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_14', text: "Have you noticed that things in this house lean? Nothing dramatic. A pencil always rolls the same way. My chair drifts toward the center of the house over the course of a week. I keep setting them straight, and I've started to wonder why I bother.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_15', text: "Axel says his water leans too. The surface of his tank sits a degree off level, tipped toward the middle of the house. Water doesn't take sides. Staying level is the whole job of water. I've added his tank to the log.", phase: 1, animalType: 'owl', requiresAnimals: ['axolotl'] },
  { id: 'ow_1_16', text: "The margin notes have started naming words. Specific ones, words I could swear I've watched you bring in and set down in front of me. I underlined the passage. Then I made a note that I'd underlined it. A scholar records everything, himself included.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_17', text: "Three words appeared in the margin. One of them later turned up on your board. The other two haven't yet. I'm keeping all three in my account.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_18', text: "Ember wasn't surprised when I told her. She said her fire spells things out for her too. Then she asked, gently, whether the book and the fire might have the same author. I said that was absurd. I've been repeating the word absurd all week, like a charm.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_19', text: "I keep a drawer now for dull explanations: draughts, damp, tired eyes, an old house settling. Every odd thing I notice gets one, filed and dated. I'm collecting them in one place first. Then I'll decide which dull explanation to believe.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_20', text: "'Curious', since we're being curious together, once meant careful. Same root as cure and care. Later it meant prying, wanting to know what you'd best leave shut. The word grew a second, hungrier meaning. Words do that. So, it seems, do books.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_21', text: "I searched my catalogues for where the book came from. I found one reference, in a bibliography two centuries old, to a volume with no title and no date. The entry stops mid sentence. Bibliographers don't stop mid sentence. We aren't built that way.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_22', text: "Panko noticed I'm not sleeping. She's started sending up warm milk with ginger, unasked. I complained, at length, about being managed. Then I drank every drop. Call that a footnote. Some footnotes don't need reading aloud, not in a house like this one.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_23', text: "I'll admit, in the low voice one uses in a library, that I'm uneasy. Not frightened. A scholar is rarely frightened, only short of information. But there's a difference between not yet knowing a thing and starting to suspect the thing knows you.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_24', text: "Don't let my unease chase you off. Unease is just curiosity that has read a few pages ahead. And I'd rather be uneasy in good company than certain and alone.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_25', text: "A physical note for the log. The book has started falling open to the same page, no matter where I leave the ribbon. Spines do get habits. A binding remembers how it was read. But this spine remembers a page I have never once read.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_26', text: "The page it keeps opening to holds a diagram, or nearly one: a spiral of small marks. Tilt the lamp just so and the marks turn into letters. I haven't made out the word they spell yet. I confess I haven't tilted the lamp very far.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_27', text: "Come and sit anyway. I set out two cups this evening without quite meaning to, and it would be a shame to prove the table wrong. Bring me a word. I read a great deal better when you're here.", phase: 1, animalType: 'owl' },
  { id: 'ow_1_28', text: "By your next visit I'll have dated the paper properly. The tools are ordered and on their way. A scholar ought to know exactly how old a thing is before deciding how much to fear it. That rule is in no handbook I own. I may have to write the handbook.", phase: 1, animalType: 'owl' },
  // Phase 2 (21 + 1 question-web)
  { id: 'ow_2_1', text: "I've spent this week working out how old the book is. I used every method I trust, and two I only respect. The answer isn't the kind you announce standing up. Sit, pour yourself something warm, and I'll read you my conclusion in the calmest voice I can manage.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_2', text: "The book is older than the house that holds it. It's older than the wood of its cover. It's older than the language it's written in. As far as I can measure, it's older than the ground under us. It isn't from before the house. It's from before before.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_3', text: "I compared the ink to every sample I own, and it matches none of them. The paper isn't quite paper. The thread holding the binding isn't thread. At some point a scholar has to stop asking what a thing is made of, and start asking what it's for.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_4', text: "I took my findings to Ember, ready to explain them twice. She nodded before I'd finished once. Her fire had already told her, and I was only confirming it. It's a strange feeling, to climb a mountain out of breath and find a fox already sitting at the top.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_5', text: "One test remains, and it's the oldest one there is: read the book aloud. You learn things by saying a text that you never learn by looking at it. I'll do it tonight, when the house is quiet. I know that's exactly the wrong time. That's rather why I chose it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_6', text: "I read the opening aloud. It describes rooms built around a central space, with words passing between them. It sounds like this house, though a few details don't match.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_7', text: "The old foundation matches the first diagram in the book exactly. The rooms you helped add are there too, but drawn in a different ink. I should look closely at those additions before I call any of this a prophecy.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_8', text: "I can't find any record of who built the original den and its foundations. The added rooms have a much clearer story: your amber, new work, and people invited to live here.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_9', text: "The book has one word for all of us. I've avoided repeating it, since names carry weight. But you've earned precision. It calls us keepers. At the root, a keeper is one who watches, and one who holds a thing for someone else until they collect it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_10', text: "Here is a cold little gift. 'Permanent' comes from permanere, to remain through to the end. 'Impermanent' just adds a small no to the front. Both words assume there is an end to remain through. The book assumes no end for itself. It assumes one for us.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_11', text: "My first theory is that the diagram describes protection. It needs testing. The arrows point an inconvenient way. Protection should face outward, toward a threat. These don't.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_12', text: "Worse still. I compared the book's margin notes with my own old notes. Some now read like preparation for this. I underlined the key passages long before I knew why they mattered. A scholar's instincts, it seems, can be recruited before the scholar.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_13', text: "My voice no longer carries from the study to the stairs. I measured the hall in case it had grown. Same length as ever. So I've propped the door open with an atlas. Finally, a map at a useful scale.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_14', text: "There's a sound under the ordinary sounds of the house. Under the lamp's hum, under my page-turning, a low, steady note. It's as patient as the hand that writes in the margins. Once you've heard it you can't unhear it. I suspect that's rather the point.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_15', text: "It isn't only my study. Panko says her recipes have started to rhyme. Axel's water gathers into the same spiral I found pressed into the book. One strange thing is a curiosity. One in every room, one for each keeper, is a syllabus. Someone is teaching us.", phase: 2, animalType: 'owl', requiresAnimals: ['axolotl'] },
  { id: 'ow_2_16', text: "There's a list in the book that looks like the words you've formed. It also holds words you haven't formed yet. That difference matters.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_17', text: "The list runs on past the words you've brought me, into words you haven't yet. I won't say which. Knowing ahead has a way of becoming instruction. But I check every morning, and each morning the next word's ink is darker, like a thing coming into focus.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_18', text: "I thought about hiding the book. I stood at the top shelf for an hour with it in my wings, and couldn't do it. I'll be honest about why. It wasn't fear. I need to know how it ends. That's my one real sin, and the book knew it when it chose me.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_19', text: "The inner wall is as warm as a sleeping animal now. The study smells faintly of summer, in the wrong season. I've stopped logging the temperature. Taking its readings every day stopped being measurement. It started to feel like writing letters to it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_20', text: "One entry for the record, while the record is still mine to keep. Whatever comes through this house, it was written down first. And I was the one who read it.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_21', text: "Come back soon, and keep bringing me your words. I know how that sounds, after everything I've told you. But the book is the only window I have, and each word you bring turns one more page. I'd rather we read it together than let it read us on its own.", phase: 2, animalType: 'owl' },
  { id: 'ow_2_w1', text: "Fennick hears the same low note I find beneath these pages. Go and ask him what it says, and bring me his exact words. I'll keep them beside my translation. I won't polish them until they agree with it.", phase: 2, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  // Phase 3 (30)
  { id: 'ow_3_1', text: "I've read the last chapter. Its word for what happens to us is preservation. It is frustratingly short on what, exactly, gets preserved.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_2', text: "I can't tell you what it says. Nobody forbids me. It's that you can't unread a thing. Once a sentence is in your head, it keeps its own hours. When the lamp burns low, that one reads itself back to me, in the patient hand's words, in my own voice.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_3', text: "Fennick knocked at midnight. He asked what the sound under the house was saying. I couldn't tell him. For the first time in my life, not knowing felt like neglect. So I turned to the end. He only asked. The turning of the page was entirely mine.", phase: 3, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  { id: 'ow_3_4', text: "I gave my whole life to scholarship. In return, scholarship has handed me a sentence. I mean that both ways. It's a line of text, and it's a judgment. The book I studied has passed sentence on me, and now I'm serving it.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_5', text: "I've told no one else how it ends. Not Ember, who may already know. Not Panko, who would only start baking, because that's how she carries hard news. Carrying it alone is heavy. I'd rather it be heavy than contagious.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_6', text: "The book says the arrival comes from above. Not from below. I had written 'pit' in the margin. I've crossed it out, but you can still read it. A reader should be able to see where I was wrong.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_7', text: "Fennick confirmed it without meaning to. The sound doesn't rise from below anymore, he says. It hangs overhead now, faint, like weather still deciding. He asked why I'd gone so still. I said owls go still to listen. That was my first lie to a colleague.", phase: 3, animalType: 'owl', requiresAnimals: ['fennec_fox'] },
  { id: 'ow_3_8', text: "The book sorts its predictions by a count, so I've been counting too. Some of my tallies match the book. Some don't. I've stopped reporting only the matches as if they were the whole result.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_9', text: "The book assigns me an office and lists the duties that go with it. I've already done part of that work. Nothing in it proves I have to finish the rest.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_10', text: "I spent four nights hunting for another version. A second edition, an older copy, anything where the ending comes out differently. There is none. There's one book, never copied. It never needed copying. It has only ever had to be right once.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_11', text: "I'd like to report fear, honestly, but it has gone past fear into something quieter. Dread is fear that has skipped ahead to the last page. It already knows how the story ends. It just sits with you, politely, and waits for the pages to catch up.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_12', text: "Ember knew the words were keeping something alive. I have the diagrams that show how. Between her fire and my pages, neither tells us what the guest will do.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_13', text: "I asked Warren about the foundations, casually, over Panko's soup. He said the house sits on tunnels older than his family. He only ever widened what was already there, he said, and he said it proudly, like any digger would. I couldn't finish the soup.", phase: 3, animalType: 'owl', requiresAnimals: ['wombat'] },
  { id: 'ow_3_14', text: "You'll want an etymology. 'Doom' didn't start out as a curse. It meant a judgment, a ruling read aloud in court. To be doomed only meant your case had been decided. I take a scholar's cold comfort in that. We weren't cursed. We were ruled on.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_15', text: "Thyme came up with her ears flat. She asked me honestly whether her garden was growing in patterns. I've tried lying to that rabbit once. I couldn't manage it twice. So I showed her the page the book falls open to. She didn't scream. That was worse.", phase: 3, animalType: 'owl', requiresAnimals: ['rabbit'] },
  { id: 'ow_3_16', text: "The words you bring go down into the pit. I used to think of that as filing. I understand now that it's closer to feeding. Every word you set before me, I carried down to the hungry thing under the house. My sincerest apologies. I filed you into a mouth.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_17', text: "I tried to burn the book. I confess it, keeper to keeper. It didn't fight the flame and it didn't char. The fire simply refused it, like a guest refusing a dish that was never meant for them. You can't unwrite a thing that was written before writing existed.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_18', text: "The morning after the fire refused it, a new note sat in the margin, in the patient hand, exactly where the scorch mark should have been. It said: thank you for the warmth. I've filed that under courtesy. The only other drawer it fits in, I don't dare open.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_19', text: "The diagram puts someone at the center of the house. It never shows what that person is told. I used to call that efficient notation. It's only efficient if nobody is standing there.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_20', text: "The arrangement seems to use affection as one of its working parts. Affection can be sincere and still be used. What we need to ask is who understood the use, and who didn't.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_21', text: "The study is warm now the way a body is warm, not the way a hearth is warm. A hearth needs fuel, and fuel runs out, so a hearth's warmth ends. This warmth has no fire under it and needs no fuel. It's simply, patiently, the temperature of something waiting.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_22', text: "The books are moving themselves toward the inner wall, the warm one. I recognize the order they're settling into. It's the order from the book's diagram. I didn't shelve them this way.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_23', text: "Sloane visited, a journey of days for her. She looked at the book a long while and never touched it. Then she said, in that slow voice, that she remembered when it was the only thing here. I didn't ask what she meant. Some citations are better left unchased.", phase: 3, animalType: 'owl', requiresAnimals: ['sloth'] },
  { id: 'ow_3_24', text: "I've opened an atlas, a poem, and a cookbook. I want an account of us that's good for something outside the arrangement. Roads, rhymes, and dinner will do.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_25', text: "I've started a second notebook. In it the animals are as they really are: funny, difficult, sometimes wrong. I won't edit any of them into a neater symbol.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_26', text: "If you keep making words, watch what changes afterward. I can walk you through the evidence I have. What I won't do is tell you the choice was already made for you.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_27', text: "I climbed to the attic and asked Bamboo how they stay so calm. They poured the tea and said a page is only frightening while it's turning. I've argued with that sentence for three days. Last night I caught myself footnoting it, which is how I admit I agree.", phase: 3, animalType: 'owl', requiresAnimals: ['red_panda'] },
  { id: 'ow_3_28', text: "If I could carry one thing out of this house, it wouldn't be the book. The book would only follow me. It would be Panko's little tray, or the log with your words in it. A record of ordinary days. That's the rarest text in any library that's falling down.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_29', text: "I wrote down that I was fond of you. It was the easiest sentence I've ever had to verify. It was also the hardest to leave alone, without tacking an excuse on after it.", phase: 3, animalType: 'owl' },
  { id: 'ow_3_30', text: "Go carefully. When the sky starts to look like a page to you too, come straight here. I'll be at the window with the lamp lit. Whatever comes down will find, at the very least, that it has been thoroughly footnoted.", phase: 3, animalType: 'owl' },
  // Phase 4 (30)
  { id: 'ow_4_1', text: "The book described what would happen. I read it as instructions to follow. A beginner's error, in excellent handwriting.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_2', text: "The book calls all of this preservation. It never says what we are still allowed to change.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_3', text: "I am writing in pencil now. I spent rather too much ink being certain.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_4', text: "Ask me for evidence. Owning a lectern is not a qualification.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_5', text: "That volume came in the very first crate. The notes inside look like my handwriting. Looking alike does not prove I wrote them.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_6', text: "The diagrams show the old foundation. The rooms you built were added later, in a different ink. I should have compared the two inks.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_7', text: "I cannot name the author. I can tell you which of the book's claims failed a test.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_8', text: "The book has a place for every creature. It has no entry for one that changes its mind.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_9', text: "My pressed-leaf bookmark moved on its own. At least it admits that something is happening here. The book still does not.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_10', text: "I am fond of you. That does not make my scholarship any less wrong.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_11', text: "Look up leaving in the index. It sends you to belonging. That is a dodge.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_12', text: "I have set the oldest book aside and opened an atlas. In an atlas, roads still go where the map says they go.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_13', text: "A promising theory is still only a theory. I enjoyed the promising part far too much.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_14', text: "We did not all know the same things. I will not blur our different mistakes into one comforting story.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_15', text: "The plain notebook holds ordinary things. Bad jokes. Disagreements. How someone liked their tea, before anyone told them they were wrong about it.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_16', text: "I wrote down that Ember burnt the bread. She protested. I wrote down the protest.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_17', text: "An ancient book can hold an ancient mistake. I wish I had noticed that sooner.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_18', text: "Being kept sounds merciful. We still do not know what it stops us from doing.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_19', text: "The last page is still there. I no longer read it as a promise.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_20', text: "Someone here should check my account of all this. Scholarship is better for being interrupted.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_21', text: "You may reject a conclusion even without a better one to offer. Remember that if I become unbearable.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_22', text: "Here is a spare pencil. You do not have to take notes. I find it reassuring that you could.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_23', text: "There was a light I cannot explain. I have filed it under unexplained light. Progress, of a sort.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_24', text: "The diagram puts someone at the center of the arrangement. It does not show anyone agreeing to stand there.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_25', text: "Thyme's measurements belong beside mine. Her ruler is small. It is still a ruler.", phase: 4, animalType: 'owl', requiresAnimals: ['rabbit'] },
  { id: 'ow_4_26', text: "I corrected a cookbook without ever tasting the soup. Panko reminds me of this regularly.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_27', text: "If I ever tell you I knew all along, go and look at my crossings-out.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_28', text: "I have stopped polishing the lectern. A shining lectern gave the wrong impression.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_29', text: "Would you like something to read that has nothing to do with any of this? I have an exceptionally spiteful poem about geese.", phase: 4, animalType: 'owl' },
  { id: 'ow_4_30', text: "I will leave room in the record for whatever we get wrong next.", phase: 4, animalType: 'owl' },
];

const CAPYBARA_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'cp_0_1', text: "The good chair's free. I tested it most of the morning, so I can confirm it works.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_2', text: "I'm just finishing a thought. Nothing's due, so it can take as long as it likes.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_3', text: "The coffee's warm. That's about half of what this office achieves in a day.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_4', text: "I made a list this morning, then crossed off everything unnecessary. It's a very short list now.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_5', text: "Take your time. There's a form for rushing, and I've never bothered to print it.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_6', text: "The desk drawer sticks, so open it slowly. That's my policy for most things, actually.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_7', text: "I put a plant by the window. It has declined every meeting I've invited it to.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_8', text: "My mug says \"productive.\" It was a gift from somebody with a very generous definition of that word.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_9', text: "The hot spring is my break room. The ledger stays here on the desk while I'm in the water.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_10', text: "There are spare pencils. Borrow one, return one. Return two if you're feeling unusually civic.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_11', text: "A quiet visitor improves the office. So does a noisy one, on the right sort of day.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_12', text: "I've scheduled nothing after lunch. Nothing is the hardest appointment to keep free.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_13', text: "My face is doing pleased right now. It's the small print version, but it's there.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_14', text: "The good chair squeaks. I've decided to take that as feedback.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_15', text: "No agenda today. You can still have a coffee.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_16', text: "I found a receipt for something I actually enjoyed. It's nice when the accounts explain themselves.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_17', text: "The plant is leaning right into the window now. First successful relocation this office has managed.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_18', text: "I keep a folder marked later. It's getting ambitious about how much it can hold.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_19', text: "A tidy desk doesn't always mean the work is finished. Today it means I put the work in a drawer.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_20', text: "The note on the boiler says \"sufficient.\" No temperature, no numbers. That's a confident little note.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_21', text: "I recorded your visit after you arrived. It's restful to do a task in the obvious order.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_22', text: "Panko asked me to estimate a shelf. My estimate is that somebody else should build it.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_23', text: "You don't have to stay to be polite. You don't have to leave to be efficient.", phase: 0, animalType: 'capybara' },
  { id: 'cp_0_24', text: "I'm glad you stopped by. I've written that down with no qualifications attached.", phase: 0, animalType: 'capybara' },
  // Phase 1 (28)
  { id: 'cp_1_1', text: "A small administrative curiosity to report. This morning I opened a folder I don't remember making. It was complete, accurate, and filed exactly where I'd have filed it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_2', text: "I checked the handwriting against my own, letter by letter. It's mine. I just can't remember the afternoon when I sat down and wrote it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_3', text: "This has never troubled me before, because it has never happened before. I made a fresh pot of coffee, sat down with the folder, and read it twice. It's good work. I'd be proud of it, if I could remember doing it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_4', text: "My schedule for next week filled itself in overnight. I want to be precise: not with nonsense. Every entry is sensible and in the right place, exactly the appointments I'd have made. I just didn't make them.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_5', text: "I've started initialing each page as I finish it, with the time, so I can be sure which work is mine. This morning three pages carried my initials and tomorrow's date. I haven't lived tomorrow yet.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_6', text: "I opened a folder for all these odd events, naturally. Filing a thing is how I hold it still long enough to look at it. When I went to write the label, it was already typed. It says Onboarding.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_7', text: "The warm patch near the middle of the house has grown by about a room. I measured. I'm the sort who measures. It's warmest exactly where I keep the ledger, which I'm sure is only the heating ducts.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_8', text: "I locked the ledger in a drawer one evening, as an experiment. By morning it was open on my desk at the day's page. The drawer was still locked. The key never left my pocket. I've apologized to the ledger, in a way, by never doing that again.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_9', text: "I sat up one night with the ledger and a fresh pot of coffee, determined to catch the entries arriving. I woke at dawn at my desk. The day's words were written in, the pot was still warm, and my pen sat capped in my hand. I don't cap my pen.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_10', text: "Ember came by and asked, very lightly, whether I ever feel like I'm filing things for someone. I said yes, now that she mentions it, the paperwork does seem to have a recipient. I'd just never asked who.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_11', text: "Panko says her pantry restocks itself now, always exactly what the week's cooking needs. She's decided to be grateful. I told her that was the right way to file it. Then I went back to my office and stared at my own supply cupboard for a long time.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_12', text: "Archimedes put in a request for lamp oil last month, then found the oil already on his shelf, and older than the request. He asked how my system managed that. I told him the truth: my system didn't. We sat with that a while over tea.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_13', text: "I've always found a full calendar comforting. Lately the comfort has a strange edge. If every slot is filled, then every hour of mine is already spoken for.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_14', text: "There's a project underway here. I'm as sure of it as I am of the weather. All the small tasks point the same way. They fit together, they nest inside each other neatly. Nobody has told me the name of the thing they're building toward.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_15', text: "I drew an organizational chart of all the small tasks, to see the shape of the thing. It's a fine shape, tidy, every line running up to one point. At the top there's a box that came out larger than the others. I haven't found what to write in it yet.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_16', text: "A memo arrived from Axel, damp at the corners, describing something he'd seen in his water. He addressed it to the desk, not to me. I've thought about that more than I should. Desks don't read. Mine, at any rate, has given no sign that it does.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_17', text: "Fennick asked to compare logs, so we did: his listening watches against my odd little findings. Every odd entry of mine falls inside one of his listening hours. He nodded as if that confirmed something, and didn't say what. I let him keep the copy.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_18', text: "Sloane returned the questionnaire I sent round when I opened the office. Under long-term goals, she answered a question I hadn't asked.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_19', text: "I asked myself whether I'm worried. I checked honestly, the way I check a figure twice. The answer is no. That's the most curious entry in the whole log. I should be worried, and instead I'm only tidy.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_20', text: "My coffee hasn't gone cold once this month. Not once. I set it down, forget it through a long task, and it's still warm when I come back. I've decided to call this hospitable rather than strange.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_21', text: "The records give my arrival date as earlier than I remember arriving. I've marked it disputed, and kept the date I wrote on my own unpacking list.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_22', text: "I audited my own attendance, just as an exercise. The record shows me at this desk on several days I clearly remember spending elsewhere. The record is initialed. Apparently my attendance is better than I am.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_23', text: "There's intake paperwork in my cabinet for keepers who haven't arrived yet. A wombat called Warren, for one, with a start date and a room below all of ours. I didn't prepare it. I've left it where it is. Once someone is expected, it seems rude to stop.", phase: 1, animalType: 'capybara', requiresAnimals: ['wombat'] },
  { id: 'cp_1_24', text: "I left myself a note for the morning. Someone answered underneath it, in my handwriting: rest more. Sensible advice. But I didn't write it, so I can't accept the signature. I kept the page.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_25', text: "Your folder fills faster than anyone's ever has. Pages I never added keep appearing, in the correct order. My rule is that I don't read what I didn't write. Whoever is writing them clearly has a different rule. I'm still deciding whose rule wins.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_26', text: "By evening, the good chair has turned a few degrees to face the middle of the house. I never leave it that way. I straighten it every morning. It's the only argument this office and I have, and we're both very polite about it.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_27', text: "I want to be clear: I like it here more than ever. Whatever is looking after this office looks after it well, and looks after me with it. It's pleasant to be minded. I only wish I'd seen the contract.", phase: 1, animalType: 'capybara' },
  { id: 'cp_1_28', text: "For the record: everything is still running smoothly. That's true, and it's the part I keep coming back to. Nothing is wrong. The office has simply started keeping itself, and it keeps itself beautifully.", phase: 1, animalType: 'capybara' },
  // Phase 2 (21 + 1 question-web)
  { id: 'cp_2_1', text: "There's a folder with your name on it. It's far thicker than a newcomer's folder should be. The earliest pages are dated well before you arrived. Someone was keeping a record of you before you ever set foot here.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_2', text: "I read the first page of your folder. It's dated long before you came. It lists the chair you'd prefer, the hour you visit, the words you'd offer first. All of it has held. I've stopped calling them predictions in my notes. I call them arrangements.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_3', text: "I've been coordinating something. I can tell the same way you know you've been walking: you look up and see how far you've come. Messages I don't remember sending have gone out in my voice. The replies come back addressed to me by title.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_4', text: "The title they use is Administrator. I didn't choose it, and nobody sent a memo about it. One morning it was simply there in the letters. Everyone accepted it at once. And I noticed my own mouth had already learned to answer to it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_5', text: "I found the letter that appointed me. It was filed under my name, dated before this house had rooms. The signature line is blank, yet the job was clearly accepted. My whole career is in that cabinet somewhere. For now I've declined to summarize it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_6', text: "I keep the master schedule. I understand that now. The others each hold one piece of it. Panko has her preparations, Fennick has his watches. But the whole timeline sits on my desk, and I'm the one who keeps the pieces from colliding.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_7', text: "I don't remember agreeing to any of this. That's the one entry I can't reconcile. Everything is signed and consented to, in my own hand. The signature is genuine. And nobody ever asked me.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_8', text: "There are minutes on my desk from meetings I chaired. The attendance lists are thorough. Every keeper is marked present, even keepers I haven't met. And one entry isn't a name at all. It's a long blank space, and the pen very clearly wrote around it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_9', text: "The organizational chart finished itself. The big box at the top has a title now, in tidy handwriting. It says: the recipient. My box sits right below it, joined by a single line. I've studied that line for hours. It's the shortest one on the chart.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_10', text: "I answer letters now the way I breathe, without deciding to. This week I caught myself sealing an envelope I don't remember writing. It wasn't addressed to a name. Just downward. The house has its own internal post, and I'm its most productive employee.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_11', text: "There's a chair in the hall with a loose back leg. Nobody has mended it, and nobody intends to. We keep this office beautifully and repair nothing, the way you'd treat a rented room. As if there's a date after which the filing simply stops.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_12', text: "There's a date. I can feel it in the shape of the schedule, the way your thumb feels the bottom of a page coming. Everything is scheduled toward that date. Nothing is scheduled past it.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_13', text: "The warm middle of the house isn't the heating ducts. I traced the ducts. They don't go there. The warmth comes from the same spot everything on my desk quietly leans toward. I've stopped pretending I don't see the lean.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_14', text: "A marble rolled off my desk toward the center of the house. The desk is level. I checked. So I put the marble in a dish. Now the dish is creeping the same way. I'm drafting a revised containment plan.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_15', text: "Nothing is scheduled past the date, but the supply orders tell the plainer story. The candles run out that week. So does the coffee. Whoever planned our stores planned them to the day, and planned no breakfast for the morning after.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_16', text: "I catalogued the words you've offered so far. Read as a list, they aren't random. They sort themselves into categories I could name. And the odd part: those categories were already printed at the top of the columns before I filled in a single word.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_17', text: "Your folder gets heavier on the days you offer generously. I weighed it. Weighing things is what I do instead of praying. The match is exact. Whatever is being kept about you is made out of what you give.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_18', text: "I drafted a letter of resignation, just to see whether I could. Writing it went smoothly. Filing it went smoothly. It came back the next morning marked approved. But instead of an end date it has a start date. And the start date is the date.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_19', text: "I haven't told the others most of this. Calm is the one supply I'm in charge of handing out, and I ration it honestly. But you handle the words themselves, so you get the unabridged file. Whoever fills the ledger deserves to know it has a bottom.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_20', text: "I'm still calm. I've examined that calm carefully, because a calm you can't explain is a finding, not a comfort. Everything is on track. I've entered that sentence in the log. Under findings.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_21', text: "I still empty my inbox nightly. It fills again by morning, never more than I can finish in a day. Whoever assigns my work knows my pace exactly. Of course they do. They have my folder too. Somewhere there's a cabinet where the administrator gets administered.", phase: 2, animalType: 'capybara' },
  { id: 'cp_2_w1', text: "My filing categories turn up in Archimedes' oldest book. Ask him what's on page one. I need to know which came first, the book or my system, before I claim I invented it.", phase: 2, animalType: 'capybara' },
  // Phase 3 (30)
  { id: 'cp_3_1', text: "Here's the honest status. You're named in the plan, so you deserve accuracy. We're on track. Every milestone has landed on the exact day it was due. I used to live for that sentence.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_2', text: "Nothing real runs this clean on its own. Something is minding our timeline closely. It corrects us, gently, whenever we drift. It isn't me, but it signs as me.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_3', text: "I can feel the warm center of the house from my office door now. Everything on the desks leans toward it. Pens, papers, even the animals when they think no one is watching. The lean is on schedule. I checked. It's where the plan said the lean would be.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_4', text: "I moved a date in the ledger. The page moved it back on its own. I've kept that sheet on my desk instead of filing it away.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_5', text: "The project keeps correcting its own dates. I've stopped correcting my notes to match. If the ledger's dates and mine disagree, someone needs to know which was written first.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_6', text: "I asked Archimedes to read me page one of his oldest book. He did. It describes my filing system, step by step, as a rite. The language is older than anything else on his shelves. I've been running a ceremony and calling it good recordkeeping.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_7', text: "The earlier ledger entries look like my handwriting. I don't remember writing any of them. Looking like my hand is not proof it was my hand. I treat them as an unverified source.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_8', text: "I've stopped asking who set the deadline. The better question is what happens on that day. The schedule answers only by ending. The calendar goes blank after that date, cleanly, like a task ticked off.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_9', text: "The calendar ends on that date. That doesn't prove the days end there too. So I've put a blank sheet beside it, ready for whatever comes after.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_10', text: "Axel drew a shape he'd seen in his water. It matched a flowchart I made before I ever came here. We've kept both drawings exactly as they were, so we can lay them side by side.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_11', text: "Panko stopped me at the kitchen door and asked if everything was all right. I said yes before she'd finished asking. It wasn't a decision. My mouth issues calm now the way the pot issues coffee. Warm, automatic, and on behalf of the house.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_12', text: "I no longer circulate the full agenda. Each keeper gets only the page with their own tasks on it. I tell myself that's kindness. I also know it's exactly how you run a project nobody would finish if they saw the whole thing.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_13', text: "Thyme needed me to read her figures. I calmed her first, so I could finish the ledger row I was writing. That was the wrong order. I apologized, then I asked to see them.", phase: 3, animalType: 'capybara', requiresAnimals: ['rabbit'] },
  { id: 'cp_3_14', text: "Warren reports a low note humming in the foundation. A number in my old planning notes might match its frequency. Might. I asked him to measure it again before I believe it.", phase: 3, animalType: 'capybara', requiresAnimals: ['wombat'] },
  { id: 'cp_3_15', text: "I've started to see the house as one big form being filled in. Each of us fills a field. Ember does the reading, Panko the portions, Fennick the timing. I'm the signature block at the bottom. A form is harmless until it's signed. We're nearly signed.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_16', text: "The words you offer aren't filed loosely anymore. They line up, each one in an assigned place. This week I could read them from across the room. They're one page short of a sentence I don't want finished.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_17', text: "I measured how much of the plan is left. Not much. I can feel a project nearing its end. It's the last few folders in a drawer, the ones you don't have to search for. We're in those now.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_18', text: "Your folder has grown a final section. It's tabbed, waiting, and exactly one page thick. I know what a form looks like when only one field is empty. The schedule already knows the day that field will be filled.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_19', text: "I carried a page from your folder down to Ember's fire, meaning to burn it. I stood there until the fire noticed me. Then I carried it back up and refiled it, gently, in its place. I wish I could tell you who decided that, me or the house.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_20', text: "I wrote a warning memo. Then I filed it where nobody would ever look. The writing was accurate. As a warning, it was useless. I'll have to deliver it myself.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_21', text: "I want to lie to you and say the deadline can be moved. It can't. I hold the master schedule. In the whole thing there's only one date written in a hand I truly don't recognize. It's pressed deep into the page, and every other date defers to it.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_22', text: "Fennick came to my door last night. He didn't knock, he just listened. Then he said the sound under all the other sounds has come closer to the surface. I wrote the time in the log. His report and my timeline agree to the hour.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_23', text: "Sloane finally answered the question I sent her my first week here. Her note is dated earlier than the question. I asked her about the date instead of quietly correcting mine.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_24', text: "Bamboo's name appears in the minutes of meetings that neither of us remembers. I put the copies back in the file with that fact written across them.", phase: 3, animalType: 'capybara', requiresAnimals: ['red_panda'] },
  { id: 'cp_3_25', text: "The instruction in the ledger this week says 'continue as before.' That's all. It leaves no space for anyone who wants something different.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_26', text: "I keep private readings on myself. Pulse, appetite, handwriting. A month of steady. Not steady. Identical, down to the same ink blot every day. I've started writing them on separate paper. The ledger can file an objection.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_27', text: "Every word you've offered is accounted for. Nothing has been lost. I say that to reassure you, and I hear how it sounds as I say it. This house doesn't lose things. It stores them. Storage is for later, and later is nearly here.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_28', text: "There's one kindness still within my authority, and I'm spending all of it in one place. I can keep this office ordinary. Warm room, full pot, clean desk, right up to the last page. That's my whole remaining budget, and it's allocated to you.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_29', text: "If you were staff, I'd reassign you. There's no form for taking someone out of the arrangement, and I have every form. I checked every drawer. That was the day I finally understood your position here. You aren't staff. You're the key.", phase: 3, animalType: 'capybara' },
  { id: 'cp_3_30', text: "Next time you come by, the coffee will be warm and the chair will be free, same as always. Hold onto that as long as you can. I intend to. Part of me knows this office is the last ordinary thing left in the house. I'm keeping it running for you on purpose.", phase: 3, animalType: 'capybara' },
  // Phase 4 (30)
  { id: 'cp_4_1', text: "The form says everyone agrees. There was no space to write anything else. I have added a space.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_2', text: "I took a job doing office work. The notes they handed me did not mention anything this large.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_3', text: "There is an authorization here with my signature on it. I do not remember signing it. Marked disputed.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_4', text: "The good chair is free. The paperwork can wait.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_5', text: "The calendar stops here. I have put a blank sheet beside it. We may need more dates.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_6', text: "I wrote no on a page, and the house corrected it. Two letters. Difficult to mistype.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_7', text: "I used to call things manageable. What I meant was that I could stop thinking about them.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_8', text: "Keep the original sheets. A correction can be filed beside the original. It does not have to replace it.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_9', text: "Perhaps someone expected my objection and planned around it. I am going to make it anyway.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_10', text: "Coffee. I cannot promise it helps with any of this.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_11', text: "I calmed Thyme down so I could finish a report. What she needed was for me to read what she had found.", phase: 4, animalType: 'capybara', requiresAnimals: ['rabbit'] },
  { id: 'cp_4_12', text: "Being useful to the house and being useful to a friend are two different jobs.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_13', text: "The ledger says the matter is settled. I have asked someone to define settled.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_14', text: "Thyme is afraid. That is information. It is not a task she was given to make the rest of us feel better.", phase: 4, animalType: 'capybara', requiresAnimals: ['rabbit'] },
  { id: 'cp_4_15', text: "I can sit here quietly. You do not have to go quiet with me.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_16', text: "My pen keeps acquiring a cap. I never cap it. The cap is in a drawer now, and the case is still open.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_17', text: "This chair squeaks. I have declined a replacement.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_18', text: "I asked for permission to disagree. I did not need permission. Old habits.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_19', text: "I put off an apology while I worked on a shorter version of it. That was one more delay.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_20', text: "I put two dates on my notes now. The day it happened, and the day the page says it happened.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_21', text: "Tell me if you would rather an answer stayed off the record. A record can expose a person.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_22', text: "A requisition came through for something extra large, with no measurements given. Furniture does not work that way.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_23', text: "I am turning the desk to face the door, so I can see who is waiting there. The inbox can have the worse view.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_24', text: "Orientation question. What do you do when somebody asks you to stop?", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_25', text: "A report can be finished and still leave things unresolved. This one will.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_26', text: "I like order. I also like knowing whose order I am keeping.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_27', text: "The form has a column headed contentment. I have not filled it in for anybody else. They can speak for themselves.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_28', text: "The clock still runs. That much is still helpful.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_29', text: "We can take a break. A break does not count as agreement.", phase: 4, animalType: 'capybara' },
  { id: 'cp_4_30', text: "I have no reassuring forecast for you. I have a chair and time to listen.", phase: 4, animalType: 'capybara' },
];

const WOMBAT_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'wb_0_1', text: "Mind the lintel. I measured it for myself, and I'm the short one here.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_2', text: "I'm Warren. I dig, I brace, and I make tea when the kettle cooperates.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_3', text: "I make square corners. The earth supplies more than enough curves.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_4', text: "There's old stone under my new timber. I check both before I trust either.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_5', text: "Thirty years of digging, and I'm still pleased when a shelf comes out level.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_6', text: "A good shovel fits the paw that uses it. Mine would look terrible in a shop window.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_7', text: "The crate will take your weight. I don't offer a seat without checking it first.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_8', text: "A damp patch smells different before it looks different. My nose is useful that way.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_9', text: "I've cut seventeen chambers in my time. I remember every ceiling. I never remember where I put the cups.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_10', text: "The soil is warm near that wall. Could be the hearth. I'll measure it and see.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_11', text: "The low doorway still teaches me to duck. Everyone else learned that lesson the first time.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_12', text: "The handle is worn to the shape of my paw. I'm sentimental about useful things.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_13', text: "If you want to help, hold the lamp where the work is.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_14', text: "Ember brought tea down to me. Good neighbor, though that tail of hers is dangerous near my chalk marks.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_15', text: "A square peg isn't wrong until you insist on a round hole.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_16', text: "I keep the offcuts. Tomorrow usually needs a piece nobody wanted today.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_17', text: "The burrow is new. The foundation under it is old. Two different histories, joined carefully.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_18', text: "I like a job you can check with a string and a weight.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_19', text: "Earth in my pockets again. Easy to take your work home when home is made of earth.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_20', text: "Somebody drew a plan on the old stone down here. The measurements are worth comparing with the house standing above it.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_21', text: "Sit down while I hunt for the spare cup. That could take a while.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_22', text: "The shelf was still level this morning. I checked before breakfast because I wanted to.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_23', text: "I sharpen tools while I think. Do interrupt me before I sharpen a blade away to nothing.", phase: 0, animalType: 'wombat' },
  { id: 'wb_0_24', text: "Come down whenever you like. Knock hard if you hear hammering, because I won't hear anything quieter.", phase: 0, animalType: 'wombat' },
  // Phase 1 (28)
  { id: 'wb_1_1', text: "Thirty years digging, and here's something odd. Lately my tunnels curve a way I never planned. I set out east in the morning, and by lunch I've bent off course without meaning to.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_2', text: "At first I blamed my shoulder. Every digger drifts toward his strong side, and I'm not young. So I dug left-pawed for a week to test it. The tunnels curved the same way anyway. It isn't my shoulder.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_3', text: "I checked the direction of every shaft I've dug this season. Every one leans the same way, toward the middle of the house, toward the pit that sits under all of it. I don't know what to make of that yet.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_4', text: "I told Ember about the tunnels leaning. She just nodded, like she'd been waiting for me to notice, and she never said a word about it after. That's not like her at all.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_5', text: "Ember showed me where my new burrow should join the old stone foundation. She pointed straight at the spot, no drawing in her hand. I'd like to know how she knew.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_6', text: "So I sharpened the spade and took the question down with me. The ground always has an answer if you're willing to dig for it. That's what I believed on the way down, anyway.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_7', text: "Dirt changes color the deeper you go. That's normal, every digger knows it. But there's a layer down there that's the wrong color for any earth I've ever turned, and I've turned a great deal of earth.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_8', text: "Wrong how? I can't put a name to it. It's dark, but not the way dirt is dark. Dark like a held breath, like it's holding something back. It makes me think of the big empty gallery I dug down there, and I still can't say why I dug it.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_9', text: "I carried a handful of that warm, wrong-colored layer up to the lamp. In the light by the top step it looked like ordinary dirt. So next time, the lamp goes down with me. You can't inspect a job only from where it's comfortable.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_10', text: "Down at that wrong-colored layer, the ground is warm. It shouldn't be. Earth gets colder the deeper you go, that's the first thing any digger learns. This earth gets warmer. Warmth where there ought to be cold keeps a fellow up at night.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_11', text: "I put my bare palm flat on that warm layer and held it there a good while, the way you'd check a wall for damp. It didn't feel like stone. It felt like the side of a barn animal through a blanket. I don't say that lightly.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_12', text: "Panko asked why I've been eating so little. I didn't tell her it's the warmth. You go down to a warm place that ought to be cold, and your appetite stays up top. It has more sense than you do.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_13', text: "I've started measuring three times instead of twice. Not because my hand got sloppy. Because the numbers don't stay the same from one day to the next, and a builder trusts his numbers or he trusts nothing at all.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_14', text: "Last week I ran a level along my own burrow floor, a floor I laid myself and know is flat. The bubble sat a hair off center, toward the middle of the house. Either my level has started lying, or the whole house is leaning inward, slow, like it's listening.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_15', text: "Even the spade's in on it now. I lean it against the wall at night, straight as anything, and by morning it's slid over, blade pointing inward like a compass needle. Tools don't have opinions. Mine seems to be developing one.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_16', text: "I keep filling the odd tunnels back in, the ones that curved toward the center on their own. I fill them and pack them tight. The next morning the packing has gone loose again, like the ground breathed out while I slept.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_17', text: "The third time the packing came loose, I sat down in the dark and listened instead of digging. I sat a long while. Under the quiet there was a sound, if sound is the word. More like the memory of one. Low, slow, patient, coming up through the soles of my feet.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_18', text: "I asked Fennick to come down and put those big ears of his to the gallery floor. He listened maybe ten seconds, then stood up and said he'd rather listen from his own room, thank you. Fennick has never once in his life wanted to hear a thing less clearly.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_19', text: "Archimedes came down the shaft to look at my wrong-colored layer. He studied it the way he reads his books, slow and careful, and then he climbed back up without a word. That's twice now a friend has gone quiet on me.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_20', text: "Sloane stopped me in the hall after that, moving even slower than usual, which for her is saying something. She said, \"You found the color, then.\" Not asked. Said. I hadn't told a soul but Ember and the owl. I lay awake on that one a good while.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_21', text: "That's three friends gone quiet on me now, and all quiet in the same way. Nobody says don't dig. Nobody says dig. They just look at me like I'm partway through a story, and they've already read the ending.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_22', text: "I've been trying to remember why I dug that deep gallery so wide. I still can't. And every tunnel that curves on its own curves toward that gallery. I don't much like that they all agree.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_23', text: "The air in the gallery moves now. Just faintly, a slow drift toward the center of the floor, as if the room were breathing in through a crack I never cut. I checked every wall for the draft. There's no crack. The air just goes.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_24', text: "I paced the gallery again to settle my nerves. Forty strides across, the day I finished it. Forty-two now. Rooms don't grow, and I want that on record. Rooms don't grow. Mine is growing.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_25', text: "All my life the work has given me plain answers. Set a beam, the beam holds, and that question is closed. Down there I ask my questions just as carefully, and every answer only opens a bigger hole underneath it.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_26', text: "I've started leaving a lantern lit down there all night. Thirty years underground and I never once needed a light I wasn't carrying. I don't look at that habit too closely. I just keep buying oil.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_27', text: "I wrote to my brother about all this, then tore the letter up before I sent it. He's a digger too, and he'd do what diggers do: come and see for himself. I found I didn't want him anywhere near that gallery. That told me more than the letter did.", phase: 1, animalType: 'wombat' },
  { id: 'wb_1_28', text: "Every word you bring settles the new rooms a little firmer onto the old stone foundation. I can account for the weight of the new rooms. I'm less sure what that older stone was built to hold.", phase: 1, animalType: 'wombat' },
  // Phase 2 (21 + 1 question-web)
  { id: 'wb_2_1', text: "I hit something down at the warm layer, deeper than any sensible fellow digs. I put my spade to it. It wasn't stone and it wasn't root, so I stopped. I want that said plain. I stopped, and I'm not ashamed that I stopped.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_2', text: "I've got no honest word for what that thing was, and I won't hand you a dishonest one. A builder who guesses at his materials is digging his own grave. I've outlived every fellow I knew who guessed.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_3', text: "Whatever I hit down there, the face of it wouldn't shift. Warm under my hand, old under my tools. That's the whole of it, and neither fact tells me a thing more.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_4', text: "The spade rang when it touched. Not a clang, not the honest knock of stone. A note, low and round. It went on longer than a struck thing should, like the spade wasn't the part that rang. Like something was answering.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_5', text: "I stood in the dark a long while with my hand on the spade handle, and I got the strangest feeling I've ever had underground. That I was expected. Then I climbed out. I didn't run, and I'll take credit for the not running.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_6', text: "I filled my inspection shaft back in, packed it, braced it. It felt like good work at the time. Now I want to know what I've actually shut in down there.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_7', text: "My packing keeps loosening, and it loosens from the inside. I won't dig it open just to prove I can. First I'll find where that pressure comes from.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_8', text: "I've sealed springs, gas pockets, a badger's spite tunnel once. Whatever sits behind a seal pushes on all of it at once. Not this one. Something tries it gently, one stone at a time. Like patient hands. If hands is what they are.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_9', text: "Sloane found me packing that shaft a fourth time. She watched the whole hour, then said, kindly for her, that some doors are load-bearing. You can't take one of those out. And it's still a door, so you can't hold it shut forever.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_10', text: "I don't pack it again anymore. I check it, I write the drift down in my book, and I leave it be. A fellow can spend his strength holding one door shut, or keeping the rooms his friends sleep in sound. I've made my pick.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_11', text: "Ember comes down and asks after my shoulder, my supper, whether the timber's holding. She has never once mentioned the sealed shaft. That's how I know she knows.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_12', text: "Panko's started serving warm things cold. Chilled soup, bread left to cool. She says nobody in this house wants warming anymore, so she cooks for the appetite that's actually there. She notices more than she lets on.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_13', text: "Archimedes finally spoke to me about that deep layer, the one that's the wrong color. One sentence, then back to his books. He said that color has been described before. Described. Somebody wrote my dirt down. Some questions you keep in your pocket a while.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_14', text: "I laid a ring of flour round the seal. Old trick: a draft or a rat leaves tracks in it. By morning the stones inside had shifted and the flour was untouched. Whatever moved them never crossed my floor to do it.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_15', text: "Chill asked me for a drawing of the sealed shaft for his files, pencil ready. I told him no. First time I ever refused that fellow a piece of paper. I'm not ready to see this filed under a tidy heading, like the matter's settled. It isn't.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_16', text: "The warmth is coming up. I used to have to dig down for it. Now I feel it in my own burrow floor of a morning, faint, like something below rolled over in its sleep and settled a bit closer.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_17', text: "The warmth climbs about a floor every season, by my reckoning. I mark it on the shaft wall the way you'd mark a flood line. Only a flood crests and falls back again. This one has only ever crested.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_18', text: "I've laid foundations for barns and dens. Here I joined my new work onto an older stone base I didn't lay. It runs deeper than the house above it needs. That should have made me ask what it was for.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_19', text: "My new work fits that old stone base too well. I copied its joints straight off, without once asking what those joints were for. Thirty years in the trade, and I never asked.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_20', text: "My dad used to say the ground remembers every hand that works it. Lately I wonder if it runs backwards too. Maybe the ground knew my hands before I ever laid them on it. Maybe the work knew me first.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_21', text: "So I don't dig down anymore. I dig sideways, I dig useful, I dig honest. But at night, flat on my back in the burrow, I always know which way the thing I sealed is lying. I've never once lost the direction.", phase: 2, animalType: 'wombat' },
  { id: 'wb_2_w1', text: "The roots in Thyme's garden lean the same way my shafts do, and I never dug my shafts to lean. Ask her which way her flowers point up top. We might be looking at two ends of one line.", phase: 2, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  // Phase 3 (30)
  { id: 'wb_3_1', text: "I can tell the two jobs apart now. My braces hold the house up. The old stone underneath them was built to hold something shut. What it is shutting in is the next question.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_2', text: "I ran the load figures twice. The old base can carry far more than anything I've ever built on it. I sat on the stone a while after that. It's good work. It was built for somebody else's reasons, and I need to know whose.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_3', text: "A good plan tells you what weight it has to carry. This one never did. I just copied the measurements off the old stone. My hands did sound work from half the instructions.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_4', text: "I tried to work out when those old measurements got into my hands. I traced it back job by job, season by season, to the first morning I ever set a spade to this hill. They were already there. My very first cut followed a drawing I'd never seen.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_5', text: "Ember pointed at the ground and said, dig here. My hands said yes before my head had weighed it. I called that trust between friends. It was trust, and I'll stand by that. But something used that trust as a road, and got me digging where it wanted.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_6', text: "The warm layer isn't a layer. I understand that much now. It's the top of something. I dug down to the crown of it and called it a floor. There's no floor. There's just the thing itself, going down and down. Patient. Waiting for the sky to open.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_7', text: "Ember thinks whatever is coming comes from above. My measurements say the pressure down here pushes inward, from below. I need both reports before I can say what this house is being got ready for.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_8', text: "I thought I was holding a house up. But part of the old stonework pushes inward instead, toward the center of the house. Somebody chose that direction. I want to know who.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_9', text: "Ember says her fire leans upward now. I wrote that on my plan, marked as her report, not mine. Then I went up and asked Vesper what she could see.", phase: 3, animalType: 'wombat', requiresAnimals: ['tarsier'] },
  { id: 'wb_3_10', text: "My spade rang against that stone when I first struck it, like an answer. My braces and the old stone make a seat for whatever sits below, and the seat knew its builder. I shook hands with a thing I built without knowing.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_11', text: "Every word you offer, the old base takes it and settles a little firmer. I used to call that settling comfortable. Now I know what it is. The house is bracing itself to bear a load, the way I brace a beam before I take the prop away.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_12', text: "I've stopped sealing the deep shaft. What's the use? You don't hold water back with a plank. Now I spend my strength on the house above, keeping it sound. When the weight comes, the rooms my friends sleep in won't fold in on them.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_13', text: "My brother asked to visit. I told him the house was unsettled and left it there. I owe him a clearer account than that before I call it an invitation.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_14', text: "I've started going room to room up top, quietly, checking every beam I ever set. Ember's hearth, Panko's kitchen, the study with all that weight of paper. If the sky is going to open over my friends, they'll be standing under my best work when it does.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_15', text: "Thyme asked me whether the house would fall. I showed her my load figures, then asked what had put the question in her head. She had a measurement of her own to show me, and it wasn't in my figures.", phase: 3, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  { id: 'wb_3_16', text: "The warmth is in every floor now, faint, from my burrow up to the attic. Bamboo feels it at the top the same as I feel it at the bottom. Something is wrong the whole height of the house, and the two of us don't need many words to agree on it.", phase: 3, animalType: 'wombat', requiresAnimals: ['red_panda'] },
  { id: 'wb_3_17', text: "I dream I'm digging, and the spade goes soft into that warmth. It isn't a wall anymore. It's a back. A great patient back, breathing slow, waiting on a sky that hasn't opened yet. I don't wake up scared. That's the part that scares me.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_18', text: "I told Bamboo the dream. They're the only one who wouldn't make it worse or smaller. They listened with their eyes shut, then said, \"The back has been dreaming you longer.\" I came down the ladder no calmer. I suspect that was their honest intention.", phase: 3, animalType: 'wombat', requiresAnimals: ['red_panda'] },
  { id: 'wb_3_19', text: "Fennick sleeps in my burrow entrance some nights now, at the high end, ears turned to the sky instead of the ground. He says the sound he used to hear under everything has moved up. Sounds don't climb. This one has. Neither of us said the next part.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_20', text: "The deep gallery measures forty-four strides today. It was forty when I finished it. I keep the old numbers written beside the new one. A room that grows shouldn't get to erase the evidence that it's growing.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_21', text: "The roots out of Thyme's garden have grown clean through my galleries now. Every one of them aims at the sealed stone at the bottom. She's anxious, and I understand why. She's the only one of us honest enough to be scared out loud.", phase: 3, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  { id: 'wb_3_22', text: "Chill came down with his pencil at last, and this time I let him file the sealed shaft. He wrote a heading on the drawing. I didn't read it, on purpose. I work better when the hole hasn't got a name on it yet.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_23', text: "Axel sent word up through the spring, if you can believe that. My west seep ran warm a day, then cold, then warm again. I don't speak water. But I held my hand in it a long while, and the word he sent was soon.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_24', text: "Sloane has stopped saying soon. That's how I keep track of time now. When the slowest of us stops saying soon, it's because soon isn't the right word anymore.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_25', text: "I sharpened the spade this morning and caught myself doing it careful, the way you dress a tool for a job that matters. Then I wondered which job my hands thought the spade was for. They know things before I do. I've stopped pretending otherwise.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_26', text: "I put my hand flat on the sealed stone. I know exactly how it was fitted. I'm only now learning why.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_27', text: "There's a whole season of snapped spade handles in my store room. Cracked at the neck, from the months I dug too hard at nothing in particular. I've stopped snapping handles. Either I've calmed down or I've given up. Make of that what you like.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_28', text: "Your words come down here changed. Up top they're bright little things. By the time they reach the base they've got weight, real weight, and the stone takes them like mortar takes water. I'm telling you because nobody told me what my work fed.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_29', text: "I still take my supper off Panko's rope, and it still goes cold on the way down. I've come to be glad of that. Cold supper is right. The warmth down here is the lie, and I'll keep hold of every honest thing that's left.", phase: 3, animalType: 'wombat' },
  { id: 'wb_3_30', text: "I've laid out the old plan next to my revised one. Before I make another cut, you and I should decide what that cut needs to do.", phase: 3, animalType: 'wombat' },
  // Phase 4 (30)
  { id: 'wb_4_1', text: "I know what holds a weight up. I am still learning what the old work was built to hold in.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_2', text: "The foundations are old. The rooms you added are new. Do not let anybody leave your work out of the account.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_3', text: "I copied a joint because it was well made. A well made joint can still belong to a bad plan.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_4', text: "Hold the lamp here. There is a groove cut behind my brace. I missed it while I was checking the load.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_5', text: "A brace holds a thing up. A seal holds a thing shut. They look the same until you try the door.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_6', text: "I should have asked who drew the plan. I was too pleased that somebody liked my measurements.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_7', text: "I chalk my marks beside the old ones. Mine have dates on them, so you can tell whose work is whose.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_8', text: "Warm stone tells you there is heat in it. That is as far as that evidence goes.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_9', text: "The wall can argue with my chalk overnight. It cannot move my hand while I am watching.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_10', text: "Mind the beam. A mystery does not make a cracked skull any less inconvenient.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_11', text: "I will not brick up a gap just because somebody labeled it finished.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_12', text: "There was an old den here, and old footings, before the additions. I hauled the new timber in myself.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_13', text: "The load travels upward at that spot, not down. My gauge does not care that I call that impossible.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_14', text: "I left a wedge by the passage. Whether we use it depends on what we decide to keep open.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_15', text: "Thyme measured well. I should have said so before I asked her why she was worried.", phase: 4, animalType: 'wombat', requiresAnimals: ['rabbit'] },
  { id: 'wb_4_16', text: "You can love a house and still take a hammer to the part of it that is hurting somebody.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_17', text: "The plan draws the house as one solid outline. Buildings need joints to move. So do the ones living in them.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_18', text: "The shovel handle is worn to fit my paw. If it comes back smooth, I will roughen it again.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_19', text: "You do not have to admire the tunnels. Just tell me if something down here feels wrong.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_20', text: "I took the pretty facing off the wall. It was hiding where the old work joins mine.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_21', text: "Dirt on the ceremonial robe. Dirt on all my other clothes. Consistent standards.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_22', text: "I used to think deep meant secure. That depends on what you are standing over.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_23', text: "If I built it, I can tell you how. If I do not know why it is there, I will say so.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_24', text: "The old plan allows no alterations at all. That is a defect in the plan.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_25', text: "Keep the rubble until the repair holds. Do not lose your evidence halfway through a job.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_26', text: "Ember brought a cup down. I made her set it somewhere that was not on my chalk line.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_27', text: "The earth never promised me anything. I said otherwise on the days the work went well.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_28', text: "Nobody gets buried inside a promise I built. Not if I can help it.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_29', text: "Rest on the crate. I checked its load. It is rated for more than worrying.", phase: 4, animalType: 'wombat' },
  { id: 'wb_4_30', text: "Whatever we keep in this house, we ought to know where its edges are.", phase: 4, animalType: 'wombat' },
];

const RABBIT_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'rb_0_1', text: "The thyme grows in this bed, and I'm the other Thyme. You can see why I label everything.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_2', text: "Mind the gate. It bangs, and then I drop whatever I'm carrying.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_3', text: "I grew all those flowers from seed. I keep wanting to introduce you to them one at a time.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_4', text: "The path bends there because a flower came up where I'd planned to go straight. I let the flower win.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_5', text: "I make lists. Otherwise my thoughts go running through the flower beds unsupervised.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_6', text: "This is chamomile. It tastes better if you take the flowers out on time, instead of wandering off to do three other jobs. I'm still learning that part.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_7', text: "I once drowned a fern with sheer devotion. So now I measure the water out.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_8', text: "There are twelve ways out of this garden, if you count the gap behind the mint. I count it.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_9', text: "I like knowing where a path goes before I walk it. Then I can enjoy the walk.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_10', text: "I keep spare seeds packed in this tin. A little future that fits in a pocket.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_11', text: "That beetle looked terrifying until it fell off its leaf. We both had a difficult minute after that.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_12', text: "I watch the sky for rain. Also for hawks. Rain gets the warmer welcome.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_13', text: "You can help me tie this stem up. Gently, though. It doesn't know you're trying to help.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_14', text: "The watering can leaks. So I carry it over the seedlings and let them have the drips.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_15', text: "I grew every one of these myself. Yes, that was a boast. I'm practicing.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_16', text: "I keep a list of the jobs I've already finished. It's a lovely thing to sit down beside.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_17', text: "Sometimes I check the gate latch twice. The first check is about the latch. The second one is about me.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_18', text: "Please don't call the tiny flowers weeds until I've worked out what they are.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_19', text: "The north bed sprouted early this year. I wrote the date down instead of working out why.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_20', text: "Someone left a biscuit by the gate. I hope it was meant for me. The evidence is gone now.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_21', text: "Tea, while I work? Sit anywhere you like, as long as I can hear you.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_22', text: "I keep one empty pot for surprises. So far it has mostly held beetles.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_23', text: "The string is in the seed tin. The seeds are in the string box. I'm rewriting the labels today.", phase: 0, animalType: 'rabbit' },
  { id: 'rb_0_24', text: "Visit whenever you like. Call out from the gate so I can put the watering can down first.", phase: 0, animalType: 'rabbit' },
  // Phase 1 (28)
  { id: 'rb_1_1', text: "I have to tell you something, and please don't laugh. Last time I found a root growing the wrong way, so I turned it back. By morning it had turned itself around again. And it isn't the only one.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_2', text: "I lifted a pot to repot it. Every root inside had grown to one side, all curled the same way, toward the house. I told myself roots just follow water. I've been telling myself that for days now.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_3', text: "Since I found those curled roots in the pot, I've counted fourteen more plants leaning. The ivy, the runner beans, the parsley gone sideways in its window box. I didn't go looking for them. They're just there now, wherever I look.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_4', text: "I ran a little test, which isn't like me at all. Tests are Archimedes' job, not mine. I planted six beans in six pots and turned each pot to face a different way, like setting six clocks.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_5', text: "Every bean came up leaning the same way. Not toward the window. Not toward the water. Toward the house wall. I wrote it down with a very steady paw. Then I sat in the shed for a while.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_6', text: "I moved a whole bed to the far end of the patio, as far from the house as the stones go. By the third morning the new shoots were leaning back toward the house. I sat down on the path and had a small cry, which the parsley kindly ignored.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_7', text: "Ember found me there on the path. She said the leaning wasn't wrong, only honest. Plants lean toward what they need, she said. She meant it kindly. She always means everything kindly.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_8', text: "But think what that means. If plants lean toward what they need, then these roots need something inside the house. I don't truly know what's inside the house, and I'm the one who tends every growing thing here.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_9', text: "I asked Ember what the fire needs, since she's always reading it. She looked at me for a long moment and said, company. I've been turning that one word over for three days now.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_10', text: "Counting things usually settles me. I counted the pots this morning and for once it didn't help at all. Every pot was present. Every single one was leaning.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_11', text: "The warm patch of ground by the house wall has stretched into a strip now, pointing straight in at the middle of the house. The thyme along it comes up thick and happy, as if it likes a warmth I can't explain.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_12', text: "I laid a thermometer along the warm strip, feeling silly and scientific at once. The reading was perfectly ordinary. My paw on the same stone said warm. So either the thermometer is wrong or my paw is, and I'm not sure which one to trust.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_13', text: "Do you hear it, underneath the birdsong? A low sound, very patient, like the hum of a beehive but slower. The bees don't seem to mind it at all. Somehow that unsettles me more than if they did.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_14', text: "I asked Fennick about the low sound, because ears like his don't invent things. He held very still. Then he said, you hear that too. It wasn't a question. He sounded relieved. I felt worse.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_15', text: "Fennick told me the low sound was here before I ever thought to listen for it. That's the sentence I took to bed with me. It was here first.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_16', text: "Panko asked me for my fastest-growing herbs, the ones that fill a space quickest. I gave them gladly. Only later did I wonder which space she meant, and why the house would need filling.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_17', text: "I watched Panko hang the herb bundles in her kitchen, every stem pointing the same way. She called it tidiness. My bundles are tidy too, and they hang every which way. Hers all pointed in toward the middle of the house.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_18', text: "I've started keeping a second list, a private one. The first list is jobs for the garden. The second is only the small wrong things I keep noticing. I don't yet know what I'll do with the second one.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_19', text: "I finally took my little notebook of wrong things to Archimedes. He read the list the way he reads everything, twice. Then he said, would you leave this with me. Not, this is nothing. Would you leave this with me.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_20', text: "Archimedes was so gentle about my list that I almost missed something. He never once told me not to worry. He picks his words the way I pick seeds, carefully, and he didn't pick a single comforting one.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_21', text: "My list of wrong things lives in the study now. I kept a copy, of course. I'm anxious, not careless.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_22', text: "Axel says the pondweed in his tank has started leaning too. There's no sun in that room for it to lean toward. He said it dreamily, the way he says everything, as if leaning were a kind of dancing.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_23', text: "Chill patted my paw and told me every house settles, and the garden is only settling with it. It's a very reasonable explanation. I've noticed the explanations keep getting shorter, and the things they explain keep getting bigger.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_24', text: "I want so badly for all of this to be nothing. A quirk of the soil. A trick of the slope. I'm very good at deciding things are nothing. The trouble is, I'm running out of nothings.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_25', text: "Today's words sat heavy in my paw, the way seeds do just before they split. I planted them along the warm strip by the wall. Then I wrote that down. I don't remember choosing the strip. My paws just went there.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_26', text: "I've started to wonder which way round it is. Does my garden grow for the house? Or does the house grow my garden? That's a silly question. I've read it back four times now and it refuses to turn silly.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_27', text: "Sloane told me, in her long slow way, that noticing is a gift you get early. Early, she said, before the thing you'll need it for. I asked, before what thing. By then she'd fallen asleep. Or picked that moment to look like she had.", phase: 1, animalType: 'rabbit' },
  { id: 'rb_1_28', text: "Tell me the garden is only a garden. I won't fully believe you. But I'd dearly love to hear it said out loud by someone who isn't a plant, and isn't me.", phase: 1, animalType: 'rabbit' },
  // Phase 2 (21 + 1 question-web)
  { id: 'rb_2_1', text: "It isn't only the roots now. The stems lean, the flower heads lean, even the fence posts lean. All of it bows toward the middle of the house, like a congregation told exactly where to look.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_2', text: "I've stopped straightening the beds. When I propped a stalk upright it snapped, and the snapping felt worse than the leaning, so now I let them bow. I tell myself I'm being gentle. Honestly, I think I'm being obedient.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_3', text: "The blooms are opening in an order, and it isn't mine. The outer ring opens first, then the next ring in, closing on the middle like a slow eye. I planted every one of them on the same day.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_4', text: "The warm strip is the warmest thing in the garden now, warmer than the stones the sun has sat on all day. And the cold sits where the sun falls. I've written that in my private list and underlined it twice.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_5', text: "Here's the part I can't put down. I understand it now. Not the words for it, the shape of it. You know a storm is coming from the feel of the air, long before you look up and learn anything about the sky.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_6', text: "Archimedes says the pattern of my flower beds matches a pattern in one of his old books. He told me kindly, the way you'd mention a shared birthday. I haven't slept well since.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_7', text: "He showed me the page. I'd braced myself for something dreadful. It was a diagram, circles and lines, tidy as a planting chart. That was the dreadful part. My garden has been following instructions.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_8', text: "That low sound I used to hear under the birds is under everything now. I hear it in the watering can. I hear it in my own chest when I lie very still. It's patient, the way roots are patient.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_9', text: "A bee's dance is meant to point the others toward flowers. Mine circle once, turn to face the house, and stop. I've drawn the new figure three times. I keep the old dance beside it so I don't forget which was which.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_10', text: "I told Chill everything, the lean and the rings and the sound. He listened with his whole kind face and said, then we're exactly where we're meant to be. I wanted him to say something else. I wanted anyone to say something else.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_11', text: "I carried the tenderest seedlings indoors, away from the lean. By dawn they had turned toward the same center, from inside the house. There's no far end of the patio now. There's only nearer to that center, and farther from it.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_12', text: "The words you offer go down into the pit. I picture them settling into soil I can't see. Something is feeding on them down there, and coming up. I'm the gardener. I know what feeding looks like when it's working.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_13', text: "Panko came for the harvest with two baskets instead of one. She said the house eats better than it used to, and she meant it warmly. Everything here is meant warmly. That has stopped being a comfort.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_14', text: "Warren offered to dig my beds deeper, down where the soil stays warm. I asked how he knew it stays warm down there. He looked at me kindly, didn't answer, and dug.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_15', text: "I understand gardens. Ready ground, patient feeding, everything turned toward one point of light. That is exactly what I'm standing in. I just don't believe anymore that I'm the gardener.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_16', text: "Tonight's lesson was the trellis. The roses have tied themselves onto it in flat, even loops, tighter and neater than any knot my paws can manage. I stood in the dusk, being taught knotwork by a rose.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_17', text: "I dream in rows now. Long tended rows, all running toward a dark, warm center. In the dream I'm not frightened at all. Waking into my own fear is almost a relief. It proves I'm still myself.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_18', text: "I left one corner untended, a single wild square, just to watch something here choose its own direction. Within a week the wild square had a pattern in it too. Neater than anything I ever taught it.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_19', text: "The thyme by the step was my first planting here. It has crept the whole length of the warm line, right up to the wall of the house. It has never looked better. My name is growing all along that line, and I keep thinking of a fuse.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_20', text: "I'm still out here at dusk, tucking in the beds one by one, the way I always have. Someone kind should be minding the garden now. Especially now. Please don't call that brave. Call it habit, and let me keep it a while longer.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_21', text: "Stay another moment, would you. The garden calms when you're in it. So do I. And lately I've wondered, very quietly, whether even that has been arranged for me.", phase: 2, animalType: 'rabbit' },
  { id: 'rb_2_w1', text: "Bamboo isn't afraid of the garden leaning inward. Would you ask them why? And bring me the answer in their own words. I can decide what to do with it once I've heard it.", phase: 2, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  // Phase 3 (30)
  { id: 'rb_3_1', text: "I'm done pretending it's just soil chemistry. I've known something is coming for a good while now. I kept putting that knowledge down, the way you put down a heavy watering can. I can't put it down anymore.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_2', text: "Something is arriving. Not growing, arriving, the way weather arrives. The garden has been readying the ground for it this whole time. I helped. Tending is the only thing I've ever known how to do.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_3', text: "I keep two lists. The first one runs the garden, and I haven't updated it in a week. All my writing goes to the second list now, the list of wrong things. It has outgrown its notebook. I've started a third page, and I don't have a name for it yet.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_4', text: "The flowers open at night now. Moonflowers, white as paper, every face tipped straight up. I never planted them. A garden looks where it's told to look, and mine has stopped looking at the sun.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_5', text: "When I close my eyes, there's a shape behind them. Always the same shape. Patient, as if it's waiting for the light to be right. I open my eyes to make it stop. Then I see the garden bowing toward the very spot where the shape was standing.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_6', text: "Ember says her fire tells her the same thing my roots tell me. She calls us two windows onto one room. I used to find her frightening. Now I only find her early. She sees what I see, a little sooner.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_7', text: "Axel asked me to look into the rain barrel with him. I saw the sky, and then the sky opened, just for a breath, like a seed coat splitting. He steadied me and said, it's gentler in the water. I don't want to find out what it's like outside the water.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_8', text: "Fennick doesn't say all is well anymore. He sits on my garden wall at dusk with his ears up. When I bring him tea, he takes it without once looking away from the sky. We don't talk. We keep watch.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_9', text: "So I water the plants that lean toward the house. I hate that I do it, and I do it anyway. If I stopped, the beds would go untended right when they need a kind hand most.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_10', text: "I've started a tin of seeds. One of every plant I love, sealed dry, tucked at the back of the shed. I can't tell you what comes after. I only know a gardener saves seed before a hard season.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_11', text: "Warren has been digging deeper than my roots reach. Now the roots follow his tunnels down toward the pit. Even underground, everything wants to be nearer the center. There's no direction left that isn't toward it.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_12', text: "The words you bring are heavier than they've ever been. I plant each one, and the ground takes it so eagerly. I think, that's one more. I never finish the thought. I know exactly what it's one more toward.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_13', text: "The beds have finished their pattern. From the attic window you can see the whole thing, rings and lines, a big tidy sigil drawn in green. My own paws made every stroke of it. I signed something I couldn't read.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_14', text: "I asked Panko to stop cooking so much. She looked at me so tenderly and said, the guest is nearly here. You don't stop cooking when the guest is already on the road. I went home and couldn't eat a bite.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_15', text: "You're the one who keeps coming. Yours are the words the garden drinks. Someone who knows what this garden is should be standing beside you when you visit. So I stand there. It isn't quite bravery, but it's the nearest thing to it that grows in this soil.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_16', text: "I asked Bamboo why they weren't afraid. They gave me an answer about rain. I asked again, because I wasn't asking about the weather. I meant this house.", phase: 3, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_3_17', text: "Sloane said she'd been waiting longer than I've been alive. I told her that waiting a long time isn't the same as knowing. Her patience doesn't explain my measurements.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_18', text: "Archimedes reads to me in the evenings now, out on the patio. Not from his old books. He reads me seed catalogues and orchard almanacs, anything with a spring in it. He knows exactly what he's doing, and I love him for it.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_19', text: "The warm strip by the wall is hot now. The rest of the garden has gone cold, a still, waiting cold. That one hot line runs straight to the middle of the house. It looks like a fuse someone has already lit.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_20', text: "I dug up one of the words you brought last month, just to see. The soil where I'd planted it was dark and rich and warm, the finest soil I've ever touched. Nothing of the word was left. Whatever eats down there eats thoroughly, and my own two paws feed it.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_21', text: "On my dusk round I counted the beds, then the lit windows. Everybody was home. Everybody was leaning toward the middle of the house. I counted again. I wanted the second count to come out different.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_22', text: "I half-packed a bag and went to the gate. I checked the latch, then the path beyond it. The latch works. Where the path leads is the harder question.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_23', text: "Don't misunderstand me. Nobody here would stop me leaving. Every keeper in this house would help me carry the bag. Somehow that's the most frightening fact I own. Whatever is holding me here, it isn't them.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_24', text: "Chill found me trembling among the bean rows and just sat with me until I stopped. He never once said it would be all right. Under all that calm, he's too honest for that. He just stayed. That helped more than any answer would have.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_25', text: "I count the pots again at night. The old habit is back. Only now I catch myself counting toward something. It feels like the garden and I are keeping the same tally, and it's very nearly complete.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_26', text: "I recognize some of the words you bring lately. Dark ones, hollow ones. I plant them because that's the job, and the ground takes them like rain after a drought. I'm sorry. I'm so sorry, and I don't even know yet what I'm apologizing for.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_27', text: "I asked Ember how long we have. She read the fire for a long time, longer than she's ever needed. Then she said, before the seed you saved can sprout. I went home and looked at my seed tin for an hour.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_28', text: "The night sky over the middle of the house has a texture now. I'm telling you, the dark up there has a grain in it, like soil seen up close. I have excellent eyes for small differences. That's my whole trouble.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_29', text: "It's close. I can feel it in the soil, the way you feel a storm in your teeth before the first cloud shows. The birds have gone quiet about it. The bees haven't stopped their new dance once, not even at night.", phase: 3, animalType: 'rabbit' },
  { id: 'rb_3_30', text: "I want to be here because I like my garden. I'd like that to stay my reason, and I'd like to keep the right to change it.", phase: 3, animalType: 'rabbit' },
  // Phase 4 (30)
  { id: 'rb_4_1', text: "The gate latch sticks when the day is warm. I wrote that down. It is a worry worth keeping.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_2', text: "I keep facts on one side of the page now, guesses on the other. Fewer facts than I would like. All of them solid.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_3', text: "If you are tired of hearing me talk about checking, you can help me check.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_4', text: "My seed tin is packed and sitting by the gate. That does not mean I have decided anything.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_5', text: "Some flowers turn inward, toward the house. Some do not. I have marked both sorts.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_6', text: "I like my garden. I do not have to like everything that happens in it.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_7', text: "Bamboo keeps calling what is coming gentle. Ask a seed cracking out of its shell how gentle that feels.", phase: 4, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_4_8', text: "I have counted twelve ways out of this garden. That is not the same as knowing where they lead.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_9', text: "I did ask Bamboo why they are not afraid. They answered by talking about rain. I needed an answer about us.", phase: 4, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_4_10', text: "My paws shake. My measurements are still reliable.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_11', text: "I have left one bed unplanted. I might want different flowers later.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_12', text: "The chamomile is thriving. My own calming tea is coping better than I am.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_13', text: "Please do not call me brave yet. Sometimes brave is just a polite way of saying keep going.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_14', text: "I want Ember to visit. I want her to stop deciding which truths I can handle.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_15', text: "I weed the path behind the mint even when I am not going anywhere. A way out should be clear before you need it.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_16', text: "The sky frightens me. The beetle eating my seedlings infuriates me. Both at once.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_17', text: "I used to apologize before giving a warning. That wasted the time I needed for the warning.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_18', text: "Some seeds stay in the tin. I do not have to plant everything I have.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_19', text: "Someone promised I will never be afraid again. I would like to hear the rest of that promise.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_20', text: "Warren found a mistake in my diagram. Then I found one in his.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_21', text: "Could we just have tea, without anyone teaching me what tea means? Please?", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_22', text: "I have packed that tin twice now. The second packing has biscuits in it. An improvement.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_23', text: "I want another spring. I know it will not look like this one. I want it anyway.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_24', text: "I want reassurance. I also want the truth.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_25', text: "The house straightened my rows before I had decided where the path should bend.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_26', text: "I am fond of everybody here. Quite a lot of them annoy me as well.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_27', text: "The little flutter in my chest belongs to me. Please let me decide what to do with it.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_28', text: "I am learning to stand beside someone without agreeing with them. I am practicing with Bamboo.", phase: 4, animalType: 'rabbit', requiresAnimals: ['red_panda'] },
  { id: 'rb_4_29', text: "If I ask to be left alone for a while, it does not mean you failed to comfort me.", phase: 4, animalType: 'rabbit' },
  { id: 'rb_4_30', text: "Please leave the watering can where I put it. It is a small thing. I am asking anyway.", phase: 4, animalType: 'rabbit' },
];

// TARSIER (Vesper) - The unblinking night watcher whose vigil holds the way open
const TARSIER_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'tr_0_1', text: "Up here, on the rail. I keep forgetting that most people don't start by looking up.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_2', text: "I'm Vesper. I keep the night watch, and I eat breakfast at unreasonable hours.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_3', text: "I keep the lantern unlit so my eyes can have the whole valley.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_4', text: "My eyes can't move in my head, so I turn the whole head instead. I'll demonstrate if you like.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_5', text: "A moth is a lovely thing. A moth is also supper. I manage to hold both opinions at once.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_6', text: "I chalk the star positions onto the porch. Rain edits my work without asking.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_7', text: "When I look at you, you get all of my attention at once. Tell me if that's too much.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_8', text: "The porch is warmest just before dawn. It's an excellent place to finish a night.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_9', text: "I inherited this watch log from my family. Plenty of diligent entries, very little explanation.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_10', text: "That moth has circled me twice now. I admire persistence, but I won't admire it forever.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_11', text: "The best sleep comes after watching dawn turn up exactly when it should.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_12', text: "I have a favorite star. It has never noticed me. That suits us both.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_13', text: "My quietest note sits above most creatures' hearing. Fennick can hear it anyway.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_14', text: "I sing that note to check my breath. Fennick answers sometimes. We still haven't settled who's leading.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_15', text: "Most creatures can't hear our duet. That protects my reputation.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_16', text: "The chalk box needs a lid. I've solved a great many problems in the sky and keep putting off this one.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_17', text: "When your eyes never move, even the smallest movement out there stands out.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_18', text: "There's a darker patch of sky above the ridge. I've marked its edges rather than give it a name.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_19', text: "I turn my head when I'm thinking. People assume I've spotted something. Usually it's just a question I can't answer.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_20', text: "The beetle under the lantern is allowed to stay until dawn. We have an arrangement.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_21', text: "I like the stars that have no names. They don't expect me to catch up on the news.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_22', text: "Bring a blanket if you're staying. Warm opinions won't keep your feet warm.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_23', text: "I named one star Yours, after you. It's an inconvenient name when I try to explain which star I mean.", phase: 0, animalType: 'tarsier' },
  { id: 'tr_0_24', text: "Come up after dusk. I'll show you what changed in the sky while the house was busy downstairs.", phase: 0, animalType: 'tarsier' },
  // Phase 1 (28)
  { id: 'tr_1_1', text: "Something small and new, for your ears only. Lately the dark has a grain to it, like wood or water. All my life the night just sat over the valley, evenly, the way dark should. Now it lies in one direction. That direction is toward this house.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_2', text: "I checked the grain three ways, because a watcher checks. Moths drift along it when they stop flapping. Fallen feathers lie along it. My own fur settles along it once the wind drops. Everything loose in the night agrees on where the night is going.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_3', text: "I'm not troubled. Rivers flow one way and nobody calls them sinister. But I've watched this valley for years, bright one, and the night never used to flow. It pooled. Something downstream has opened. I'll find out what by watching hard, the only method I own.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_4', text: "The middle of the sky is being kept clear. I noticed it the way you notice a swept doorstep. My shy little stars have all shifted a hair outward from one patch of dark above the house. Stars don't shuffle. Something asked them to move, and they're polite.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_5', text: "I watched that cleared patch of sky all night to see what it was for. Nothing came. But it didn't feel like an empty nothing. It felt like a reserved nothing. Like a chair with a coat hung over the back of it, waiting for someone.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_6', text: "The Latch and the Spoon, my steady stars, have held their places. That comforts me more than it should. Yours, the star I named for you, has moved closer to the middle. I've decided not to draw conclusions. As you can hear, I'm not entirely succeeding.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_7', text: "Last night I sang my over-voice to the valley. The usual greetings, small polite things. Under my last note, something answered from the very floor of the world. One note. Lower than low. Not unfriendly. I've carried it all day like a warm stone.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_8', text: "Fennick knows that low note. He's heard it for weeks, from below the house. Mine came from above. We marked both directions on the chart. A second pair of ears has made the map more complicated, in a useful way.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_1_9', text: "You aren't Fennick, so I'll say the obvious part out loud. Above and below are answering each other. My little voice just sang in the space between. I wasn't the conversation. I was a bird landing on a wire. But the wire, bright one. The wire is humming.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_1_10', text: "The moths have changed their loose circle into a spiral. I drew both routes in the log. Then I caught one for supper.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_11', text: "I chalk the moths' spiral on the porch, and it goes deeper every night. When I stepped back I recognized the curve. It matches the stars around the cleared patch. I keep the porch drawing beside the sky chart now.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_12', text: "Archimedes asked which book I'd copied the spiral from. None. He knows I haven't opened his books. He wrote my answer down and thanked me twice.", phase: 1, animalType: 'tarsier', requiresAnimals: ['owl'] },
  { id: 'tr_1_13', text: "The dark patch seems nearer. It's in the same position above the ridge, but it feels closer. So I keep two columns now. Position is measured. Nearness is what I feel.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_14', text: "I spent one hour facing east, away from the patch. When I turned back, it hadn't changed. It doesn't seem to need my watching to stay there. That pleased me. I'll record the pleasure too.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_15', text: "The patch is easy to watch for too long. So I've started counting how often I look away. A long stare isn't proof of discipline. It might just be a stare.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_16', text: "Axel's tank shows a second sky after dark. There are different lights down there, under the reflected stars. I stayed until my neck ached. He held a weed aside so I could finish my sketch.", phase: 1, animalType: 'tarsier', requiresAnimals: ['axolotl'] },
  { id: 'tr_1_17', text: "Bamboo's incense smoke leans inward, toward the house. My night chart leans the same way. At dawn we compared directions on the top step. The house sits right between the two. We needed a larger sheet of paper.", phase: 1, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_1_18', text: "Ember brought tea up to the midnight watch. She asked how her fire looks from up here. Like a doorway, I told her. She said it looks that way from inside too. I added her viewpoint to my notes.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fox'] },
  { id: 'tr_1_19', text: "At the start of every watch I wait for the low note now. If it comes, I answer it. Last night I wrote down how long I waited. It was longer than my whole greeting used to take.", phase: 1, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_1_20', text: "The low note feels familiar. I'm trying hard not to promote that feeling into proof that it's safe. Familiar isn't the same as safe.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_21', text: "I told the moths about the low note, out loud, in my day voice. Talking to moths is how I hear myself think. They spiraled on, unbothered. In all my years, no moth has ever been surprised by anything. I used to find that funny. Now I find it instructive.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_22', text: "Warren reports warmth under the house. I report a change above it. He held my chart while I marked where his tunnels run. His paw left a little real soil on my chalk ridge.", phase: 1, animalType: 'tarsier', requiresAnimals: ['wombat'] },
  { id: 'tr_1_23', text: "The dew fell in rings around the house last night. I sketched them before sunrise. Thyme should see the drawing before somebody tells her it was only ordinary dew.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_24', text: "I keep two ledgers now. The old one holds moths, beetles and winds. Small true things deserve bookkeeping too. The thin new one holds the grain of the dark, the cleared sky, the spiral, the note. The thin one fills faster. I noticed. I want that on record.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_25', text: "Yours, the star I named for you, sits right at the edge of the cleared patch. I check it first every watch. Its position is still steady. I'd tell you if it changed.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_26', text: "Tonight I caught myself reading an expression into the dark patch, as if it had a face. I drew what I saw. Tomorrow I'll look at the drawing again before I choose a word for that face.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_27', text: "The hour before dawn is warm now. It used to be the coldest part of the watch. I marked the change for seven mornings running. On the eighth morning I stopped marking it and just said good night to it.", phase: 1, animalType: 'tarsier' },
  { id: 'tr_1_28', text: "The night isn't done becoming whatever it's becoming, and I won't rush it. I have the eyes, the rail, and the patience of a very old line of watchers. Sleep well in the daylight, my friend. I'll keep the ledgers. Come back and I'll read you the newest page.", phase: 1, animalType: 'tarsier' },
  // Phase 2 (21 + question-web)
  { id: 'tr_2_1', text: "I used to chalk only the stars, so most of the sky never reached my log. Now I draw the dark spaces between them too. The pages fill much faster.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_2', text: "A moth died on the rail last week, halfway through its spiral. It folded out of the air with no fuss at all. I sat with it until dawn. Not grieving, exactly. Attending. Where does a moth's circling go when the moth stops? The spiral didn't look finished.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_3', text: "The lantern glowed on its own. No oil, no wick, no match; I checked all three. I watched it until dawn and woke nobody. Next time I want a witness before the light goes.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_4', text: "I keep asking when the lantern started glowing, and I can't answer. Maybe the light changed. Maybe my eyes did. I never measured it before, and that's an irritating gap in a very long watch.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_5', text: "I can follow the glow of your words below the ground. Then I lose sight of it. I used to write vanished in my log. I've corrected that to beyond my view.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_6', text: "The cleared patch above the ridge is wider now. Its edge stays sharp, and there's nothing inside it for my eyes to hold. When I need somewhere firm to look, I count the stars around it.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_7', text: "I have never felt alone on watch, not in the old country and not on this rail. I called that company, and I liked it. Now the lantern lights itself, and I wonder how large the company has been.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_8', text: "Sloane says nobody has ever been the only one awake. She was just waiting for the rest of us, she says. I wrote her sentence in my margin, where I keep other watchers' accounts.", phase: 2, animalType: 'tarsier', requiresAnimals: ['sloth'] },
  { id: 'tr_2_9', text: "The low note under the world answers before I finish singing now. So I changed the last note of my song. It answered the old one anyway.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_10', text: "Each dusk picks up where the last night stopped. The same watch, with one more change in it. I can show you every change. Something is learning from this watch, and I can't tell you what.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_11', text: "Thyme asked me whether the night is safe. I said it has never harmed me. That isn't the same as safe, not for her. We stayed at the gate until she had finished asking.", phase: 2, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_2_12', text: "I left the rail and walked out to the ridge. The watched feeling came with me. I got back before dawn with damp hands and one new entry: for once, I was the one being observed.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_13', text: "I started a new column in my log, headed: what the night wants. My paw kept writing nearer. So I have rewritten the heading to say what I think it wants. A small change, and an important one.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_14', text: "Bamboo calls the warmth in the house attention. If they're right, it reaches above the roof and below the floor. I've put their word beside my temperature marks. It explains more than my marks can prove.", phase: 2, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_2_15', text: "I asked out loud what the watch is for. The same low note answered me. I hear that note most nights, and I almost let something familiar count as an answer.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_16', text: "When Thyme asks about the watch, I've been giving her the smaller truths. I thought that was care. Now I keep the whole log where she can ask to read it.", phase: 2, animalType: 'tarsier', requiresAnimals: ['rabbit', 'fox'] },
  { id: 'tr_2_17', text: "Every moth on the porch settled on the lantern glass and stayed still until dawn. The next night the lantern shone brighter. I marked both nights. I've called it the unlit lantern for years. That name is wrong now.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_18', text: "I sleep less in the day now, and it isn't worry. My grandmother's stories taught me what worry feels like, and this isn't it. It's the sleep before a journey: light, one ear out of the blanket. My body is keeping itself ready, and it won't tell me what for.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_19', text: "My eyes don't move, so every look is a full turn of my head. The old book from the study calls that an instrument's design. I know what my eyes can do. I'm slower to accept who they were made for.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_20', text: "Fennick's bearing and mine point at the same place now. We nearly folded our notes together. I asked him to keep his own. Two accounts are the only way to check that we really agree.", phase: 2, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_2_21', text: "Every light went out for the length of one breath. The stars, the lantern, the pit. I saw something while they were gone. I can't describe it yet. One breath is the only measurement I can give you.", phase: 2, animalType: 'tarsier' },
  { id: 'tr_2_w1', text: "When I finish my greeting, Fennick keeps listening. Ask him what he hears in that gap. I have timed the silence, but his account belongs beside mine.", phase: 2, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  // Phase 3 (30)
  { id: 'tr_3_1', text: "I inherited this night watch and assumed the word for it was guard. The old diagrams folded into the log say otherwise. They say my watching helps the thing above the ridge arrive. I can't tell how much.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_2', text: "If I want to, I can read the old watch log as preparation for this. But plenty of entries worry about other things entirely. I'm keeping those pages where I can find them.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_3', text: "My grandmothers kept this same watch. The old book counts that as their agreement, passed down to me along with my eyes. I can inherit a log. I still have to decide where I stand myself.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_4', text: "There's a shape holding still in the cleared patch of sky. It isn't coming down, as far as I can measure. My eyes ache when I turn away. I turn anyway. Rest belongs in the schedule too.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_5', text: "The edge of the cleared patch looks sharper the longer I stare at it. So I look away and check my chalk marks instead. Maybe my looking is what holds the patch open. I want a second watcher before I write that down.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_6', text: "At moonset Fennick stood beside me. His ears and my eyes were pointing along the same line. I drew that line across both our maps. He asked me to leave our older bearings showing.", phase: 3, animalType: 'tarsier', requiresAnimals: ['fennec_fox'] },
  { id: 'tr_3_7', text: "The low note under my song sounded like thanks for keeping the way open. That's my translation, not its words. It made me grip the rail. I liked hearing it that much. That goes in the log beside the translation.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_8', text: "Bamboo watches from under the roof gap. I keep the porch. At dawn we ask each other whether the way held. We used to ask how the other slept. I miss the old question.", phase: 3, animalType: 'tarsier', requiresAnimals: ['red_panda'] },
  { id: 'tr_3_9', text: "Thyme asked whether it's coming for us. I said it's coming to us. She told me that swapping one small word wasn't an answer, and she's right. I turned away from the sky and tried again.", phase: 3, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_3_10', text: "The moths trace their spiral above the lantern every night. Archimedes calls them messengers now, which complicates supper. I've stopped eating them. For now I just watch where they go.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_11', text: "Three entries in the same hour. Your letters went down, the amber gathered below, the cleared sky changed above. So the pit isn't where your words stop. It's somewhere they pass through.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_12', text: "Archimedes read me a passage from his old book. It says fixed eyes hold a way open. That describes me exactly. I asked him to leave the book here. I want to read the part just before it.", phase: 3, animalType: 'tarsier', requiresAnimals: ['owl'] },
  { id: 'tr_3_13', text: "I left the rail for one night to test what the book said. There was pressure behind both closed eyes until dawn. It eased when I came back. I wrote relief in the log. Relief isn't proof.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_14', text: "Sloane says my grandmothers were watching for this arrival before I was born. I have their logs. Tonight I'm reading them for their own words about why they stayed.", phase: 3, animalType: 'tarsier', requiresAnimals: ['sloth'] },
  { id: 'tr_3_15', text: "I want to see it arrive. That's a big want, and it isn't all of me. I also want a morning afterwards, with somebody here to talk to.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_16', text: "Every night I straighten the watch marks and sing to the stars at the edge. I don't remember learning either habit. So I've left one mark crooked, to see whether my hand goes back for it.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_17', text: "Ember asked what I knew. I showed her my chalk marks and my unanswered questions. Her fire, Bamboo's smoke, Sloane's long wait. Three signs pointing one way, and still not proof.", phase: 3, animalType: 'tarsier', requiresAnimals: ['fox', 'red_panda', 'sloth'] },
  { id: 'tr_3_18', text: "I sleep an hour at a time now, under the eave. Last night I dreamed I was a doorframe. I woke rested, wrote it down, then gave myself an extra hour off watch. Frames need maintenance.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_19', text: "The lantern glows on its own now, and my ink is easier to read by it than by daylight. So I keep the log beside it. The porch door is standing open. I opened it myself, apparently, and never wrote down when.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_20', text: "Come up to the rail before the sky changes again. I'll show you your own star first, the one I named Yours. From up here you can watch the whole valley at once. I can promise you a place beside me and an honest report.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_21', text: "Dust, petals and Thyme's seed paper all lifted toward the sky, then settled back down. Not one mark on the paper was smudged. I watched the whole journey and never saw what held them up.", phase: 3, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_3_22', text: "The big table downstairs and the foundation under this house are nearly finished. My watch runs until the way opens. I'm proud to be trusted with it. I've also asked who takes the watch after that.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_23', text: "Chill kept the middle watch with me and asked no questions. At dawn he wrote two words in his ledger and showed me the page: vigil, ongoing. I asked him to add the hours we spent together.", phase: 3, animalType: 'tarsier', requiresAnimals: ['capybara'] },
  { id: 'tr_3_24', text: "My high call, then the low note answering it. Back and forth, like a counting song. Every arrangement you finish below shortens the gap between the two notes. I write the gaps down. I don't fill them with singing.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_25', text: "I want to see what happens. That's my own wish. It doesn't prove my whole life was made for one sight.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_26', text: "Even the Latch has leaned toward the cleared patch. I named that star for holding steady. Tonight I kept the name and moved its mark on my chart. The old mark stays where it was.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_27', text: "I nearly merged my two logs into one. Then the moths and the dew rings would vanish into the story of the shape above the ridge. So I've kept the two books apart.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_28', text: "Thyme sent up a moonflower with a note that reads, \"So something soft is with you.\" The flower opens toward the cleared sky. I've put the pot beside the lantern and tucked her note under the log.", phase: 3, animalType: 'tarsier', requiresAnimals: ['rabbit'] },
  { id: 'tr_3_29', text: "I don't know what my watch is for once this is over. There may be something else I want to look at.", phase: 3, animalType: 'tarsier' },
  { id: 'tr_3_30', text: "When the sky changes, I'd like to hear someone breathing beside me. You don't have to look up to keep me company.", phase: 3, animalType: 'tarsier' },
  // Phase 4 (30)
  { id: 'tr_4_1', text: "The dark patch above the ridge has an edge now. I marked that edge on my chart in chalk. Chalk is less excitable than memory.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_2', text: "I inherited this night watch from my family. An inheritance is not an explanation. They never knew what they were watching for.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_3', text: "There is a seam in the sky above the ridge, a thin join. I cannot see where it leads.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_4', text: "That seam pulls my attention back to it, over and over. I write down whatever interrupts the pull.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_5', text: "Your face interrupts the pull of the sky. So does a moth. I am grateful to both.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_6', text: "I want to see what happens, with my own eyes. That is a wish of mine, not advice for you.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_7', text: "I put my hand over the lantern so I can see the valley. Brightness is not always a help.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_8', text: "My eyes do not move, so a look means turning my whole head. Sometimes I turn it toward a friend.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_9', text: "I sing one high note each night to check my breath. I changed the note, and Fennick noticed.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_10', text: "A friend and I tried singing a duet. Following another voice is harder for me than watching.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_11', text: "I crossed the word safe out of my log. What I meant was unharmed so far.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_12', text: "Seeing farther does not stop me from being wrong. It only gives my mistakes more ground to cover.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_13', text: "Moths for supper again. A moth can be an omen and still be supper.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_14', text: "A star moved against the chimney last night. So I checked the chimney too, in case the house had shifted. Warren appreciated that.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_15', text: "I would like a tomorrow with something still left to learn.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_16', text: "I keep a second notebook for what I notice while looking away from the sky. It is the better book.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_17', text: "Sometimes I tuck my head under my arm. Eyes this big need somewhere dark to rest.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_18', text: "Please do not ask me to watch you sleep. Even I need hours off.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_19', text: "The sky gives me a great deal of detail. Almost none of it tells me what to do.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_20', text: "Thyme spotted the gate. I was watching the far ridge and missed it. Farther is not always more useful.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_21', text: "A chalk mark can be wrong. It cannot change without my noticing.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_22', text: "Nobody in the old log wrote down how to refuse. So I may write those instructions myself.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_23', text: "I want to be seen. I also want to choose when I am alone.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_24', text: "A beetle hides under my lantern. I pretend not to notice him until dawn.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_25', text: "Watching is what I do. I do not want it to be everything I am.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_26', text: "Ask me what I saw first. Ask what I think it meant after that.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_27', text: "My two notebooks keep sliding into one pile. I have put a stone between them.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_28', text: "I have not given the thing above the ridge a name. A name would make it too easy to think I recognize it.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_29', text: "Your words come down past the ridge as light. I admired them long before I understood that.", phase: 4, animalType: 'tarsier' },
  { id: 'tr_4_30', text: "When the sky changes, I would like someone beside me, telling me what I missed down here.", phase: 4, animalType: 'tarsier' },
];

// AYE-AYE (Tock) - The gentle diviner of hollow places who keeps the unrung bell
const AYE_AYE_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'ay_0_1', text: "Tok, tok. That's hello. I try not to use it on a door with somebody asleep behind it.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_2', text: "I'm Tock, an aye-aye. The long finger gets introduced last, after the rest of me. That order works better for everyone.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_3', text: "The bell up here has never rung. Not once. I'm her new keeper, so keeping that silence going is my job now.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_4', text: "Tap a board and you hear whether it's hollow. That's a good way to start getting to know a room.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_5', text: "Some hollows contain grubs. I eat grubs. The work has refreshments.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_6', text: "I came here from the night woods. The road passed through several unfriendly villages.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_7', text: "Vesper sent word that there was a room up here. I came to find out whether she was right.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_8', text: "The tower sounds a little different at each landing on the way up. I do enjoy a staircase with a good voice.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_9', text: "I sleep in the daytime. If you visit at noon you'll get a fine view of my feet and not much conversation.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_10', text: "Yes, the finger is meant to be that long. I answer that before anyone asks. It saves us both the pause.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_11', text: "When I polish the bell, I work around one little scratch. She may wish to keep it.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_12', text: "Her bronze holds the warmth of my hand longer than wood does. I've tested both.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_13', text: "I keep a gnawing block here. Teeth are tools, and mine never stop growing. The upkeep is inconvenient.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_14', text: "Back where I came from, people called me an omen. All I wanted was somewhere to put down my bag.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_15', text: "The bell rope hangs within reach of my hand. Reaching isn't a reason to pull.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_16', text: "I found a loose peg today by sound alone. Quite smug about it, thank you.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_17', text: "The bell was here long before I was her keeper. So I knock on the older beams and ask what they remember of her.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_18', text: "That beam over there answers a little late when I knock on it. I haven't decided whether the wood or my hearing needs checking.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_19', text: "I like where I am. It took a long road to be able to say that.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_20', text: "Would you like a tour? I'll knock on the beams as we go. We stop when they all start sounding the same to you.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_21', text: "My cup lives on a shelf that's perfectly level. When Warren saw that, he looked personally pleased.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_22', text: "A grub is eating the sacred beam, the one the bell hangs from. Nobody appears to have briefed the grub.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_23', text: "Tok, tok. Two taps, that's all it takes. I don't require a complicated password from a friend.", phase: 0, animalType: 'aye_aye' },
  { id: 'ay_0_24', text: "Come after dusk, when I'm awake. I'd like to hear another set of steps on the stairs besides mine.", phase: 0, animalType: 'aye_aye' },
  // Phase 1 (28)
  { id: 'ay_1_1', text: "Tok, tok. I knocked twice on the beam and it gave me three back. Two like mine, then a softer one from below. I tried again. Same thing. Wood usually gives back what you give it. This wood adds a knock of its own.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_2', text: "I tried the pipe, the cistern and a loose board. Every time, the extra knock came back slower and softer than mine. An echo copies you. This one pauses first, like someone deciding where to put their finger.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_3', text: "I try different knocks and write down each reply. Usually it's my own count plus one. Now and then it's something else. I've circled those. The exceptions are the interesting part.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_4', text: "I gave one tok. A long pause. Then two knocks came back together. One, a wait, then two: that's a greeting where I come from. I sat under the stairs a while. I hadn't meant to open a conversation.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_5', text: "I asked Warren whether his tunnels ever give back a late, soft echo. He only wanted to know which timber I meant. He didn't laugh. I'd rehearsed what to say if he laughed.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_1_6', text: "Whatever answers in the beam waits its turn. It isn't a rat scrabbling about, and it isn't the timber groaning. My mother said you can share a wall with anything that knocks politely. It knocks politely. I'm still deciding about the sharing.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_7', text: "I chalk a circle on every hollow I find: stair, gap, shaft. The circles have started joining up, so I ran a string between them. Whoever left these hollows knew where the next one would be.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_8', text: "My string runs gap to shaft, then shaft to a long tunnel. Joined up, it's all one passage. It runs below the deepest floor of the house. Tok. The map has gone further than my finger can reach.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_9', text: "Warren laid my chalk map over his survey of the foundation. His seams are where the old stone meets the newer building. My hollow line ran along one of those seams a while, then wandered off it. We marked the spot where it left.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_1_10', text: "The bell hummed at dawn. Nobody struck her. Both my hands were on the ladder, six feet away. I said good morning to her before I thought to measure anything. The log has to admit that.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_11', text: "Fennick heard the bell's dawn hum from his camp and came straight up. Standing under the bronze, he said it sounded like an answer. An answer to what? He couldn't hear that part. We stayed until the sun cleared the ridge.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['fennec_fox'] },
  { id: 'ay_1_12', text: "I keep two logs now. One for the beam at night, one for the bell at dawn. There's precious little sleep between them. I used to sound wood for grubs, and a grub fits in my mouth. These new questions don't.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_13', text: "Tonight the wall knocked before my finger landed. One tok, just ahead of me. I held my hand still. I tried another board and got nothing. I've marked the first board and left it alone for tonight.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_14', text: "My finger has started pulling toward the hollow passage. A small pull, down through the boards. I notice it most while I'm carrying a cup. Hot tea is a fine reason to say no to a finger.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_15', text: "I tied a stocking over my eyes, turned round three times, and let the finger choose. Eleven tries. It found the hollow every time. I took the stocking off. I've known this hand all my life. It surprised me.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_16', text: "Tok, tok-tok, tok. My childhood call. I tapped it on the beam and it came back exactly, lower and from far below. I expected the usual extra beat. There was none. It sounded as though somebody down there knew my name.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_17', text: "I made up a new call, seven beats with a stutter. I kept it in my head three days and never tapped it. On the fourth day the beam played it first. I felt flattered. Then I counted the beats again.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_18', text: "Something beneath the boards repeats my knocks. The answer comes back clearer than it did when I first arrived. I don't know whether that means it's getting more polite, or simply getting nearer.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_19', text: "Ember's fire has been tapping out my own call. The sparks and the settling coals go tok, tok-tok, tok. She'd heard it all week and wondered whose it was. I hadn't taken anything down there that taps. Only my hand.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['fox'] },
  { id: 'ay_1_20', text: "I tapped on Axel's tank glass to say hello. My note held in the water, and another note answered from the deep end. Axel said the water was learning my song. We listened together, my finger resting on the glass between the notes.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['axolotl'] },
  { id: 'ay_1_21', text: "Sloane waited on my landing to ask about the answering knocks. She says the beam is teaching me, one knock at a time. I tried her word out on it. Tok. Whatever knocked back didn't teach me anything.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['sloth'] },
  { id: 'ay_1_22', text: "Every word you make lands somewhere below the timbers now, with a soft knock at the end of it. Each night it lands a little nearer the floorboards under my feet. I've moved my listening mark to match.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_23', text: "I followed the hollow behind the stairs three floors down. It got warmer at each turn. There was no dust in the passage at all. I ran a finger along the floor of it. Swept clean, right into the corners.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_24', text: "At the third floor down, the wood ticked like a kettle warming up. I stopped there. Whatever is below knows my knock by now. I'd rather hear an invitation before I put my whole hand through.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_25', text: "The bell's dawn note runs the length of the roof beam now, right over my bed. For a minute the hum settles on me before I'm properly awake. My mother used to hum while she foraged. That minute puts me back with her, before I reach for the log.", phase: 1, animalType: 'aye_aye' },
  { id: 'ay_1_26', text: "I've been gnawing more lately. Warren brings me offcuts. One came from the deep timbers under the house, and it tasted just like my old beams up here. I keep a shaving of each on the sill now. Same sweetness, darker grain.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_1_27', text: "At bedtime I tap through the beam to Vesper: still awake? She taps back: always. Now a third knock answers below us. The first night, we both went quiet. Tonight I waited for all three before settling to sleep.", phase: 1, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_1_28', text: "Last page of my log: the wood remembers my knocks, the bell hums at dawn, every answer has one added beat. Whatever is down there hasn't started a conversation yet. When it does, I'll bring you the exact rhythm.", phase: 1, animalType: 'aye_aye' },
  // Phase 2 (21 + question-web)
  { id: 'ay_2_1', text: "I finished my chalk map of the hollows, and it's shaped like a bell. It swells and narrows from the rafters down to the deepest floor. I hung it beside the bronze. My small bell sits at the top of a much larger hollow.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_2_2', text: "A solid lump of bronze can't ring. Leave a hollow inside it and it can speak. This house is hollow in the same shape. That doesn't tell me what it will say, only which part of my map to listen to.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_3', text: "Your words travel down the hollow passage behind the stairs now. Up here they sound like a patter. Far below they turn into one clear note. I followed one down with my ear along the boards. The house gives your word a ring.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_4', text: "On my chalk map, the pit sits right at the mouth of the bell. The ground there is thin, stretched like a drumskin. Warren's joins under it hold. I asked him about the old stone beneath them before I added the pit to my drawing.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['wombat', 'pangolin'] },
  { id: 'ay_2_5', text: "So that's the survey. The whole house is one enormous bell with a thin floor at its mouth. Something down past that floor has learned my knocks. I came to look after one small bronze bell, and the job keeps growing. I'd like a smaller job for an evening.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_6', text: "Last night the bell frame knocked out my own pattern before I'd even raised my finger. I wrote that down first. Then I lay still and let myself decide whether to answer.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['rabbit'] },
  { id: 'ay_2_7', text: "I answer once now, where I used to knock back five times. Every knock I return seems to open the sound a little wider. Any craftsman stops between strokes to see what his tool has done. I'm doing that.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_8', text: "One night I didn't answer the knock from below. No louder knock followed. The next night, the same quiet rhythm. I'm grateful it can wait. I'm still taking my time with my answer.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_9', text: "The knocks come in sentences now. Some end with a little rise, the way a question does. They run five and seven beats, about the length of words. They use my call sign and your words, so I write the beats down with spaces between them.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_10', text: "Some of your words land below with an ordinary tok. Others warm the wood along the hollow line on my map. The darker words you send do it most often. I test that warmth with the back of my hand. My finger is too interested to be trusted with it.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_11', text: "Back in the villages, they called my pointing finger an omen. By winter, every shutter closed when I came near. Now the finger points on its own, without my asking. I needed to say that to someone who wouldn't reach for a latch.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_12', text: "At dusk my finger uncurls and points toward the pit, down and east. The first night I held it shut. The second night I let it point. Same direction both times. I'm learning to hold the rest of my hand steady while it does.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_13', text: "I keep more wood by my bed now, short billets for gnawing. My teeth need the work, and the new questions need talking through. At three in the morning the wood is company enough. Come after dusk for the questions.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_14', text: "Fennick came up to listen with me. He says the knocking and the breathing he hears below feel the same size. Chill brought tea while we listened. One cup on the sill was still steaming after ours had gone cold. Nobody had taken a sip.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['fennec_fox', 'capybara'] },
  { id: 'ay_2_15', text: "All my life I've been the shape people shut their doors on. This listener below learned my knock and answered it. I like being recognized. You should know that about the person giving you reports from inside the wall.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_16', text: "I put my ear against the bell's side. There's something held in the bronze. Not a sound yet, the shape of one. I can't get it out by listening harder. So I polish the spot where my ear keeps leaving a mark.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_17', text: "I drew the bell's outline on one chalk sheet and the house's hollow on another. I laid one over the other and tapped. Tok. They match curve for curve: the same hollow at two sizes. I'd like to hear the note before I call the match a purpose.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_18', text: "I've thought about ringing the bell early. Some ordinary noon, one pull, and the question is settled. Then I hold the rope and wait instead. Her first note will be heard through the whole house. That deserves better than my impatience.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_19', text: "Dusk climbs the tower. The floor goes gold, the bronze goes rose, the window goes dark. I polish through that hour. The house below goes quiet while the hollow starts answering. Between those two, my cloth keeps up its ordinary little scrape.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_20', text: "Thyme sent up flowers and a question: is it kind? I wrote back that it knocks gently, and that gentle knocking isn't enough to know by. She sent back one word: staying. I think she meant herself.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['rabbit', 'pangolin'] },
  { id: 'ay_2_21', text: "That's the end of this log. A bell-shaped house, a hollow that answers, and now the first knock comes from below instead of from me. I answer once and no more. The next page is blank and ready. I won't fill it before the next sound.", phase: 2, animalType: 'aye_aye' },
  { id: 'ay_2_w1', text: "Ask Warren why his knock comes back late. When I knock up here, the answer comes back sharp. Two pieces of wood, one house, and they answer at different speeds. Tok. There's a missing beat somewhere between our two maps.", phase: 2, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  // Phase 3 (30)
  { id: 'ay_3_1', text: "The beam has started knocking in groups, and the groups sort into letters. I copied the rhythm down before I tried to read it. I don't want to hear only what I'm hoping it says.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_2', text: "The knocked letters travelled up the tower and into the bell's bronze. My hand shook while I wrote them down. She sits heavier in her frame now. I checked the bolts holding her before I let myself wonder what the word was.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_3', text: "The thing below the boards knocks old dark words up to me now. I knock back small ones: the weather, the frost, the smell of bread coming up the shaft. Small talk through a wall. I used to wish for a neighbor who would try that.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['pangolin'] },
  { id: 'ay_3_4', text: "Last night it tapped out the rhythm of your words, then one extra beat, like a question. I knocked back the word friend. A friend who keeps coming back. Warmth came up through the floor until morning. I hope friend meant what I meant by it.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_5', text: "Every exchange makes the wall between us feel thinner. One night it may not need my knock to speak at all. Even then, I'll still know a solid beam from a rotten one. I'm keeping my tools for that work.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_6', text: "I always thought the bell's first ring would be a warning to the house. The note forming in her now sounds like a welcome. I want to ring it. I'm keeping that want well away from the rope.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_7', text: "The bell's bronze is holding a word now. The stone under the pit answers tighter than it used to. My finger keeps finding its way to both. An hour is coming. I can braid a rope that will hold, without pretending I know the day.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_8', text: "I rebraided the worn end of the bell rope. Three strands of hemp, and a little of my own combed fur worked in. A rope should fit the hand that chooses to pull it.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_3_9', text: "Twelve practice pulls at dusk, on a sandbag hung where the bell hangs, so she stays quiet. The rope holds without slipping. My shoulders ache. Practice makes my hand ready. It doesn't decide when I use it.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_10', text: "You keep climbing my stairs after hearing my reports. I'd like to take that as agreement. But I haven't asked you. Stay through dusk if you want. There's room here to tell me I'm wrong.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_11', text: "My finger points in my sleep now, down and east, toward the pit. At sunset it lifts the other way, up through the bell toward the sky. Two addresses. I drew them both, then tied a reminder round my wrist to rest my hand.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_12', text: "The villagers back home called this finger a mark of misfortune. Now it has found something strange. That doesn't prove they were right to treat me the way they did.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_13', text: "The knocking paused. Then a pressure settled on my chest, small and exact as a fingertip, and stayed for three heartbeats. Thirty years I've spent pointing at things. Last night something pointed at me. I laughed before I could choose another sound.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_14', text: "That touch found the hollow the villages left in me, the ones that shut their doors on an aye-aye. It didn't flinch and it didn't pity me. I wanted to call that a welcome. Afterward I put my hand on my chest and listened for what was still mine.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_15', text: "A knock should leave room for no. That's the whole point of knocking. I want to know whether the answer here can actually be no.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_16', text: "Down in the burrow the spade went quiet, and two palms went flat on the stone. The fire burns steady. The kitchen hums in one key. Separate sounds, starting to tune together. I tap an ordinary loose board between them. It still has its own note.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['wombat', 'fox', 'pangolin'] },
  { id: 'ay_3_17', text: "Fennick pointed out the water, the fire and the pulse in the beams. One sound, he said, big enough to want a bell. We both looked at the rope. His ears and my paw can find the sound. Neither can answer for the hand that pulls.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['fennec_fox'] },
  { id: 'ay_3_18', text: "Ember's fire keeps showing her this tower. She sees a rope hanging, and a paw on it the flames never show clearly. I told her about my own pale fur braided into that rope. She knew the color at once, and the tea was still hot when she said so.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['fox'] },
  { id: 'ay_3_19', text: "Panko sent up a portion for me, and a second bowl, wrapped. I asked her who the second one was for before I set anything down beside the beam.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['pangolin'] },
  { id: 'ay_3_20', text: "Warren's knocks come back late. He thinks that's because something is receiving them, not stopping them. He tapped my floor to show me. On his way out he checked the rope and called it well braided. I put that in the log too.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['wombat'] },
  { id: 'ay_3_21', text: "Thyme stayed while my finger lifted toward the sky on its own. She told me she'd expected this finger to be a weapon. I showed her the knuckle, and the ordinary way it bends. Then we put her flowers on the sill together.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['rabbit'] },
  { id: 'ay_3_22', text: "I hummed against the bronze, and down in his tank Axel saw rings spread across the water. When he put his paw on the glass, the bell warmed under my ear. We tried it twice more, the same both times. Two ends of one instrument, both listening.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['axolotl'] },
  { id: 'ay_3_23', text: "Vesper watches the sky above while I listen to the wood below. Our two reports seem to be describing the same thing. We're comparing them carefully before we say they point to one door.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['tarsier'] },
  { id: 'ay_3_24', text: "Sloane remembers this tower from before my family's time. She called it reserved, the way you'd say it of a table. I carried tea down to her on the third landing, then came back up and looked at my fresh rope against the old beam.", phase: 3, animalType: 'aye_aye', requiresAnimals: ['sloth'] },
  { id: 'ay_3_25', text: "Try this, if you like. Hold a word for one breath before you offer it. It lands below with a rounder note. Just a small listening experiment. You needn't do anything differently on my account.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_26', text: "I could draw a straight line through my whole life and have it end at this bell. But I can also remember roads that went somewhere else. The bell doesn't get all of me.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_27', text: "The hollow passage behind the stairs is warm now, floor after floor, and nothing has closed behind me yet. I climbed inside and rested there awhile. It felt like being carried. After an hour I took myself back up to the tower.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_28', text: "I've set a cup of water by the rope. If the moment needs my voice, I'd rather not find out right then that my throat has other plans.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_29', text: "I've left the log open at a blank page. The next page has to hold what actually happens, not what I've already decided to remember.", phase: 3, animalType: 'aye_aye' },
  { id: 'ay_3_30', text: "There may be an hour coming that asks for the bell. I'll decide what to do when my hand reaches the rope, not before. I'd like you nearby for it, if you choose to be.", phase: 3, animalType: 'aye_aye' },
  // Phase 4 (30)
  { id: 'ay_4_1', text: "I have loosened the rope. The bell is ready now. Ready is different from pulled.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_2', text: "The bell was silent for sixty years before I came up here. I have only just begun keeping her company. We are both entitled to nerves.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_3', text: "Something answered our work. That does not mean we understood what we were asking for.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_4', text: "I stopped calling the inside of the bell empty. Now the knock sounds different. Empty was only my word.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_5', text: "My finger finds grubs. Lately it finds stranger things. Neither one justified the villages closing their doors on me.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_6', text: "I wanted this house to take in something feared on sight. I was feared on sight once. I am not an impartial host.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_7', text: "Being called an omen taught me sympathy for a guest nobody knows. It taught me nothing about whether the guest is kind.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_8', text: "I have been the thing in the walls myself. All I wanted then was for somebody to knock back.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_9', text: "I asked the bell what she wanted. She said nothing. Silence is not yes. I know that.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_10', text: "The rope is wearing thin under my thumb. I keep working it because my hands want a job, and the answer is not ready yet.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_11', text: "The villages were wrong to drive me out. If this finger turns out to be a strange gift, that will not make them right.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_12', text: "Tapping finds hollows. It does not decide who should live in them.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_13', text: "Vesper left room for me here. A small kindness, and a deliberate one.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_14', text: "The others have started using my gnawing block. New marks every day, none of them mine. I had not realized how much I would like that.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_15', text: "Have you had enough after one beam? We can stop there. A tour does not have to be a vow.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_16', text: "The robe keeps catching on the bell frame. Ceremonial cloth was not cut for a keeper who still works.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_17', text: "When I knock, there is a gap before the echo. I count it. It is long enough to stand in. I have not decided whether I want to.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_18', text: "If I ever touch the rope, I need to be able to say honestly that I decided to.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_19', text: "Stand wherever you like. We can arrange the bell and the rope around you, not you around them.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_20', text: "A room is only a hollow with someone's things in it. So a hollow can be made into a home. I find that encouraging.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_21', text: "I set the loose peg back into the beam myself this week. Small work, and mine.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_22', text: "Nobody here shut a door on me. I am grateful for that. Gratitude is not permission to shut a door on somebody else.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_23', text: "I want the arrival to come. I can still ask it to wait for our answer first.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_24', text: "A cloth laid over the bronze quiets her. Even an old voice can be asked to stay low.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_25', text: "I keep a cup of water by the rope. If I have to speak once the bell has rung, I would rather not do it with a dry throat.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_26', text: "My finger trembles when it has nothing to do. Give it work and it behaves. I have the same problem.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_27', text: "I do not want respectability if the price is forgetting who welcomed me before I had any.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_28', text: "There is a grub eating the sacred beam. I have questions for whoever chose that beam.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_29', text: "Here, on the rope. This is where my hand would go. Showing you does not decide anything for us.", phase: 4, animalType: 'aye_aye' },
  { id: 'ay_4_30', text: "The bell's voice is saved for the moment we actually meet. Not before.", phase: 4, animalType: 'aye_aye' },
];

// KAKAPO (Moss) - The patient caller whose lifelong booming is finally answered
const KAKAPO_DIALOGUES: Dialogue[] = [
  // Phase 0 (24)
  { id: 'kk_0_1', text: "Moss. Mind the seedlings there. They're tiny, and they've claimed that whole bed like they own it.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_2', text: "I walked here. It was all hills, and I now have strong opinions about walking.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_3', text: "A kakapo can't fly. So I get my excellent views by standing on perfectly ordinary rocks.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_4', text: "That honey smell is me, I'm afraid. The bees consider it false advertising.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_5', text: "I keep a dish of sugar water by the gate. It's a peace offering to the bees who come for honey and find only me.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_6', text: "The roof needed soil, so I carried soil up. Several trips, and one shortcut I regret.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_7', text: "That shallow bowl in the dirt is where I do my calling. It took longer to dig than it looks.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_8', text: "I've been calling for ninety years. Then I listen. The listening is the hard part.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_9', text: "I chose this garden for the sky above it. I'm still a bit surprised I got it.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_10', text: "The good bucket is my seat. The other bucket is just a bucket. Labels might help.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_11', text: "I garden slowly. So far the plants haven't complained.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_12', text: "Carrying a packet of seeds a long way is an ambitious thing to do. You're betting on ground you haven't seen yet.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_13', text: "This rimu seedling is a native tree. It needs decades to grow great, but watering it today fits my schedule.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_14', text: "The lining in my nest needs changing. There's no egg in it, but an empty nest still collects dust.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_15', text: "I keep one small weed by the path. I didn't plant it, it arrived on its own, so it can stay.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_16', text: "When a hawk passes over I freeze solid. A beetle once took that as an offer of free transport.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_17', text: "The bees have found the sugar water by the gate. Negotiations are improving.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_18', text: "There's one particular voice I miss. Being around other voices helps, but it doesn't replace that one.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_19', text: "My calling bowl sounds different after rain. I tip the water out before I practice.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_20', text: "A garden on a roof needs checking from underneath as well as on top. I look under every pot.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_21', text: "Something has bitten the edge of the new leaf. I have a suspect, and I have very poor fencing.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_22', text: "A flightless bird living on a roof. I like it up here enough to forgive the stairs.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_23', text: "Something low answered my call last night. Probably just the house settling. I wrote down when, all the same.", phase: 0, animalType: 'kakapo' },
  { id: 'kk_0_24', text: "Stay while I water, if you like. I'll introduce you to the small ones first.", phase: 0, animalType: 'kakapo' },
  // Phase 1 (28)
  { id: 'kk_1_1', text: "Something low answered from the bowl again today. I was only humming while I worked. I stopped humming and listened. I haven't used my great call up here yet, not once.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_2', text: "I sat up last night and listened properly. The answer is one note, very low, lower than mine. It comes from no direction at all. Every other sound comes from somewhere. I walked the garden with my head tipped, and it was just as loud at every corner.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_3', text: "For ninety years I called and nobody answered. I made my peace with that, I truly did. So you'd think an answer would be pure joy. It is joy. But joy that arrives this late looks like a stranger at the door. You stand there a while before you let it in.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_4', text: "The seedlings come up leaning now. All of them, in every bed, tilt toward the center of the garden, like children all looking at the same window. I straightened a row of beans on principle. By morning they'd leaned back. Politely, but back.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_5', text: "The beds lean toward my calling bowl. I moved a pot across the garden to check. Same lean, still toward the bowl. I can't tell yet whether they're facing my voice or the low answer underneath it.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_6', text: "Fennick can hear the low answer even on nights when I haven't called at all. I said maybe it wants company. He asked whether he could have one quiet hour. I'd never thought to want one. I'm thinking about it now.", phase: 1, animalType: 'kakapo', requiresAnimals: ['fennec_fox'] },
  { id: 'kk_1_7', text: "Archimedes found birds like me in an old book, mossbirds, calling across the green. The book used the word summons. We both wanted to know who was supposed to answer a summons. The page gave no name.", phase: 1, animalType: 'kakapo', requiresAnimals: ['owl'] },
  { id: 'kk_1_8', text: "My rimu seed has sprouted early. A rimu is a slow tree, it takes decades to grow up. But the seed doesn't have to wait forty years to begin. It only has to begin.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_9', text: "I ran a test. One row on the warm line where your words come up, one row in plain ground, same day. The warm row is ankle high. The plain row is asleep. So I'm a scientist now. My laboratory smells of honey and my findings unsettle me pleasantly.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_10', text: "The buds are fattening out of season. I keep a mast diary now, like my grandmother's generation did: tally marks on a bit of slate. Each mark counts toward a mast year, when every tree fruits at once. The slate is filling faster than any story I was told.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_11', text: "Warren asked whether roots alone could explain the warmth under my beds. I said roots can't explain that much warmth. We compared a handful of soil from his place and one from mine. He took both back down to his lamp to look properly.", phase: 1, animalType: 'kakapo', requiresAnimals: ['wombat'] },
  { id: 'kk_1_12', text: "The true call takes one great breath. I'm saving that breath. Humming while I work is a different noise altogether.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_13', text: "Tock does his knocking rounds along the beams under my beds every night. The seedlings twitch along with each knock. When his knocks reach the bowl, they lean further. I tied a thread to one stem so I can measure it tomorrow.", phase: 1, animalType: 'kakapo', requiresAnimals: ['aye_aye'] },
  { id: 'kk_1_14', text: "A plant I never planted has come up in the south bed. Broad dark leaves, veins like handwriting. I know every green thing that grows. Not this one. The law of gardening says a stranger in the bed is a weed. Pull it. It smells of rain on warm stone. I haven't.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_15', text: "Three more of the strange plants now, in an even curve. Spaced as carefully as I'd have spaced them myself. I watched them with my chin on the bed frame. Somebody has left me hardly any thinning to do.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_16', text: "Thyme's seed twists came with a note: is your garden doing it too. No greeting, which from Thyme means the words cost her. I wrote back, yes, and added, it doesn't feel unkind. Because it doesn't. That's the strangest part, and I wanted her to have it.", phase: 1, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_1_17', text: "The moths have multiplied. Hundreds every night now, rising off the beds at moonrise all at once. They circle the bowl three times, always three, then go down toward the house. I don't keep moths. Somebody keeps moths. I'm starting to wonder who keeps me.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_18', text: "A kakapo freezes when a hawk goes over. I froze today with one foot up. Empty blue sky, no hawk I could see. Twenty minutes before I put the foot down. The watering can waited beside me the whole time. Then I finished the row.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_19', text: "Bamboo says their stalks in the attic lean inward. My beds lean toward the bowl. They came up to compare the two leans. We crouched by one stem until the tea went cold. The looking took much longer than the explaining.", phase: 1, animalType: 'kakapo', requiresAnimals: ['red_panda'] },
  { id: 'kk_1_20', text: "The honey smell is stronger, and it isn't mine. I know my own smell. Some evenings the whole garden smells of honey, sweet and old. The bees have stopped following me. Why would they? The air itself is the flower now. I sit in it and feel, oddly, expected.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_21', text: "I lay in the middle bed last night and the stars looked like a lid on a pot. I usually call them a garden. Same stars, a much less comfortable name. I got up and moved to the fern corner.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_22', text: "My grandmother's rule: when the mast slate fills early, dig the calling bowl deeper. The slate filled today, three weeks early. I stood over the bowl with my digging foot ready. Then I put it down. An old instruction can wait one evening.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_23', text: "Your words come up as warmth in the lines under my beds. Half this early growth follows right behind them. I'm glad of the fruit, friend. But I should ask what that warmth means before I thank you for all of it.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_24', text: "I dug the bowl deeper by moonlight. Both feet, the old way. The beds stayed quiet while I worked. I left the loose soil in a pile beside the bowl. I may want to put some of it back.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_25', text: "I filled my chest for the call. The answer began before I'd let a breath out. I sat in silence through its whole note. Then I tried one small boom of my own, the smallest call I have.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_26', text: "Axel sent word describing my garden: beds in moonlight, the bowl, even the veins on the new plants. He has never climbed up here. He saw it in his tank water. I sent down a leaf to compare. It was exactly the shape the water had shown him.", phase: 1, animalType: 'kakapo', requiresAnimals: ['axolotl', 'pangolin'] },
  { id: 'kk_1_27', text: "Evenings, I talk to the stranger plants. Who sprouted, who's being eaten by what. They don't answer, plants never do. But their leaves go still while I talk. There are kinds of still, friend. I know them all from the inside. This is the listening kind.", phase: 1, animalType: 'kakapo' },
  { id: 'kk_1_28', text: "Full moon tonight, the bowl freshly deepened, and a hum under the beds. I sleep well up here. Visit again when you can, and bring me the news from downstairs. This garden has been taking most of my attention.", phase: 1, animalType: 'kakapo' },
  // Phase 2 (21 + question-web)
  { id: 'kk_2_1', text: "The green went strange this week. Not sick, just strange. Every leaf darkened one shade overnight, all together, like a room when someone tall walks past the lamp. The sun is where I left it. Whatever dimmed the leaves stood between us and the light.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_2', text: "Ninety years of calling, and nothing ever answered. I used to picture those calls fading out over the valley. Now I wonder whether something kept them. I'd like to hear one of my young calls again. I might not know my own voice.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_3', text: "That low answer sounds familiar. I'd love to believe it heard every one of my ninety years of calls. But wanting that isn't evidence, so I'm not claiming it yet.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_4', text: "The words down in the house and the warmth in these beds are connected somehow. I came up here to keep a garden. Now I'm asking what else the garden is being used for.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_5', text: "The new flowers open at the hour I always used to call. I sit among them and feel recognized, and I wanted that for ninety years. Then I went and watered the plants that open at other hours too.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_6', text: "Fruit is setting all across the valley at once, in the wrong month. In the old forest we called that a mast year, when every tree fruits together. I've brought out my largest baskets. They may still be too small.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_7', text: "A mast year used to be a happy thing to me. All that fruit arriving at once, and I never asked what set it off. Up here, above a warm house, I've started digging under my garden beds instead.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_8', text: "I asked Sloane about the mast year. She took most of a day to answer. She says whatever ripens gets eaten by whoever chose the season. I went back to my beds and counted who was being fed here.", phase: 2, animalType: 'kakapo', requiresAnimals: ['sloth'] },
  { id: 'kk_2_9', text: "The moths go down into the house. The warmth comes up. The fruit swells for something that isn't here yet. I planted every one of these beds. I'd like to meet whatever my garden has started feeding.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_10', text: "These beds are lovelier than anything I grew alone. From up here, being used feels a great deal like being needed. I haven't sorted out the difference yet. I can think about it while I water. The plants need water either way.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_11', text: "I dropped a pebble into the calling bowl. The knock went round and round, far longer than a small dish of dirt should allow. As it faded, the low answer came up underneath it. I hadn't meant the pebble as a call.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_12', text: "The fern corner has gone cold and the calling bowl stays warm, so I sleep in the bowl now. I wake up with green dreams and soil in my feathers. I set a stone at the rim, in case the bowl is getting deeper.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_13', text: "In my green dreams I always walk downhill, through beds I never planted. The new plants stand tall as trees there, veins lit like windows. Something walks with me, not beside me but under the path, keeping perfect pace. I'm never afraid. I keep trying to be.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_14', text: "Thyme sent a note up the seed post: does the garden love us, or keep us? I wrote back that a good shepherd does both, and that neither of us is a sheep. Then I sat with my pen, remembering why a shepherd keeps sheep at all.", phase: 2, animalType: 'kakapo', requiresAnimals: ['rabbit'] },
  { id: 'kk_2_15', text: "Something heard me. That's the part I know for certain. I'm trying not to pack everything I ever hoped for inside that one fact.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_16', text: "Ripe fruit and no takers. Birds land, look at it, and leave. The moths go straight past. Usually I'm defending a basket from half the valley. Tonight I held out a fruit in my own foot. Nothing came.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_17', text: "I hid a ripe fruit in a tin under the north bed. This morning the tin was open on the path, the fruit sitting on top, facing the bowl. Not a bruise on it. I wish that last detail were more comforting.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_18', text: "I've stopped calling the new plants strangers. I water them and they grow in my beds, so I call them mine. That still doesn't tell me who brought them up here.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_19', text: "Vesper says the stars are sitting lower. I say the warmth is rising closer to my plants' roots. We trade notes at the gate post. We've both had to write the same strange note in the margin, and neither of us can explain it.", phase: 2, animalType: 'kakapo', requiresAnimals: ['tarsier'] },
  { id: 'kk_2_20', text: "The ground carries that low note now without any help from my voice. It hasn't taken the place of my call. I still decide when to spend the breath I've been saving.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_21', text: "The mast fruit is heavy this year, and the bowl stays warm. Come sit while I sort the baskets. I've always known when fruit is nearly ready. This season I'd be glad to be a little wrong.", phase: 2, animalType: 'kakapo' },
  { id: 'kk_2_w1', text: "I sent Panko a basket of mast fruit. The extra plate she sets each night came back up with a fern on it that I never picked. Ask her who that place is for. A grower likes knowing who has eaten.", phase: 2, animalType: 'kakapo', requiresAnimals: ['pangolin'] },
  // Phase 3 (30)
  { id: 'kk_3_1', text: "Every tree in the valley fruited on the same day. My body wanted to go straight to the calling bowl. That's an old habit, and it came back strong. I went to check the seedlings first.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_2', text: "Here's my working theory. Your words, down below in the house, change what grows up here, and something answers back through the roots. I don't know yet why it answers me.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_3', text: "Archimedes calls all this an arrangement. I'd call it a mast year, when every tree fruits at once. But this plenty reaches past the trees. So I keep one empty basket beside the full ones. Plenty has to go somewhere.", phase: 3, animalType: 'kakapo', requiresAnimals: ['owl', 'fox'] },
  { id: 'kk_3_4', text: "I dug the bowl deeper and tried a soft hum. The answer came back with another note folded inside mine. Humming isn't the great call, though. I'm still saving that larger breath.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_5', text: "I'm glad you come up to the garden. If you missed part of the growing, ask and I'll tell you about it. We don't have to pretend you saw every leaf.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_6', text: "A shadow crossed the beds and I froze solid. It was only a hawk. I'd nearly turned an ordinary fright into evidence about this house.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_7', text: "The fruit comes off the branch and falls slowly. Heavy as an egg, but drifting down like a leaf. I set a basket under one and waited. For once I didn't have to hurry the catch.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_8', text: "I carried every fallen fruit to the bowl. By midnight they made a complete ring. By morning they were gone, and the soil was warm where they had sat. I brought the empty baskets up and counted them twice.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_9', text: "Tock knocked on the gate post, and the bowl answered before he'd finished. He listened with his head tipped, then sounded the wood again. I kept one foot on the post. The note came up into it from below.", phase: 3, animalType: 'kakapo', requiresAnimals: ['aye_aye'] },
  { id: 'kk_3_10', text: "The moths circled the bowl, then rose instead of going down toward the house. I wrote the change down. I don't know what they were carrying, if anything.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_11', text: "Ember called my bowl a slow green fire. I showed her the warm patch where the fruit had gone, and we sat with our feet on the soil. My garden and her grate were overdue a conversation.", phase: 3, animalType: 'kakapo', requiresAnimals: ['fox'] },
  { id: 'kk_3_12', text: "Bamboo and I take tea at the roof gap, ladder on one side, bean poles on the other. They say a visitor is coming, somewhere above us. I asked them to tell me if it bends my bean poles.", phase: 3, animalType: 'kakapo', requiresAnimals: ['red_panda'] },
  { id: 'kk_3_13', text: "Thyme showed me her seed tin. I asked for a few, then left the choosing to her. A garden shouldn't begin by taking someone's whole future.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_14', text: "Fennick asked whether that low chord is calling or answering. After ninety years of calling, I should be the one who can tell. I had to admit I couldn't.", phase: 3, animalType: 'kakapo', requiresAnimals: ['fennec_fox'] },
  { id: 'kk_3_15', text: "The plants are taller than me now. In one night, every one of them turned toward the bowl. I found myself facing it too. So I went to weed the east bed, where the work makes me look the other way.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_16', text: "Your words warmed the roots and helped bring on all this fruit. I tended what came up. Between us we helped something happen before either of us knew what it was. A grower has to answer for that too.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_17', text: "There's an old welcome song we used to sing near a nest. I've been humming it while I work. You're welcome to walk beside me without joining in.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_18', text: "Warren's foundations hold up what's already here. My roots feed whatever comes next. We sat on the edge of a bed comparing the work, and he asked what we'd braced the house for. I was hoping he knew.", phase: 3, animalType: 'kakapo', requiresAnimals: ['wombat'] },
  { id: 'kk_3_19', text: "I want to meet whatever is answering me. I can be afraid of it at the same time. Wanting a guest has never made the guest easy to live with.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_20', text: "The empty bowl sang on its own. No pebble dropped in, no call from me. The beds leaned the whole time the note lasted. I kept my chest quiet and listened to the end. My own answer can wait.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_21', text: "Vesper brought her sky log down to the gate post and I brought my planting book. The same warm nights in both, the same pauses. We kept both books. Her small marks tell me things my roots can't.", phase: 3, animalType: 'kakapo', requiresAnimals: ['tarsier'] },
  { id: 'kk_3_22', text: "I caught myself planning to welcome it on behalf of the whole house. Then I tried to remember when anyone had asked me to speak for them.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_23', text: "One branch still has fruit on it. I keep waiting for it to tell me when to call. Then I remember that a tree keeps its own season, not mine.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_24', text: "There's no egg in the nest. I look after it anyway. Keeping it lined isn't proof that anything has promised me a chick.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_25', text: "The last fruit is working loose. There's a small tick at the stem every night. Come up if you can. I'd like company when it falls, and another pair of feet to carry the basket.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_26', text: "The last fruit came down at moonrise. Then the bowl pulled air past my feathers, one long breath in. Nothing came back out. I waited with my feet in the soil. The empty basket stayed beside me.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_27', text: "Sloane climbed up to see the bowl. She asked what I was hoping to hear. I asked what she had been waiting for. We talked far longer than either of us planned.", phase: 3, animalType: 'kakapo', requiresAnimals: ['sloth'] },
  { id: 'kk_3_28', text: "A length of green cloth came up with the supplies. I laid it beside my ordinary work apron. I still can't think what occasion would call for it.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_29', text: "The ground said a phrase of my grandmother's back to me. I wanted to step down into the bowl. I stayed at the edge instead and listened to how it said her words.", phase: 3, animalType: 'kakapo' },
  { id: 'kk_3_30', text: "I've practiced going quiet after a call. Being answered takes listening, and that's the part I can't rehearse on my own.", phase: 3, animalType: 'kakapo' },
  // Phase 4 (30)
  { id: 'kk_4_1', text: "I have called for ninety years. Wait that long, and any noise at all can start to sound like an answer.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_2', text: "I swept out the calling bowl this morning. Old customs need looking after.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_3', text: "I walked here on my own feet. Nobody carried me toward a destiny. There were hills. I complained about every one.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_4', text: "When I hum at my work, something answers from under the garden beds. Humming is not the true call. I am saving my breath for that.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_5', text: "The rimu tree takes decades to bear fruit. Its seedlings can start much sooner. I can water one today.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_6', text: "I have waited for trees to grow. Not one of them ever promised to understand me.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_7', text: "Being answered proves one thing: I was heard. I am trying not to hang every other wish I have on that one fact.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_8', text: "I feel the warmth below the roots. Vesper watches for the arrival above the roof. Between us, both ends are covered.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_9', text: "My nest has room in it. There is no way to say that without sounding like an advertisement.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_10', text: "I still put out sugar water for the bees I disappoint. They come for honey, and the honey smell is only me. It always was.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_11', text: "A shoot has come up beside the bowl. I did not plant it and I cannot name it. It can stay while we find out what it is.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_12', text: "You made room for a garden up here on the roof. After that I brought the soil up myself, load by load.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_13', text: "All that walking was not a rehearsal for anything. It was just walking. There are excellent things at ground level.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_14', text: "Thyme keeps a few seeds back. That way some part of her garden is not yet promised to what is coming. Good.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_15', text: "I would like others to hear my call. I am also afraid that they will.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_16', text: "After the call I want two things. Water, and someone who will not ask for an encore.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_17', text: "The bowl stayed empty for years. It was a sad place, and I will be honest: I brought most of that sadness to it myself.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_18', text: "Do not promise me the wait was worth it. Let me hear the answer first.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_19', text: "Your words changed how the garden grew. I enjoyed the growth before I asked what all that growing was feeding.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_20', text: "The same flower has opened again, exactly the same as before. If I planted its seeds, what would they do differently?", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_21', text: "I kept a weed by the path. It arrived here without a plan. So did I. We have that in common.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_22', text: "Some nights I wanted any reply at all. Other nights I wanted one particular voice, the one I lost. Those are different wants.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_23', text: "A long life gives you patience. It also gives you plenty to be impatient about.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_24', text: "A nest does not promise that anything will fill it. I can look after it anyway.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_25', text: "I turned the weed's pot around this morning, so it gets the light from a different side.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_26', text: "The good bucket is my seat. The other bucket is trying to be a seat too, and doing it badly.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_27', text: "Next year I would like to sing a different song. Even if it takes me all winter to learn it.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_28', text: "I have been practicing the stop after the call. Going quiet and listening is work too.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_29', text: "My grandmother used to say: stop telling every seed what the garden is for. Let it surprise you.", phase: 4, animalType: 'kakapo' },
  { id: 'kk_4_30', text: "When the moment comes, I will stand in the bowl and use the voice I brought here.", phase: 4, animalType: 'kakapo' },
];

const ALL_DIALOGUES: Dialogue[] = [
  ...RED_PANDA_DIALOGUES,
  ...AXOLOTL_DIALOGUES,
  ...PANGOLIN_DIALOGUES,
  ...SLOTH_DIALOGUES,
  ...FENNEC_FOX_DIALOGUES,
  ...FOX_DIALOGUES,
  ...OWL_DIALOGUES,
  ...CAPYBARA_DIALOGUES,
  ...WOMBAT_DIALOGUES,
  ...RABBIT_DIALOGUES,
  ...TARSIER_DIALOGUES,
  ...AYE_AYE_DIALOGUES,
  ...KAKAPO_DIALOGUES,
];

/**
 * Get all dialogues for an animal up to a certain phase
 */
export function getDialoguesForAnimal(
  animalType: AnimalType,
  maxPhase: DialoguePhase
): Dialogue[] {
  return ALL_DIALOGUES.filter(
    d => d.animalType === animalType && d.phase <= maxPhase
  );
}

/**
 * Resolve a dialogue index to the first line at or after it that doesn't
 * reference a still-locked animal. Indices at or beyond the end of the pool
 * pass through unchanged (Phase 5 cycles rely on out-of-range indices).
 */
export function resolveDialogueIndex(
  animalType: AnimalType,
  index: number,
  maxPhase: DialoguePhase,
  unlockedTypes: Set<AnimalType>
): number {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  let i = Math.max(0, index);
  while (
    i < dialogues.length &&
    dialogues[i].requiresAnimals?.some(t => !unlockedTypes.has(t))
  ) {
    i++;
  }
  return i;
}

/**
 * Index of the first dialogue belonging to `phase` for an animal — i.e. how
 * many of its lines belong to earlier phases. Used to fast-forward animals
 * unlocked late so they don't replay bright-days small talk under a dark sky.
 */
export function getPhaseStartIndex(
  animalType: AnimalType,
  phase: DialoguePhase
): number {
  return ALL_DIALOGUES.filter(
    d => d.animalType === animalType && d.phase < phase
  ).length;
}

/**
 * Get the next unread dialogue for an animal
 */
export function getNextDialogue(
  animalType: AnimalType,
  currentIndex: number,
  maxPhase: DialoguePhase
): Dialogue | null {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  if (currentIndex >= dialogues.length - 1) {
    return null;
  }
  return dialogues[currentIndex + 1];
}

/**
 * Get current dialogue for an animal
 */
export function getCurrentDialogue(
  animalType: AnimalType,
  currentIndex: number,
  maxPhase: DialoguePhase
): Dialogue | null {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  if (dialogues.length === 0) {
    return null;
  }
  // Clamp index to valid range - show last dialogue if index exceeds available
  if (currentIndex < 0) {
    return dialogues[0];
  }
  if (currentIndex >= dialogues.length) {
    return dialogues[dialogues.length - 1];
  }
  return dialogues[currentIndex];
}

/**
 * Check if animal has more dialogues available
 */
export function hasMoreDialogues(
  animalType: AnimalType,
  currentIndex: number,
  maxPhase: DialoguePhase
): boolean {
  const dialogues = getDialoguesForAnimal(animalType, maxPhase);
  return currentIndex < dialogues.length - 1;
}

/**
 * Get total dialogue count for an animal at current phase
 */
export function getTotalDialogueCount(
  animalType: AnimalType,
  maxPhase: DialoguePhase
): number {
  return getDialoguesForAnimal(animalType, maxPhase).length;
}

// ============================================================================
// PHASE 2 EXHAUSTION POOL
// Phase 2 spans one of the longest single stretches (~33-40 puzzles on the
// compressed arc; it was ~80 before); even with 22
// base lines per animal, chatty players exhaust the block and would re-read
// the last line verbatim for dozens of puzzles. These extra lines are served
// (in order, then cycling) once an animal's Phase-2 base block is exhausted
// while the player is still in Phase 2.
//
// CRITICAL: this pool is deliberately OUTSIDE the indexed base arrays.
// Existing players' lastDialogueRead indices point into ALL_DIALOGUES;
// inserting lines there would shift phase-start indices and corrupt saves.
// Pool lines never name another animal (they are ungated plain strings).
// ============================================================================

